// Project Σ client: the reference consumer of the server API

// Overlay registry bootstrap - must exist before any registerOverlay() calls
// elsewhere in this file. library-mobile.js (loaded after this script) reuses
// this same array via `window._overlayRegistry = window._overlayRegistry || []`.
window._overlayRegistry = window._overlayRegistry || [];
// Replace-by-id: mobile setup re-registers its overlays on every mode
// flip, and duplicate ids would make stale configs race the fresh ones.
window.registerOverlay = window.registerOverlay || function(cfg) {
    const i = window._overlayRegistry.findIndex(r => r.id === cfg.id);
    if (i !== -1) window._overlayRegistry[i] = cfg;
    else window._overlayRegistry.push(cfg);
};
// An overlay that leaves before the page does (a switched-off extension's window).
window.unregisterOverlay = window.unregisterOverlay || function(id) {
    const i = window._overlayRegistry.findIndex(r => r.id === id);
    if (i !== -1) window._overlayRegistry.splice(i, 1);
};

// Detached frontends name a remote server by ?server= (per-device) or window.CL_SERVER; another
// origin waits for the reader's yes (askServerSwitch).
let _serverToConfirm = null;   // { base, fromLink } while a server waits for the reader's answer
const SERVER_BASE = (() => {
    const strip = (b) => String(b || '').replace(/\/+$/, '');
    // only the page's own server goes unasked: a path on this origin is a different server too
    // (/api/proxy/<url> reaches any host the proxy relays to)
    const isOwn = (b) => { try { const u = new URL(b, window.location.href); return u.origin === window.location.origin && u.pathname === '/' && !u.search && !u.hash && !u.username && !u.password; } catch { return false; } };
    const confirmed = () => {
        try { const v = JSON.parse(localStorage.getItem('clServerBase') || 'null'); return v && v.confirmed === true ? strip(v.base) : null; } catch { return null; }
    };
    try {
        const q = new URLSearchParams(window.location.search).get('server');
        if (q === '') { localStorage.removeItem('clServerBase'); return ''; }
        let base;
        if (q) base = strip(q);
        else if (window.CL_SERVER) return strip(window.CL_SERVER);   // the hoster's own choice
        else return confirmed() ?? '';
        if (!base || isOwn(base) || confirmed() === base) {
            localStorage.setItem('clServerBase', JSON.stringify({ base, confirmed: true }));
            return base;
        }
        _serverToConfirm = { base, fromLink: !!q };
        return confirmed() ?? '';
    } catch { return ''; }
})();
const API_BASE = `${SERVER_BASE}/api`;

// A detached page maps its server's /modules/ onto its own before module-loader loads, or
// extension imports load a second, empty core.
(() => {
    let origin;
    try { origin = SERVER_BASE && new URL(SERVER_BASE, window.location.href).origin; } catch { return; }
    if (!origin || origin === window.location.origin) return;
    const map = document.createElement('script');
    map.type = 'importmap';
    map.textContent = JSON.stringify({ imports: { [`${origin}/modules/`]: new URL('modules/', window.location.href).href } });
    document.head.appendChild(map);
})();

/**
 * Asks first at boot about a held-back server on another origin: yes keeps it and reloads, no drops it.
 * @returns {Promise<boolean>} true when the page is reloading onto the accepted server
 */
async function askServerSwitch() {
    const pending = _serverToConfirm;
    if (!pending) return false;
    _serverToConfirm = null;
    // the whole address, path included: a path on this origin can relay to any host (/api/proxy/<url>)
    let address = pending.base;
    try { address = new URL(pending.base, window.location.href).href.replace(/\/+$/, ''); } catch { /* named as given */ }
    const yes = await showConfirm({
        title: 'Use another server?',
        message: `This page wants to use the server at ${address} for your library, your sign-in and the extension code it runs. Continue only if you trust that server.`,
        confirmLabel: 'Use this server',
        cancelLabel: 'Stay here',
        danger: true,
    });
    const here = new URL(window.location.href);
    here.searchParams.delete('server');
    if (yes) {
        localStorage.setItem('clServerBase', JSON.stringify({ base: pending.base, confirmed: true }));
        window.location.replace(here.href);
        return true;
    }
    if (pending.fromLink) window.history.replaceState(null, '', here.href);
    else localStorage.removeItem('clServerBase');
    return false;
}

// Server-served resource path (avatars, thumbs, gallery files) -> absolute
// against the configured server.
function serverUrl(path) {
    return `${SERVER_BASE}${path}`;
}

// This tab's id, on every call so the feed can skip its own; getRandomValues since plain LAN
// HTTP has no randomUUID.
const CL_CLIENT_ID = `tab-${Array.from(crypto.getRandomValues(new Uint8Array(12)), b => b.toString(16).padStart(2, '0')).join('')}`;
let allCharacters = [];
// the id index over the cache: written at the three sites that add to or remove from the array
const _charIndex = new Map();
let currentCharacters = [];

// Virtual scroll state - moved to renderGrid section
let currentScrollHandler = null;

// Edit lock state
let isEditLocked = true;
let originalValues = {};  // Form values for diff comparison
let originalRawData = {}; // Raw character data for cancel/restore
let pendingUpdates = null;
let _saveInProgress = false; // re-entrancy guard for performSave (double-tap Confirm Save)
let _editPanePopulated = false; // Deferred - set true after Edit tab first opened
let editFieldsAutoGrowHandler = null;

// Pending avatar (card image) replacement state: set when user picks a new image in the Edit tab.
let pendingAvatarFile = null;
let pendingAvatarPreviewUrl = null;

// Favorites filter state
let showFavoritesOnly = false;

// ========================================
// SCROLLBAR AUTO-HIDE
// ========================================

(function initScrollbarAutoHide() {
    const HIDE_DELAY = 1500;
    const MOVE_THROTTLE = 250;
    const timers = new WeakMap();

    function showScrollbar(el) {
        el.classList.add('scrollbar-active');
        clearTimeout(timers.get(el));
        timers.set(el, setTimeout(() => el.classList.remove('scrollbar-active'), HIDE_DELAY));
    }

    function isScrollable(el) {
        const s = getComputedStyle(el);
        const oy = s.overflowY, ox = s.overflowX;
        return ((oy === 'auto' || oy === 'scroll') && el.scrollHeight > el.clientHeight)
            || ((ox === 'auto' || ox === 'scroll') && el.scrollWidth > el.clientWidth);
    }

    function findScrollable(el) {
        while (el && el !== document) {
            if (el.nodeType === 1 && isScrollable(el)) return el;
            el = el.parentElement;
        }
        return null;
    }

    document.addEventListener('scroll', (e) => {
        const t = e.target === document ? document.documentElement : e.target;
        if (t && t.nodeType === 1) showScrollbar(t);
    }, { capture: true, passive: true });

    let lastMove = 0;
    document.addEventListener('mousemove', (e) => {
        const now = Date.now();
        if (now - lastMove < MOVE_THROTTLE) return;
        lastMove = now;
        const el = findScrollable(e.target);
        if (el) showScrollbar(el);
    }, { passive: true });
})();

// a bar that takes no width is drawn over the content (Firefox on Windows 11), so the layout keeps a lane for it
(function markOverlayScrollbars() {
    const probe = document.createElement('div');
    probe.style.cssText = 'position:absolute;top:-9999px;width:100px;height:100px;overflow:scroll;';
    document.documentElement.appendChild(probe);
    document.documentElement.classList.toggle('cl-overlay-scrollbars', probe.offsetWidth === probe.clientWidth);
    probe.remove();
})();

// ========================================
// MOBILE MODE
// ========================================

// Reads html.cl-mobile at event time, never cached at attach: the mode flips live.
function isMobileMode() {
    return document.documentElement.classList.contains('cl-mobile');
}

// a scroll's explicit smooth behavior outranks the stylesheet's reduced-motion scroll-behavior, so every scripted scroll asks here
const _reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)');
function scrollBehavior() {
    return _reducedMotion?.matches ? 'auto' : 'smooth';
}

// ========================================
// PERFORMANCE UTILITIES
// ========================================

function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

function truncate(str, max) {
    if (!str) return '';
    return str.length <= max ? str : str.slice(0, max - 3) + '...';
}

// ========================================================================
// CUSTOM SELECT
// ========================================================================

let _customSelectSeq = 0;

// a label around the select holds its options and the trigger too, so only its own words count
function customSelectLabel(select, container) {
    const own = select.getAttribute('aria-label');
    if (own) return own.trim();
    const label = select.labels?.[0];
    if (!label) return '';
    return [...label.childNodes].filter(n => n !== container && !n.contains?.(select))
        .map(n => n.textContent).join(' ').replace(/\s+/g, ' ').trim();
}

// Native <select> is hidden but remains the data model - .value and 'change'
// events work transparently so existing code needs no changes.
function initCustomSelect(select) {
    if (!select || select._customSelect) return null;

    // Capture native value accessor before we override it
    const descriptor = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value');
    const nativeValueSetter = descriptor.set;
    const nativeValueGetter = descriptor.get;

    const isSmall = select.classList.contains('glass-select-small');
    const uid = `cs${++_customSelectSeq}`;

    // Build container
    const container = document.createElement('div');
    container.className = 'custom-select-container';
    if (select.id) container.dataset.selectId = select.id;

    // Transfer non-glass classes from the select (e.g. browse-filter-hidden)
    for (const cls of select.classList) {
        if (cls !== 'glass-select' && cls !== 'glass-select-small') {
            container.classList.add(cls);
        }
    }

    // Trigger button
    const trigger = document.createElement('button');
    trigger.type = 'button';
    trigger.className = `glass-btn custom-select-trigger${isSmall ? ' small' : ''}`;
    if (select.title) trigger.title = select.title;
    trigger.setAttribute('aria-haspopup', 'listbox');
    trigger.setAttribute('aria-expanded', 'false');
    trigger.setAttribute('aria-controls', `${uid}-menu`);
    trigger.innerHTML = `
        <span class="trigger-text"></span>
        <i class="fa-solid fa-chevron-down trigger-arrow"></i>
    `;

    // Dropdown menu (appended to body for fixed positioning)
    const menu = document.createElement('div');
    menu.className = 'dropdown-menu custom-select-menu hidden';
    menu.id = `${uid}-menu`;
    menu.setAttribute('role', 'listbox');
    menu.tabIndex = -1;

    let itemSeq = 0;
    function buildMenu() {
        menu.innerHTML = '';
        itemSeq = 0;
        for (const child of select.children) {
            if (child.tagName === 'OPTGROUP') {
                const title = document.createElement('div');
                title.className = 'dropdown-section-title';
                title.setAttribute('role', 'presentation');
                title.textContent = child.label;
                menu.appendChild(title);
                for (const opt of child.children) {
                    menu.appendChild(createItem(opt));
                }
            } else if (child.tagName === 'OPTION') {
                menu.appendChild(createItem(child));
            }
        }
    }

    function createItem(option) {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'dropdown-item custom-select-item';
        item.dataset.value = option.value;
        item.id = `${uid}-opt-${itemSeq++}`;
        item.setAttribute('role', 'option');
        item.tabIndex = -1;
        item._option = option;

        const isSelected = option.value === nativeValueGetter.call(select);
        if (isSelected) item.classList.add('selected');
        item.setAttribute('aria-selected', String(isSelected));

        if (option.disabled) {
            item.classList.add('disabled');
            item.setAttribute('aria-disabled', 'true');
            if (option.title) item.title = option.title;
        }

        const iconClass = option.dataset.icon;
        const iconUrl = option.dataset.iconUrl;
        let iconHtml = '';
        if (iconUrl) {
            iconHtml = `<img src="${iconUrl}" class="item-icon-img" alt="">`;
        } else if (iconClass) {
            iconHtml = `<i class="${iconClass} item-icon"></i>`;
        }

        item.innerHTML = `${iconHtml}<span>${escapeHtml(option.textContent)}</span>${providerStatusBadgeHtml(option.dataset)}`;

        item.addEventListener('click', (e) => {
            e.stopPropagation();
            pick(option);
        });
        return item;
    }

    // one pick for the click and the keyboard
    function pick(option) {
        if (option.disabled) return;
        nativeValueSetter.call(select, option.value);
        // A native select fires input then change, both bubbling; panels delegating on input went deaf
        // to change alone.
        select.dispatchEvent(new Event('input', { bubbles: true }));
        select.dispatchEvent(new Event('change', { bubbles: true }));
        syncVisuals();
        close();
    }

    function syncVisuals() {
        const selectedOpt = select.options[select.selectedIndex];
        const triggerText = trigger.querySelector('.trigger-text');
        // a label names the trigger with the value after it, so the value stays in the name
        const label = customSelectLabel(select, container);
        if (label) {
            trigger.setAttribute('aria-label', `${label}, ${selectedOpt?.textContent?.trim() ?? ''}`);
            menu.setAttribute('aria-label', label);
        }
        if (triggerText && selectedOpt) {
            trigger.querySelectorAll('.trigger-icon-img, .trigger-icon').forEach(el => el.remove());
            const iconUrl = selectedOpt.dataset.iconUrl;
            const iconClass = selectedOpt.dataset.icon;
            if (iconUrl) {
                const img = document.createElement('img');
                img.src = iconUrl;
                img.className = 'trigger-icon-img';
                img.alt = '';
                trigger.insertBefore(img, triggerText);
            } else if (iconClass) {
                const icon = document.createElement('i');
                icon.className = `${iconClass} trigger-icon`;
                icon.setAttribute('aria-hidden', 'true');
                trigger.insertBefore(icon, triggerText);
            }
            triggerText.textContent = selectedOpt.textContent;
        }
        menu.querySelectorAll('.custom-select-item').forEach(item => {
            const isSelected = item.dataset.value === nativeValueGetter.call(select);
            item.classList.toggle('selected', isSelected);
            item.setAttribute('aria-selected', String(isSelected));
        });
    }

    function positionMenu() {
        const zoom = parseFloat(document.body.style.zoom) || 1;
        const rawRect = trigger.getBoundingClientRect();
        const rect = { left: rawRect.left / zoom, top: rawRect.top / zoom, bottom: rawRect.bottom / zoom, width: rawRect.width / zoom };
        const viewportH = window.innerHeight / zoom;
        const menuHeight = menu.scrollHeight || 200;
        const spaceBelow = viewportH - rect.bottom - 10;
        const spaceAbove = rect.top - 10;

        menu.style.left = rect.left + 'px';
        // Floor at the trigger, but long items (aggregator model ids) widen the menu to the viewport edge.
        const minW = Math.max(rect.width, 180);
        const viewportW = window.innerWidth / zoom;
        menu.style.width = '';
        menu.style.minWidth = minW + 'px';
        menu.style.maxWidth = Math.max(minW, viewportW - rect.left - 10) + 'px';
        // a trigger near the right edge narrower than the floor: the menu moves left rather than run off
        const over = rect.left + menu.offsetWidth - (viewportW - 10);
        if (over > 0) menu.style.left = Math.max(10, rect.left - over) + 'px';

        if (spaceBelow >= menuHeight || spaceBelow >= spaceAbove) {
            menu.style.top = rect.bottom + 4 + 'px';
            menu.style.bottom = '';
            menu.style.maxHeight = Math.min(350, spaceBelow) + 'px';
        } else {
            menu.style.bottom = (viewportH - rect.top + 4) + 'px';
            menu.style.top = '';
            menu.style.maxHeight = Math.min(350, spaceAbove) + 'px';
        }
    }

    let openedAt = 0;
    let openTriggerRect = null;

    function open() {
        document.querySelectorAll('.custom-select-menu:not(.hidden)').forEach(m => {
            if (m !== menu) m.classList.add('hidden');
        });
        TOPBAR_DROPDOWN_IDS.forEach(id => document.getElementById(id)?.classList.add('hidden'));
        window.closeActiveBrowseDropdowns?.();
        menu.classList.remove('hidden');
        trigger.setAttribute('aria-expanded', 'true');
        openedAt = Date.now();
        positionMenu();
        syncVisuals();
        openTriggerRect = trigger.getBoundingClientRect();
        reveal(menu.querySelector('.custom-select-item.selected'));
    }

    // Manual scroll instead of scrollIntoView to avoid ancestor scroll side-effects
    function reveal(item) {
        if (!item) return;
        const itemTop = item.offsetTop;
        const itemBottom = itemTop + item.offsetHeight;
        if (itemTop < menu.scrollTop) menu.scrollTop = itemTop;
        else if (itemBottom > menu.scrollTop + menu.clientHeight) menu.scrollTop = itemBottom - menu.clientHeight;
    }

    // the list keeps the focus and names the row the arrows are on, so no row ever takes the focus
    let activeItem = null;
    function setActive(item) {
        activeItem?.classList.remove('is-active');
        activeItem = item || null;
        if (!activeItem) { menu.removeAttribute('aria-activedescendant'); return; }
        activeItem.classList.add('is-active');
        menu.setAttribute('aria-activedescendant', activeItem.id);
        reveal(activeItem);
    }
    const enabledItems = () => [...menu.querySelectorAll('.custom-select-item:not(.disabled)')];

    function close() {
        menu.classList.add('hidden');
        trigger.setAttribute('aria-expanded', 'false');
        setActive(null);
    }

    function toggle() {
        if (menu.classList.contains('hidden')) open();
        else close();
    }

    buildMenu();
    syncVisuals();

    // Event listeners
    trigger.addEventListener('click', (e) => {
        e.stopPropagation();
        // Decided at click time, not attach time, so a live mode flip switches sheet/menu.
        if (isMobileMode()) {
            window.openSelectorSheetFromSelect?.(select);
            return;
        }
        toggle();
    });

    // a key the list answers stops here: the page's Space and Home/End shortcuts listen on the document
    trigger.addEventListener('keydown', (e) => {
        if (isMobileMode() || !['ArrowDown', 'ArrowUp', 'Enter', ' '].includes(e.key)) return;
        e.preventDefault();
        e.stopPropagation();
        const wasOpen = !menu.classList.contains('hidden');
        if (wasOpen && (e.key === 'Enter' || e.key === ' ')) { close(); return; }
        if (!wasOpen) open();
        const items = enabledItems();
        const chosen = items.find(i => i.classList.contains('selected'));
        setActive(chosen || (e.key === 'ArrowUp' ? items[items.length - 1] : items[0]));
        menu.focus({ preventScroll: true });
    });
    menu.addEventListener('keydown', (e) => {
        if (menu.classList.contains('hidden')) return;
        const items = enabledItems();
        const at = items.indexOf(activeItem);
        if (e.key === 'ArrowDown') setActive(items[Math.min(at + 1, items.length - 1)]);
        else if (e.key === 'ArrowUp') setActive(items[at < 0 ? items.length - 1 : Math.max(at - 1, 0)]);
        else if (e.key === 'Home') setActive(items[0]);
        else if (e.key === 'End') setActive(items[items.length - 1]);
        else if (e.key === 'Enter' || e.key === ' ') {
            if (activeItem?._option) pick(activeItem._option);
            trigger.focus();
        } else if (e.key === 'Escape') {
            close();
            trigger.focus();
        } else if (e.key === 'Tab') {
            // the focus goes back to the trigger and the Tab carries on from there
            close();
            trigger.focus();
            return;
        } else return;
        e.preventDefault();
        e.stopPropagation();
    });

    const onWindowClick = (e) => {
        if (!menu.classList.contains('hidden') && !container.contains(e.target) && !menu.contains(e.target)) {
            close();
        }
    };
    window.addEventListener('click', onWindowClick);

    // Close on scroll - only if the trigger's viewport position actually changed
    // (avoids false closes from unrelated scrolls behind fixed-position modals)
    const onWindowScroll = (e) => {
        if (menu.classList.contains('hidden') || e.target === menu || Date.now() - openedAt <= 150) return;
        if (!openTriggerRect) { close(); return; }
        const r = trigger.getBoundingClientRect();
        if (Math.abs(r.top - openTriggerRect.top) > 1 || Math.abs(r.left - openTriggerRect.left) > 1) close();
    };
    window.addEventListener('scroll', onWindowScroll, true);

    const onWindowKeydown = (e) => {
        if (e.key === 'Escape' && !menu.classList.contains('hidden')) {
            close();
        }
    };
    window.addEventListener('keydown', onWindowKeydown);
    // a select that a rebuild throws away takes its menu and its window listeners with it
    const destroy = () => {
        window.removeEventListener('click', onWindowClick);
        window.removeEventListener('scroll', onWindowScroll, true);
        window.removeEventListener('keydown', onWindowKeydown);
        menu.remove();
        delete select._customSelect;
    };

    // DOM assembly
    container.appendChild(trigger);
    // Menus live on body, so a select destroyed by a re-render strands its menu; sweep the orphans
    // at the next init.
    document.querySelectorAll('.custom-select-menu').forEach(m => {
        if (m._ownerSelect && !m._ownerSelect.isConnected) (m._ownerSelect._customSelect?.destroy || (() => m.remove()))();
    });
    menu._ownerSelect = select;
    document.body.appendChild(menu);

    select.parentNode.insertBefore(container, select);
    select.hidden = true;

    // Lock the trigger to the widest option so it doesnt resize on pick; fluid selects skip it
    const triggerText = trigger.querySelector('.trigger-text');
    const skipWidthLock = select.closest('.browse-sort-container') || select.classList.contains('cl-select-fluid');
    function lockTriggerWidth() {
        if (skipWidthLock || trigger.style.minWidth) return;
        let maxW = 0;
        const original = triggerText.textContent;
        for (const opt of select.options) {
            triggerText.textContent = opt.textContent;
            maxW = Math.max(maxW, trigger.scrollWidth);
        }
        triggerText.textContent = original;
        if (maxW > 0) trigger.style.minWidth = maxW + 'px';
    }
    // a trigger already laid out locks in this task, so no frame paints it at its unlocked width
    function lockWhenShown() {
        if (trigger.getClientRects().length) { lockTriggerWidth(); return; }
        const obs = new IntersectionObserver((entries) => {
            if (entries[0].isIntersecting) {
                lockTriggerWidth();
                obs.disconnect();
            }
        });
        obs.observe(trigger);
    }
    lockWhenShown();

    // A mode flip invalidates the locked width (measured under the old layout): re-measured in the same task
    function relockWidth() {
        if (skipWidthLock) return;
        trigger.style.minWidth = '';
        lockWhenShown();
    }

    // Intercept .value to keep visuals in sync
    Object.defineProperty(select, 'value', {
        get() { return nativeValueGetter.call(this); },
        set(val) {
            nativeValueSetter.call(this, val);
            syncVisuals();
        },
        configurable: true
    });

    // Public API stored on the select element
    select._customSelect = { container, trigger, menu, open, close, toggle, relockWidth, destroy, refresh() { buildMenu(); setActive(null); syncVisuals(); }, update: syncVisuals };

    return container;
}

function initAllCustomSelects() {
    document.querySelectorAll('.glass-select, .glass-select-small').forEach(select => {
        initCustomSelect(select);
    });
}

// ========================================
// BARS THAT KEEP WHAT FITS
// A bar whose entries can outgrow it (an extension's verbs, views, tabs, window openers)
// keeps the ones that fit, in order, and collapses the rest behind a More that lists them,
// labelled, built from the collapsed entries themselves at open. Never a sideways scroll,
// never a clip. The cutoff is measured, so it is exact at any width, zoom or UI scale.
// ========================================

const FIT_COLLAPSED = 'cl-overflowed';
const FIT_LIFTED = 'cl-overflow-lifted';
const _fitRows = new Set();
const _fitQueued = new Set();
let _fitObserver = null;

/**
 * Keep a row of entries to what fits beside its More.
 * @param {HTMLElement} row the box the entries share; its width comes from its container (min-width: 0), never from them
 * @param {object} spec
 * @param {() => HTMLElement[]} spec.entries the collapsible entries in the order they keep their place; the rest of the row never collapses
 * @param {HTMLElement} spec.more the More button, inside or beside the row; hidden while everything fits
 * @param {(el: HTMLElement) => boolean} [spec.always] an entry that lives behind the More at any width
 * @param {string} [spec.current] a collapsed entry matching this lights the More (is-current)
 * @param {string} [spec.marked] a collapsed entry matching this puts its dot on the More (is-marked)
 * @param {string} [spec.working] a collapsed entry matching this shows the More working (is-working)
 * @param {string} [spec.separators] dividers in the row that hide when nothing shows on one side
 * @param {boolean} [spec.watch] refit on its own when an entry changes size or the row's controls are rebuilt
 * @param {(el: HTMLElement) => string} [spec.label] the words a collapsed control's row reads; overflowLabel when absent
 */
function fitRow(row, spec) {
    if (!row || !spec?.more || typeof spec.entries !== 'function') return;
    row._fit = spec;
    spec.more.dataset.overflowMore = '';
    spec.more.setAttribute('aria-haspopup', 'menu');
    if (!spec.more._fitWired) {
        spec.more._fitWired = true;
        spec.more.addEventListener('click', (e) => openRowOverflow(row, e));
    }
    if (!_fitObserver && typeof ResizeObserver === 'function') {
        _fitObserver = new ResizeObserver((entries) => {
            for (const { target } of entries) {
                // the parent is watched too: a row sized by its content never grows by itself
                const rows = target._fit ? [target] : target._fitOwner ? [target._fitOwner] : [..._fitRows].filter(x => x.parentElement === target);
                rows.forEach(queueRowFit);
            }
        });
        document.addEventListener('cl-mobile-mode-change', () => _fitRows.forEach(r => { if (r.isConnected) fitRowNow(r); }));
    }
    if (_fitObserver && !_fitRows.has(row)) {
        _fitObserver.observe(row);
        if (row.parentElement) _fitObserver.observe(row.parentElement);
    }
    // an entry lit, marked or working by its own surface shows on the More while collapsed, whoever
    // changed it
    if ((spec.current || spec.marked || spec.working) && !row._fitMarks && typeof MutationObserver === 'function') {
        row._fitMarks = new MutationObserver(() => syncRowMore(row));
        row._fitMarks.observe(row, { attributes: true, attributeFilter: ['class'], subtree: true });
    }
    // controls rebuilt or relabelled refit the row; what a control's own dropdown holds never does
    if (spec.watch && !row._fitRebuilds && typeof MutationObserver === 'function') {
        row._fitRebuilds = new MutationObserver((records) => {
            if (records.some(r => !r.target.closest?.('.dropdown-menu'))) queueRowFit(row);
        });
        row._fitRebuilds.observe(row, { childList: true, subtree: true });
    }
    _fitRows.add(row);
    fitRowNow(row);
}

function queueRowFit(row) {
    if (_fitQueued.has(row)) return;
    _fitQueued.add(row);
    requestAnimationFrame(() => { _fitQueued.delete(row); if (row.isConnected && row._fit) fitRowNow(row); });
}

// a watched row hears its entries resize: a label that grows can push the row past its box
function watchRowEntries(row, all) {
    if (!_fitObserver) return;
    const watched = row._fitWatched || (row._fitWatched = new Set());
    for (const el of watched) if (!all.includes(el)) { _fitObserver.unobserve(el); watched.delete(el); }
    for (const el of all) if (!watched.has(el)) { el._fitOwner = row; _fitObserver.observe(el); watched.add(el); }
}

/** Refit a row now, after its entries changed (one joined or left, a label grew). */
function refitRow(row) {
    if (row?._fit) fitRowNow(row);
}

function fitRowNow(row) {
    const { entries, more, always, separators, watch } = row._fit;
    const all = entries().filter(Boolean);
    if (row._fitLifted && !all.includes(row._fitLifted)) dropRowLift(row);
    if (watch) watchRowEntries(row, all);
    // the bar holds still while a surface opened from its More is up; it refits once that closes
    if (row._fitLifted) return;
    all.forEach(el => el.classList.remove(FIT_COLLAPSED));
    more.classList.add(FIT_COLLAPSED);
    // an entry its own surface hid (a verb that does not apply, a window the reader hid) takes no part
    const live = all.filter(el => el.getClientRects().length);
    const syncSeparators = () => {
        if (!separators) return;
        let seen = false, pending = null;
        for (const k of row.children) {
            if (k.matches(separators)) {
                k.classList.add(FIT_COLLAPSED);
                if (seen) pending = k;
            } else if (k !== more && k.getClientRects().length) {
                if (pending) { pending.classList.remove(FIT_COLLAPSED); pending = null; }
                seen = true;
            }
        }
    };
    syncSeparators();
    const over = () => row.scrollWidth > row.clientWidth;
    // a hidden row fits nothing, the observer refits it when it shows; one squeezed to no width fits nothing either
    if (row.getClientRects().length) {
        const pinned = always ? live.filter(el => always(el)) : [];
        pinned.forEach(el => el.classList.add(FIT_COLLAPSED));
        if (pinned.length || over()) {
            more.classList.remove(FIT_COLLAPSED);
            syncSeparators();
            for (let i = live.length - 1; i >= 0 && over(); i--) {
                live[i].classList.add(FIT_COLLAPSED);
                syncSeparators();
            }
        }
    }
    syncRowMore(row);
}

function syncRowMore(row) {
    const { entries, more, current, marked, working } = row._fit;
    const collapsed = entries().filter(el => el?.classList.contains(FIT_COLLAPSED));
    more.classList.toggle('is-current', !!current && collapsed.some(el => el.matches(current)));
    more.classList.toggle('is-marked', !!marked && collapsed.some(el => el.matches(marked)));
    more.classList.toggle('is-working', !!working && collapsed.some(el => el.matches(working)));
}

/**
 * Keeps a list inside the viewport: taller than the room under it, it scrolls (extension verbs
 * grow any list without bound).
 */
function fitListToViewport(el, pad = 12) {
    el.style.maxHeight = '';
    const zoom = parseFloat(document.body.style.zoom) || 1;
    const room = (window.innerHeight - el.getBoundingClientRect().top) / zoom - pad;
    el.style.maxHeight = `${Math.max(120, Math.floor(room))}px`;
    el.style.overflowY = 'auto';
}

function overflowLabel(el) {
    return (el.dataset.overflowLabel || el.getAttribute('aria-label') || el.getAttribute('title') || el.textContent || '').trim().replace(/\s+/g, ' ');
}

// An entry that is no control itself (a segmented pair, a select, a dropdown's host) stands for the
// controls it shows
function rowControls(entry) {
    const PRESSABLE = 'button, [role="button"]';
    if (entry.matches(PRESSABLE)) return [entry];
    const hiddenIn = (c) => { const h = c.closest('[hidden], .hidden'); return !!h && entry.contains(h); };
    const shown = [...entry.querySelectorAll(PRESSABLE)].filter(c => !c.closest('.dropdown-menu') && !hiddenIn(c) && getComputedStyle(c).visibility !== 'hidden');
    return shown.length ? shown : [entry];
}

// A control that opens a list or a dropdown stands unseen in the More's place while open: it opens
// from the More
function liftRowEntry(row, entry) {
    dropRowLift(row);
    row._fitLifted = entry;
    entry.classList.replace(FIT_COLLAPSED, FIT_LIFTED);
    Object.assign(entry.style, { position: 'absolute', right: '0px', top: '0px' });
    const zoom = parseFloat(document.body.style.zoom) || 1;
    const at = entry.getBoundingClientRect(), door = row._fit.more.getBoundingClientRect();
    entry.style.right = `${(at.right - door.right) / zoom}px`;
    entry.style.top = `${(door.top - at.top) / zoom}px`;
    const away = (e) => { if (e.type === 'keydown' ? e.key === 'Escape' : !entry.contains(e.target)) dropRowLift(row); };
    document.addEventListener('pointerdown', away, true);
    document.addEventListener('keydown', away, true);
    row._fitLiftOff = () => { document.removeEventListener('pointerdown', away, true); document.removeEventListener('keydown', away, true); };
}

function dropRowLift(row) {
    const entry = row._fitLifted;
    if (!entry) return;
    row._fitLifted = null;
    row._fitLiftOff?.();
    row._fitLiftOff = null;
    entry.classList.replace(FIT_LIFTED, FIT_COLLAPSED);
    for (const k of ['position', 'right', 'top']) entry.style.removeProperty(k);
    queueRowFit(row);
}

function pressFromMore(row, entry, control) {
    if (!control.hasAttribute('aria-haspopup') && !entry.querySelector('.dropdown-menu')) { control.click(); return; }
    liftRowEntry(row, entry);
    // pressed once the click that chose it has run its course, so that click cannot close what it opens
    setTimeout(() => control.click(), 0);
}

// The More's list is the context menu's; each row presses a collapsed control, so the control's own
// handler runs.
function openRowOverflow(row, e) {
    const menu = window.ModuleLoader?.get('context-menu');
    dropRowLift(row);
    const collapsed = row._fit.entries().filter(el => el?.classList.contains(FIT_COLLAPSED));
    if (!menu?.showItems || !collapsed.length) return;
    const label = row._fit.label || overflowLabel;
    const items = [];
    let group = null, wasSet = false;
    for (const el of collapsed) {
        const g = el.dataset.overflowGroup || null;
        const controls = rowControls(el);
        const isSet = controls.length > 1;
        if (g && g !== group) items.push({ type: 'header', label: g });
        // a set of controls (a segmented pair) sits between rules of its own
        else if (items.length && (isSet || wasSet)) items.push({ type: 'separator' });
        group = g;
        wasSet = isSet;
        for (const c of controls) {
            const icon = [...(c.querySelector('i')?.classList || [])].filter(k => k.startsWith('fa')).join(' ');
            items.push({ icon: icon || 'fa-solid fa-circle', label: label(c), className: c.matches('.active, [aria-pressed="true"]') ? 'is-current' : '', action: () => pressFromMore(row, el, c) });
        }
    }
    const r = e.currentTarget.getBoundingClientRect();
    menu.showItems(e, items, { x: r.left, y: r.bottom });
}


function prepareCharacterKeys(chars) {
    for (let i = 0; i < chars.length; i++) {
        const c = chars[i];
        if (!c) continue;
        // Normalize name to root level (some chars store it only in data.name)
        if (!c.name) c.name = c.data?.name || c.definition?.name || 'Unknown';
        // The server maintains the estimate as a column; list items carry it. Local
        // computation only covers objects that never came through the list mapping.
        if (typeof c.tokenEstimate === 'number') {
            c._tokenEstimate = c.tokenEstimate;
            _tokenEstimateCache.set(c.id, c._tokenEstimate);
        } else {
            c._tokenEstimate = computeTokenEstimate(c);
            _tokenEstimateCache.set(c.id, c._tokenEstimate);
        }
    }
}

