// Keep in step with the engine (rule-filters.js, by builder arity): a missing op draws a value box
// and drops the rule as inactive.
const ADV_FILTER_NO_VALUE_OPS = new Set([
    'is_empty', 'is_not_empty', 'is_true', 'is_false', 'is_linked', 'is_not_linked', 'ever', 'never', 'in_any', 'not_in_any',
    'has_override', 'no_override', 'set_to_card', 'set_to_listing', 'is_set', 'is_not_set',
]);

// Read per call so a provider registered after boot joins the dropdown.
function advFilterProviders() {
    return Object.entries(PROVIDER_MANIFEST)
        .map(([value, p]) => ({ value, label: p.advLabel || p.name }));
}

// ========================================
// FILTER PRESETS
// ========================================

// { version, char: [{ uid, name, rules, removed? }], chat: [...] }; a document without a version
// (or never created) is the empty one
function coerceFilterPresets(data) {
    const doc = data && data.version ? data : { version: 1 };
    return { ...doc, char: Array.isArray(doc.char) ? doc.char : [], chat: Array.isArray(doc.chat) ? doc.chat : [] };
}

// the server writes it too (a tag or lorebook renamed or deleted); a write elsewhere drops the
// copy, read again before the next write
const filterPresetsDoc = createStoreDocument('filter-presets', {
    coerce: coerceFilterPresets,
    unread: 'Filter presets could not be read from the server; not saving over them',
    saveFailed: 'Failed to save filter presets',
});

function loadFilterPresets() {
    return filterPresetsDoc.load();
}

function getFilterPresets() {
    const key = currentView === 'chats' ? 'chat' : 'char';
    return filterPresetsDoc.get()?.[key] || [];
}

function _generateFilterPresetUid() {
    const existing = getFilterPresets();
    let uid;
    do { uid = randomId(10); } while (existing.some(p => p.uid === uid));
    return uid;
}

async function saveCurrentAsFilterPreset(name) {
    name = (name || '').trim();
    if (!name) return;
    const rules = getAdvFilterRules();
    const activeRules = rules.filter(r => ADV_FILTER_NO_VALUE_OPS.has(r.operator) || !!r.value);
    if (activeRules.length === 0) { showToast('No active filters to save', 'warning'); return; }
    const doc = await loadFilterPresets();
    if (filterPresetsDoc.unavailable()) return;
    const key = currentView === 'chats' ? 'chat' : 'char';
    const nameLower = name.toLowerCase();
    if (doc[key].some(p => p.name.toLowerCase() === nameLower)) {
        showToast(`A preset named "${name}" already exists`, 'warning');
        return;
    }
    const serialized = activeRules.map(({ field, operator, value }) => ({ field, operator, value }));
    doc[key].push({ uid: _generateFilterPresetUid(), name, rules: serialized });
    rerenderAdvFilterPresets();
    if (!await filterPresetsDoc.save()) {
        // a write that did not land dropped the copy: the list shows the presets the server holds, the typed name kept
        await loadFilterPresets();
        rerenderAdvFilterPresets();
        return;
    }
    const input = document.getElementById('advFilterPresetNameInput');
    if (input) input.value = '';
    rerenderAdvFilterPresets();
    showToast(`Preset "${name}" saved`, 'success', 2000);
}

async function applyFilterPreset(uid, opts = {}) {
    await loadFilterPresets();
    const preset = getFilterPresets().find(p => p.uid === uid);
    if (!preset) return null;
    setAdvFilterRules(preset.rules.map(r => ({ ...r, id: advFilterNextId++ })));
    // the preset keeps a rule on an extension that went off; the live rules do not
    if (currentView !== 'chats') pruneExtensionAdvRules();
    rerenderAdvFilterRows();
    updateAdvFilterIndicator();
    // the boot seed runs BEFORE the first grid query, so firing one here would paint the
    // unfiltered library first and then snap to the filter
    if (!opts.seedOnly) triggerAdvFilterSearch();
    if (!opts.silent) {
        closeAdvFilterPresetsPanel();
        showToast(`Loaded "${preset.name}"`, 'success', 2000);
    }
    // a tag deleted since took its rules out of the preset on the server: said once, the boot's seed included, then the note goes
    const removed = Array.isArray(preset.removed) ? preset.removed : [];
    if (removed.length) {
        const tags = [...new Set(removed.map(r => r.value))];
        showToast(`Preset "${preset.name}" no longer filters on ${tags.map(t => `"${t}"`).join(', ')}: ${tags.length === 1 ? 'that tag was' : 'those tags were'} deleted`, 'warning', 8000);
        delete preset.removed;
        void filterPresetsDoc.save();
    }
    return preset;
}

async function deleteFilterPreset(uid) {
    const doc = await loadFilterPresets();
    if (filterPresetsDoc.unavailable()) return;
    const key = currentView === 'chats' ? 'chat' : 'char';
    doc[key] = doc[key].filter(p => p.uid !== uid);
    rerenderAdvFilterPresets();
    // a write that did not land dropped the copy: the list shows the presets the server holds
    if (!await filterPresetsDoc.save()) {
        await loadFilterPresets();
        rerenderAdvFilterPresets();
    }
}

function toggleAdvFilterPresetsPanel() {
    const panel = document.getElementById('advFilterPresetsPanel');
    if (!panel) return;
    if (panel.classList.contains('hidden')) openAdvFilterPresetsPanel();
    else closeAdvFilterPresetsPanel();
}

function openAdvFilterPresetsPanel() {
    loadFilterPresets().then(() => {
        rerenderAdvFilterPresets();
        document.getElementById('advFilterPresetsPanel')?.classList.remove('hidden');
        document.getElementById('advFilterPresetsBtn')?.classList.add('active');
        if (!isMobileMode()) {
            setTimeout(() => document.getElementById('advFilterPresetNameInput')?.focus(), 50);
        }
    });
}

function closeAdvFilterPresetsPanel() {
    document.getElementById('advFilterPresetsPanel')?.classList.add('hidden');
    document.getElementById('advFilterPresetsBtn')?.classList.remove('active');
}

function rerenderAdvFilterPresets() {
    const list = document.getElementById('advFilterPresetsList');
    if (!list) return;
    const query = (document.getElementById('advFilterPresetNameInput')?.value || '').trim().toLowerCase();
    const presets = getFilterPresets();
    const filtered = query ? presets.filter(p => p.name.toLowerCase().includes(query)) : presets;
    if (filtered.length === 0) {
        list.innerHTML = presets.length === 0
            ? `<div class="adv-filter-presets-empty">No saved presets</div>`
            : `<div class="adv-filter-presets-empty">No match</div>`;
        return;
    }
    list.innerHTML = filtered.map(p => `<div class="adv-filter-preset-item">
        <button class="adv-filter-preset-load" data-uid="${escapeHtml(p.uid)}">
            <i class="fa-regular fa-bookmark"></i>
            <span>${escapeHtml(p.name)}</span>
        </button>
        <button class="adv-filter-preset-delete" data-uid="${escapeHtml(p.uid)}" title="Delete">
            <i class="fa-solid fa-xmark"></i>
        </button>
    </div>`).join('');
}

let charAdvFilterRules = [];
let chatAdvFilterRules = [];
let advFilterNextId = 1;

function getAdvFilterRules() {
    return currentView === 'chats' ? chatAdvFilterRules : charAdvFilterRules;
}

function setAdvFilterRules(rules) {
    if (currentView === 'chats') chatAdvFilterRules = rules;
    else charAdvFilterRules = rules;
}

// Rule fields naming a tag or lorebook, twins of the server's PRESET_TAG_FIELDS and PRESET_LOREBOOK_FIELDS
// (a rename or delete rewrites saved presets).
const ADV_TAG_RULE_FIELDS = Object.freeze(['tags', 'charTags']);
const ADV_LOREBOOK_RULE_FIELDS = Object.freeze(['linkedLorebook', 'chatLorebook']);

/**
 * Carries the live rules of both views across a rename or delete, as the server carried the saved
 * presets; answers whether any moved.
 * @param {string[]} fields
 * @param {(value: string) => string|null} map
 * @returns {boolean}
 */
function remapAdvFilterRules(fields, map) {
    let moved = false;
    const remap = (rules) => rules.flatMap((rule) => {
        if (!fields.includes(rule.field) || typeof rule.value !== 'string') return [rule];
        const to = map(rule.value);
        if (to === rule.value) return [rule];
        moved = true;
        return to ? [{ ...rule, value: to }] : [];
    });
    charAdvFilterRules = remap(charAdvFilterRules);
    chatAdvFilterRules = remap(chatAdvFilterRules);
    if (moved) {
        rerenderAdvFilterRows();
        updateAdvFilterIndicator();
    }
    return moved;
}

// A rename as the filter engine and the server's preset rewrite match a name: SQLite's NOCASE, ASCII letters folded
function renamedName(oldName, newName) {
    const fold = (s) => String(s).replace(/[A-Z]/g, c => c.toLowerCase());
    return (value) => (fold(value) === fold(oldName) ? newName : value);
}

function getActiveAdvFilterFields() {
    return currentView === 'chats' ? CHAT_ADV_FILTER_FIELDS : { ...ADV_FILTER_FIELDS, ...extensionAdvFilterFields() };
}

// The rule fields of the extensions this account has on, keyed as the engine names them
// (ext.<id>.<key>), with the ops the server answers for each.
function extensionAdvFilterFields() {
    const out = {};
    for (const f of extensionQueryDoors().ruleFields) out[f.field] = { label: f.label, type: f.type, operators: f.ops, extName: f.extName };
    return out;
}

function triggerAdvFilterSearch() {
    // a rule change is a QUERY change on the chats view: the server filters
    if (currentView === 'chats') window.chatsModule?.loadAllChats?.();
    else performSearch();
}

// a typed rule value waits like the search box (searchWaitMs): contains on prose is the dearest
// scan, and a flat wait queried each prefix
const _advFilterRhythm = makeTypingRhythm();
let _advFilterTypeTimer = null;
function scheduleAdvFilterSearch(value) {
    const gap = _advFilterRhythm.tick();
    clearTimeout(_advFilterTypeTimer);
    _advFilterTypeTimer = setTimeout(triggerAdvFilterSearch, searchWaitMs(String(value ?? '').trim().length, gap));
}

function toggleAdvFilterPanel() {
    const panel = document.getElementById('advFilterPanel');
    if (!panel) return;
    const isHidden = panel.classList.contains('hidden');
    closeAllTopbarDropdowns('advFilterPanel');
    if (isHidden) {
        panel.classList.remove('hidden');
        if (getAdvFilterRules().length === 0) addAdvFilterRule();
        keepAdvFilterPanelInView(panel);
    } else {
        panel.classList.add('hidden');
    }
}

// the panel's floor is wider than a narrow search box, so a box the topbar pushed right would carry it past the window
function keepAdvFilterPanelInView(panel) {
    panel.style.left = '';
    if (isMobileMode()) return;
    const zoom = parseFloat(document.body.style.zoom) || 1;
    const over = panel.getBoundingClientRect().right / zoom - (window.innerWidth / zoom - 10);
    if (over > 0) panel.style.left = `${-over}px`;
}

function closeAdvFilterPanel() {
    document.getElementById('advFilterPanel')?.classList.add('hidden');
    closeAdvFilterPresetsPanel();
}

function addAdvFilterRule() {
    const fields = getActiveAdvFilterFields();
    const firstField = Object.keys(fields)[0];
    const rule = {
        id: advFilterNextId++,
        field: firstField,
        operator: fields[firstField].operators[0],
        value: '',
    };
    rule.value = getAdvFilterDefaultValue(rule);
    getAdvFilterRules().push(rule);
    rerenderAdvFilterRows();
    updateAdvFilterIndicator();
}

// Ops with a displayed default (7 days, first provider, first playlist) seed the stored value, or
// the compiler skips the rule as empty.
function getAdvFilterDefaultValue(rule) {
    if (rule.operator === 'in_the_last') return '7';
    const fieldDef = getActiveAdvFilterFields()[rule.field];
    if (!fieldDef) return '';
    if (fieldDef.type === 'provider' && (rule.operator === 'linked_to' || rule.operator === 'not_linked_to')) {
        return advFilterProviders()[0]?.value || '';
    }
    if (fieldDef.type === 'playlist' && (rule.operator === 'in' || rule.operator === 'not_in')) {
        return (window.playlistsGetAll?.() || [])[0]?.uid || '';
    }
    return '';
}

function removeAdvFilterRule(id) {
    setAdvFilterRules(getAdvFilterRules().filter(r => r.id !== id));
    updateAdvFilterIndicator();
    rerenderAdvFilterRows();
    triggerAdvFilterSearch();
}

function clearAllAdvFilters() {
    setAdvFilterRules([]);
    updateAdvFilterIndicator();
    rerenderAdvFilterRows();
    triggerAdvFilterSearch();
}

function updateAdvFilterIndicator() {
    const btn = document.getElementById('advFilterBtn');
    if (!btn) return;
    const hasActive = getAdvFilterRules().some(r =>
        ADV_FILTER_NO_VALUE_OPS.has(r.operator) ? true : !!r.value
    );
    btn.classList.toggle('has-filters', hasActive);
}

function rerenderAdvFilterRows() {
    const container = document.getElementById('advFilterRows');
    if (!container) return;
    const rules = getAdvFilterRules();
    if (rules.length === 0) {
        container.innerHTML = '';
        return;
    }
    container.innerHTML = rules.map((rule, idx) => buildAdvFilterRowHtml(rule, idx)).join('');
}

function buildAdvFilterRowHtml(rule, idx) {
    const fields = getActiveAdvFilterFields();
    // A saved preset can name a field this build doesnt offer; the engine still knows it, so the rule
    // renders as saved, never rewritten.
    const retired = !fields[rule.field];
    const fieldDef = fields[rule.field] || { label: rule.field, operators: [rule.operator], type: 'text' };
    const connector = idx === 0 ? 'Where' : 'and';

    const option = ([k, f]) => `<option value="${escapeHtml(k)}"${k === rule.field ? ' selected' : ''}>${escapeHtml(f.label)}</option>`;
    // an extension's fields follow the app's, one group per extension
    const byExt = new Map();
    for (const entry of Object.entries(fields)) {
        if (!entry[1].extName) continue;
        if (!byExt.has(entry[1].extName)) byExt.set(entry[1].extName, []);
        byExt.get(entry[1].extName).push(entry);
    }
    const fieldOptions = (retired ? [`<option value="${escapeHtml(rule.field)}" selected>${escapeHtml(rule.field)} (Retired)</option>`] : [])
        .concat(Object.entries(fields).filter(([, f]) => !f.extName).map(option))
        .concat([...byExt].map(([name, entries]) => `<optgroup label="${escapeHtml(name)}">${entries.map(option).join('')}</optgroup>`))
        .join('');

    const opOptions = fieldDef.operators
        .map(op => `<option value="${op}"${op === rule.operator ? ' selected' : ''}>${escapeHtml(ADV_FILTER_OP_LABELS[op] || op)}</option>`)
        .join('');

    const valueHtml = buildAdvFilterValueHtml(rule, fieldDef);

    return `<div class="adv-filter-row" data-rule-id="${rule.id}">
        <span class="adv-filter-connector">${connector}</span>
        <select class="adv-filter-field" data-rule-id="${rule.id}">${fieldOptions}</select>
        <select class="adv-filter-operator" data-rule-id="${rule.id}">${opOptions}</select>
        ${valueHtml}
        <button class="adv-filter-remove" data-rule-id="${rule.id}" title="Remove"><i class="fa-solid fa-xmark"></i></button>
    </div>`;
}

function buildAdvFilterValueHtml(rule, fieldDef) {
    if (ADV_FILTER_NO_VALUE_OPS.has(rule.operator)) return '';

    if (rule.operator === 'in_the_last') {
        return `<div class="adv-filter-value">
            <input type="number" class="adv-filter-input" data-rule-id="${rule.id}" min="1" value="${escapeHtml(rule.value || '7')}">
            <span class="adv-filter-unit">days</span>
        </div>`;
    }

    if (rule.operator === 'before' || rule.operator === 'after') {
        return `<div class="adv-filter-value">
            <input type="date" class="adv-filter-input" data-rule-id="${rule.id}" value="${escapeHtml(rule.value || '')}">
        </div>`;
    }

    if (fieldDef.type === 'number') {
        return `<div class="adv-filter-value">
            <input type="number" class="adv-filter-input" data-rule-id="${rule.id}" min="0" value="${escapeHtml(rule.value || '')}" placeholder="0">
        </div>`;
    }

    if (fieldDef.type === 'provider') {
        const providers = advFilterProviders();
        const opts = providers
            .map(p => `<option value="${p.value}"${p.value === (rule.value || providers[0]?.value) ? ' selected' : ''}>${escapeHtml(p.label)}</option>`)
            .join('');
        return `<div class="adv-filter-value"><select class="adv-filter-input" data-rule-id="${rule.id}">${opts}</select></div>`;
    }

    if (fieldDef.type === 'playlist') {
        const playlists = window.playlistsGetAll?.() || [];
        const opts = playlists
            .map(pl => `<option value="${escapeHtml(pl.uid)}"${pl.uid === rule.value ? ' selected' : ''}>${escapeHtml(pl.name)}</option>`)
            .join('');
        return `<div class="adv-filter-value"><select class="adv-filter-input" data-rule-id="${rule.id}">${opts}</select></div>`;
    }

    return `<div class="adv-filter-value">
        <input type="search" class="adv-filter-input" data-rule-id="${rule.id}" value="${escapeHtml(rule.value || '')}" placeholder="Value..." autocomplete="off">
    </div>`;
}




function getAdvFilterRulesForChats() {
    return chatAdvFilterRules;
}

// ========================================================================
// Search and Filter Functionality (global, called from view switching)
// THIN-CLIENT GRID QUERY: the whole view state compiles to server query params, one engine.
// ========================================================================

const GRID_SORT_MAP = {
    name_asc: { sort: 'name', order: 'asc' },
    name_desc: { sort: 'name', order: 'desc' },
    // date_* is the library's own stamp (when the card was added); the values predate the modified
    // sort and stay for saved choices
    date_new: { sort: 'imported', order: 'desc' },
    date_old: { sort: 'imported', order: 'asc' },
    modified_new: { sort: 'updated', order: 'desc' },
    modified_old: { sort: 'updated', order: 'asc' },
    created_new: { sort: 'created', order: 'desc' },
    created_old: { sort: 'created', order: 'asc' },
    tokens_high: { sort: 'tokens', order: 'desc' },
    tokens_low: { sort: 'tokens', order: 'asc' },
    random: { sort: 'name', order: 'asc', shuffle: true }, // presentation shuffle after fetch
};

// ========================================
// EXTENSION SORTS AND FILTER FIELDS
// ========================================
// An extension the account has on may answer sorts and filter fields of its own (its server
// half's query doors, listed in the inventory). They join the sort select and the advanced
// filter while it stays on, and a sort or a rule of one that went off is dropped rather than
// sent, since the server would refuse it.
function extensionQueryDoors() {
    return window.ExtensionHost?.getQueryDoors?.() || { known: false, sortKeys: [], ruleFields: [] };
}

// a sort select value for an extension's key: ext:<sort>:<order>, the sort ext.<id>.<key>
function extensionSortOf(value) {
    const m = /^ext:(ext\.[a-z0-9][a-z0-9-]*\.[a-z][a-zA-Z0-9_]*):(asc|desc)$/.exec(String(value || ''));
    if (!m || !extensionQueryDoors().sortKeys.some(s => s.sort === m[1])) return null;
    return { sort: m[1], order: m[2] };
}

function gridSortOf(value) {
    return GRID_SORT_MAP[value] || extensionSortOf(value) || GRID_SORT_MAP.name_asc;
}

// The extensions' sorts after the app's, a group per extension; a select left on a gone one falls
// back to the default.
function syncExtensionSortOptions() {
    const select = document.getElementById('sortSelect');
    if (!select) return;
    const was = select.value;
    select.querySelectorAll('optgroup[data-ext-sorts]').forEach(g => g.remove());
    const groups = new Map();
    for (const k of extensionQueryDoors().sortKeys) {
        if (!groups.has(k.extName)) {
            const group = document.createElement('optgroup');
            group.label = k.extName;
            group.dataset.extSorts = '';
            groups.set(k.extName, group);
        }
        for (const [order, word] of [['desc', 'Descending'], ['asc', 'Ascending']]) {
            const opt = document.createElement('option');
            opt.value = `ext:${k.sort}:${order}`;
            opt.textContent = `${k.label} (${word})`;
            opt.dataset.icon = 'fa-solid fa-puzzle-piece';
            groups.get(k.extName).appendChild(opt);
        }
    }
    for (const group of groups.values()) select.appendChild(group);
    const kept = [...select.options].some(o => o.value === was);
    select.value = kept ? was : getViewDefault('defaultSort');
    select._customSelect?.refresh?.();
    select._customSelect?.update?.();
    // the trigger was locked to the widest option there was; a new one may be wider
    select._customSelect?.relockWidth?.();
}

// Drop live rules on a field no extension answers, once the inventory is read: a boot-seeded rule
// is unknown before that, not gone.
function pruneExtensionAdvRules() {
    const doors = extensionQueryDoors();
    if (!doors.known) return 0;
    const offered = new Set(doors.ruleFields.map(f => f.field));
    const lost = charAdvFilterRules.filter(r => String(r.field).startsWith('ext.') && !offered.has(r.field));
    if (!lost.length) return 0;
    charAdvFilterRules = charAdvFilterRules.filter(r => !lost.includes(r));
    showToast(lost.length === 1 ? 'A filter was removed: its extension is off' : `${lost.length} filters were removed: their extension is off`, 'info');
    return lost.length;
}

document.addEventListener('cl-ext-query-doors-changed', () => {
    syncExtensionSortOptions();
    if (pruneExtensionAdvRules()) updateAdvFilterIndicator();
    // hidden too: opening the panel shows the rows as they were last drawn
    rerenderAdvFilterRows();
    // the view compiles against the doors, so the grid re-asks when they moved its query
    if (_lastGridQueryKey !== null && gridQueryKey(compileViewQuery()) !== _lastGridQueryKey) performSearch();
});

// Both read per call: a provider registered after boot must parse in the next search.
function gridPrefixProviderMap() {
    return Object.fromEntries(Object.entries(PROVIDER_MANIFEST)
        .flatMap(([id, p]) => p.searchPrefixes.map(pre => [pre, id])));
}

// Non-provider operators wrap the manifest prefixes so the accepted-prefix regex stays
// one alternation; a new provider joins it by existing.
function searchPrefixSrc() {
    return ['creator', 'version', 'uid', 'favorite', 'fav', 'linked',
        ...Object.values(PROVIDER_MANIFEST).flatMap(p => p.searchPrefixes), 'playlist'].join('|');
}

/** Compiles the view state into 1-2 query passes (two when favorites group first); null when it can match nothing. */
function compileViewQuery() {
    const rawQuery = document.getElementById('searchInput').value;
    const fields = [];
    if (document.getElementById('searchName').checked) { fields.push('name', 'nickname'); }
    if (document.getElementById('searchListingName').checked) fields.push('listingName');
    if (document.getElementById('searchTags').checked) fields.push('tags');
    if (document.getElementById('searchAuthor').checked) fields.push('creator');
    if (document.getElementById('searchNotes').checked) fields.push('notes');
    if (document.getElementById('searchTagline')?.checked) fields.push('tagline');
    // Card text, off by default.
    if (document.getElementById('searchDesc')?.checked) fields.push('description');
    if (document.getElementById('searchFirstMessage')?.checked) fields.push('firstMessage');
    if (document.getElementById('searchAltGreetings')?.checked) fields.push('altGreetings');

    const rules = [];
    const base = new URLSearchParams();

    const prefixPattern = new RegExp('(?:^|\\s)((?:' + searchPrefixSrc() + '):(?:[^\\s]+))', 'gi');
    const providerPrefixes = gridPrefixProviderMap();
    let favParam = null;
    let query = rawQuery;
    let match;
    while ((match = prefixPattern.exec(rawQuery)) !== null) {
        const token = match[1];
        const colonIdx = token.indexOf(':');
        const prefix = token.substring(0, colonIdx).toLowerCase();
        const value = token.substring(colonIdx + 1).trim().toLowerCase();
        if (!value) continue;
        query = query.replace(token, '');

        if (prefix === 'creator') rules.push({ field: 'creator', op: 'contains', value });
        else if (prefix === 'version') {
            rules.push(value === 'none' || value === 'empty'
                ? { field: 'version', op: 'is_empty' }
                : { field: 'version', op: 'contains', value });
        } else if (prefix === 'uid') {
            rules.push(value === 'none' || value === 'empty'
                ? { field: 'uid', op: 'is_empty' }
                : { field: 'uid', op: 'contains', value });
        } else if (prefix === 'favorite' || prefix === 'fav') {
            favParam = (value === 'yes' || value === 'true') ? 'true' : 'false';
        } else if (prefix === 'linked') {
            rules.push({ field: 'providerLink', op: (value === 'yes' || value === 'true' || value === 'linked') ? 'is_linked' : 'is_not_linked' });
        } else if (prefix in providerPrefixes) {
            const want = value === 'yes' || value === 'true' || value === 'linked';
            rules.push({ field: 'providerLink', op: want ? 'linked_to' : 'not_linked_to', value: providerPrefixes[prefix] });
        } else if (prefix === 'playlist') {
            if (value === 'none' || value === 'empty') rules.push({ field: 'playlist', op: 'not_in_any' });
            else if (value === 'any' || value === 'yes') rules.push({ field: 'playlist', op: 'in_any' });
            else rules.push({ field: 'playlistName', op: 'contains', value });
        }
    }

    query = query.trim();
    if (query) {
        if (!fields.length) return null; // no searchable fields selected: nothing can match
        base.set('q', query);
        base.set('qIn', fields.join(','));
    }

    // tag chips (tri-state with any/all modes)
    const includedTags = [];
    const excludedTags = [];
    activeTagFilters.forEach((state, tag) => {
        if (state === 'include') includedTags.push(tag);
        else if (state === 'exclude') excludedTags.push(tag);
    });
    if (includedTags.length) {
        for (const t of includedTags) base.append(tagIncludeMode === 'all' ? 'tag' : 'anyTag', t);
    }
    if (excludedTags.length) {
        for (const t of excludedTags) base.append(tagExcludeMode === 'all' ? 'excludeTagAll' : 'excludeTag', t);
    }

    if (activePlaylistFilter) rules.push({ field: 'playlist', op: 'in', value: activePlaylistFilter });
    if (showFavoritesOnly) favParam = 'true';
    if (favParam !== null) base.set('fav', favParam);

    // advanced rules pass through verbatim, evaluated server-side; a rule on an extension field nothing
    // answers yet stays out
    const extFields = new Set(extensionQueryDoors().ruleFields.map(f => f.field));
    for (const rule of charAdvFilterRules) {
        const needsValue = !ADV_FILTER_NO_VALUE_OPS.has(rule.operator);
        if (needsValue && !rule.value) continue;
        if (String(rule.field).startsWith('ext.') && !extFields.has(rule.field)) continue;
        rules.push({ field: rule.field, op: rule.operator, value: rule.value });
    }
    if (rules.length) base.set('rules', JSON.stringify(rules));

    const sortSel = gridSortOf(document.getElementById('sortSelect')?.value);
    base.set('sort', sortSel.sort);
    base.set('order', sortSel.order);
    base.set('count', 'false');

    // favorites-first grouping = two passes unless a fav constraint already exists
    const groupFavs = (getSetting('groupFavoritesFirst') || false) && favParam === null;
    const passes = [];
    if (groupFavs) {
        const favPass = new URLSearchParams(base); favPass.set('fav', 'true');
        const restPass = new URLSearchParams(base); restPass.set('fav', 'false');
        passes.push(favPass, restPass);
    } else {
        passes.push(base);
    }
    // the view's set in the list's grammar, before the favourites split; the server drops order and
    // paging when reading it as a set
    return { passes, shuffle: !!sortSel.shuffle, filter: base.toString() };
}

// Whether the compiled query holds a tag constraint: a tag chip, a rule on tags, or a text search over tags
function viewQueryConstrainsTags() {
    const compiled = compileViewQuery();
    if (!compiled) return false;
    const params = new URLSearchParams(compiled.filter);
    if (['tag', 'anyTag', 'excludeTag', 'excludeTagAll'].some(k => params.has(k))) return true;
    if (params.has('q') && (params.get('qIn') || '').split(',').includes('tags')) return true;
    let rules = [];
    try { rules = JSON.parse(params.get('rules') || '[]'); } catch { /* no rules */ }
    return rules.some(r => r.field === 'tags');
}

let _gridQueryGen = 0;
let _gridQueryAbort = null;   // the running query's own fetches; superseded = aborted, not just discarded

// Windowed grid: currentCharacters is a SPARSE array sized to the total; only windows the viewport
// touches are fetched, O(what was seen).
const GRID_WINDOW_SIZE = 200;
// The browser gives this origin 6 connections; window fetches take at most 4 so search,
// chats and modal hydrates always have a free lane even mid-prefetch.
const GRID_WINDOW_CONCURRENCY = 4;
let _gridSegments = null; // { gen, segments: [{ base, total, offsetBase }] }
let _gridWindowQueue = [];               // pending window jobs, nearest-first
const _gridWindowsInFlight = new Map();  // job key -> AbortController
let _lastGridQueryKey = null;

// A changed query resets scroll (new result set starts at the top); a same-query
// re-run (view re-entry, post-write resync) keeps the user's position.
function gridQueryKey(compiled) {
    return compiled
        ? compiled.passes.map(p => p.toString()).join('|') + (compiled.shuffle ? `|sh${_gridQueryGen}` : '')
        : 'none';
}

function gridQueryChanged(compiled) {
    const key = gridQueryKey(compiled);
    const changed = key !== _lastGridQueryKey;
    _lastGridQueryKey = key;
    return changed;
}

// ONE grid query at a time, latest-wins: a keystroke costs the server a synchronous query an abort
// cant un-spend, so park, dont race.
let _gridQueryActive = null;
let _gridQueryQueued = false;

function runGridQuery() {
    if (_gridQueryActive) {
        _gridQueryQueued = true;
        return _gridQueryActive.then(() => {
            if (_gridQueryQueued) { _gridQueryQueued = false; return runGridQuery(); }
            // A sibling parked caller already started the follow-up; wait for that one
            // rather than resolving over a grid it has not painted yet.
            return _gridQueryActive || undefined;
        });
    }
    _gridQueryActive = (async () => {
        // The search box's magnifier becomes a spinner so slow reads as working; deferred past a normal
        // answer so it never flashes.
        const slow = setTimeout(() => setGridSearchBusy(true), GRID_QUERY_BUSY_MS);
        try { await doGridQuery(); }
        finally { clearTimeout(slow); setGridSearchBusy(false); _gridQueryActive = null; }
    })();
    return _gridQueryActive;
}

const GRID_QUERY_BUSY_MS = 250;

function setGridSearchBusy(busy) {
    const icon = document.getElementById('searchBusyIcon');
    if (!icon) return;
    icon.classList.toggle('fa-search', !busy);
    icon.classList.toggle('fa-spinner', busy);
    icon.classList.toggle('fa-spin', busy);
}

async function doGridQuery() {
    const gen = ++_gridQueryGen;
    // the old generation's windows would be discarded anyway; aborting them frees connections so this
    // query isnt queued behind its past
    _gridWindowQueue = [];
    for (const f of _gridWindowsInFlight.values()) f.ac.abort();
    _gridQueryAbort?.abort();
    const ac = new AbortController();
    _gridQueryAbort = ac;
    const compiled = compileViewQuery();
    // a Select All lives while the view shows its set: a write that moved the view keeps it, a new
    // search or filter ends it
    window.MultiSelect?.viewQueried?.(compiled?.filter ?? null);
    const queryChanged = gridQueryChanged(compiled);
    if (queryChanged) {
        const sc = document.querySelector('.gallery-content');
        if (sc && (getCurrentView() || 'characters') === 'characters') sc.scrollTop = 0;
    }
    if (!compiled) {
        currentCharacters = [];
        _gridSegments = null;
        renderGrid(currentCharacters);
        _gridPaintedOnce = true;
        return;
    }

    try {
        // Shuffle is the one deliberate full-stream mode: a random order has to
        // be drawn over the whole result set once.
        if (compiled.shuffle) {
            const rows = [];
            for (const pass of compiled.passes) {
                let after = null;
                do {
                    const params = new URLSearchParams(pass);
                    params.set('limit', String(FETCH_PAGE_SIZE));
                    if (after) params.set('after', after);
                    const resp = await apiRequest(`/characters?${params}`, 'GET', null, { signal: ac.signal });
                    if (gen !== _gridQueryGen) return;
                    if (!resp.ok) throw new Error(`query failed: ${resp.status} ${await resp.text()}`);
                    const page = await resp.json();
                    for (const item of page.items) rows.push(item);
                    after = page.nextCursor;
                } while (after);
            }
            if (gen !== _gridQueryGen) return;
            const mapped = mergeServerRows(rows);
            for (let i = mapped.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [mapped[i], mapped[j]] = [mapped[j], mapped[i]];
            }
            _gridSegments = null;
            currentCharacters = mapped;
            renderGrid(mapped);
            _gridPaintedOnce = true;
            return;
        }

        const segments = [];
        for (const pass of compiled.passes) {
            const params = new URLSearchParams(pass);
            params.set('limit', String(GRID_WINDOW_SIZE));
            params.set('offset', '0');
            params.set('count', 'true'); // the total sizes the sparse array + scrollbar
            const resp = await apiRequest(`/characters?${params}`, 'GET', null, { signal: ac.signal });
            if (gen !== _gridQueryGen) return;
            if (!resp.ok) throw new Error(`query failed: ${resp.status} ${await resp.text()}`);
            const page = await resp.json();
            segments.push({ base: pass, total: page.total ?? page.items.length, first: page.items });
        }
        if (gen !== _gridQueryGen) return;

        let offsetBase = 0;
        for (const s of segments) { s.offsetBase = offsetBase; offsetBase += s.total; }
        const sparse = new Array(offsetBase);
        for (const s of segments) {
            const chars = mergeServerRows(s.first);
            for (let i = 0; i < chars.length; i++) sparse[s.offsetBase + i] = chars[i];
            s.first = null;
        }
        _gridSegments = { gen, segments };
        currentCharacters = sparse;
        renderGrid(sparse);
        _gridPaintedOnce = true;
    } catch (e) {
        if (e?.name === 'AbortError') return; // superseded by a newer query; that run owns the view now
        console.error('[GridQuery] failed:', e);
        if (gen !== _gridQueryGen) return;
        // nothing painted yet: an error with a retry, never the empty array as an empty library
        if (!_gridPaintedOnce) { renderGridLoadError(e?.message); return; }
        renderGrid(currentCharacters); // keep the last good view, and say that it is stale
        showToast(`The library could not be refreshed: ${e?.message || 'the server did not answer'}`, 'error');
    }
}

// The CURRENT view as a set, its filter in GET /characters' grammar for a tally or a server-side
// write; null when it matches nothing.
function currentViewFilter() {
    return compileViewQuery()?.filter ?? null;
}

// what orders, pages or counts a list, never what it holds (the server's own list, LIST_ONLY)
const FILTER_LIST_ONLY = ['sort', 'order', 'after', 'limit', 'offset', 'count', 'idsOnly', 'fields'];

/**
 * A filter narrowed by one more advanced rule: rules AND, so a favorites-only view stays favorites only.
 * @param {string} filter a GET /characters query string
 * @param {{field: string, op: string, value?: *}} rule
 * @returns {string}
 */
function narrowFilter(filter, rule) {
    const p = new URLSearchParams(filter || '');
    let rules = [];
    try { rules = JSON.parse(p.get('rules') || '[]'); } catch { /* the server refuses a broken one by name */ }
    p.set('rules', JSON.stringify([...(Array.isArray(rules) ? rules : []), rule]));
    return p.toString();
}

/** Whether two filters name the same set: their parameters alike, order, paging and counting aside. */
function sameSet(a, b) {
    const key = (f) => {
        const p = new URLSearchParams(f || '');
        for (const k of FILTER_LIST_ONLY) p.delete(k);
        return [...p.entries()].map(([k, v]) => `${k}=${v}`).sort().join('&');
    };
    return key(a) === key(b);
}

/** Whether a filter names no subset: only order, paging or counting, so its set is the whole library. */
function filterNamesNothing(filter) {
    const p = new URLSearchParams(filter || '');
    for (const k of FILTER_LIST_ONLY) p.delete(k);
    return [...p.keys()].length === 0;
}

// Queues windows with holes in the range, midpoint first. RECONCILE by default (queue rebuilt, far
// fetches aborted); additive for point requests.
function requestGridWindows(startIndex, endIndex, additive = false) {
    if (!_gridSegments || _gridSegments.gen !== _gridQueryGen) return;
    const mid = (startIndex + endIndex) / 2;
    const jobs = [];
    for (const s of _gridSegments.segments) {
        const segStart = s.offsetBase;
        const segEnd = s.offsetBase + s.total;
        const from = Math.max(startIndex, segStart);
        const to = Math.min(endIndex, segEnd);
        if (from >= to) continue;
        const firstPage = Math.floor((from - segStart) / GRID_WINDOW_SIZE);
        const lastPage = Math.floor((to - 1 - segStart) / GRID_WINDOW_SIZE);
        for (let p = firstPage; p <= lastPage; p++) {
            const pStart = segStart + p * GRID_WINDOW_SIZE;
            const pEnd = Math.min(segEnd, pStart + GRID_WINDOW_SIZE);
            let missing = false;
            for (let i = pStart; i < pEnd; i++) {
                if (currentCharacters[i] === undefined) { missing = true; break; }
            }
            if (!missing) continue;
            const key = `${_gridQueryGen}:${s.offsetBase}:${p}`;
            if (_gridWindowsInFlight.has(key)) continue;
            jobs.push({ seg: s, pageNo: p, key, gen: _gridQueryGen, start: pStart, end: pEnd, dist: Math.abs((pStart + pEnd) / 2 - mid) });
        }
    }
    jobs.sort((a, b) => a.dist - b.dist);
    if (additive) {
        const queued = new Set(_gridWindowQueue.map(j => j.key));
        _gridWindowQueue.unshift(...jobs.filter(j => !queued.has(j.key)));
    } else {
        _gridWindowQueue = jobs;
        const slack = Math.max(endIndex - startIndex, GRID_WINDOW_SIZE * 2);
        for (const f of _gridWindowsInFlight.values()) {
            if (f.gen !== _gridQueryGen || f.end <= startIndex - slack || f.start >= endIndex + slack) f.ac.abort();
        }
    }
    pumpGridWindows();
}

function pumpGridWindows() {
    while (_gridWindowsInFlight.size < GRID_WINDOW_CONCURRENCY && _gridWindowQueue.length) {
        const job = _gridWindowQueue.shift();
        if (_gridWindowsInFlight.has(job.key)) continue;
        const ac = new AbortController();
        _gridWindowsInFlight.set(job.key, { ac, start: job.start, end: job.end, gen: job.gen });
        fetchGridWindow(job.seg, job.pageNo, job.gen, ac.signal).finally(() => {
            _gridWindowsInFlight.delete(job.key);
            pumpGridWindows();
        });
    }
}

// Mid-fling the queue holds only windows left behind; in-flight fetches finish and reconcile cleans
// up at scroll-end.
function dropQueuedGridWindows() {
    _gridWindowQueue = [];
}

async function fetchGridWindow(seg, pageNo, gen, signal, attempt = 0) {
    try {
        const params = new URLSearchParams(seg.base);
        params.set('limit', String(GRID_WINDOW_SIZE));
        params.set('offset', String(pageNo * GRID_WINDOW_SIZE));
        params.set('count', 'false');
        const resp = await apiRequest(`/characters?${params}`, 'GET', null, { signal });
        if (gen !== _gridQueryGen) return;
        if (!resp.ok) throw new Error(`window fetch failed: ${resp.status}`);
        const page = await resp.json();
        if (gen !== _gridQueryGen) return;
        const chars = mergeServerRows(page.items);
        const baseIdx = seg.offsetBase + pageNo * GRID_WINDOW_SIZE;
        for (let i = 0; i < chars.length; i++) currentCharacters[baseIdx + i] = chars[i];
        indexCharsById(chars);
        // The total came from a COUNT taken before this fetch: a shrunk set leaves the tail empty for good,
        // so mark it null (answered).
        const windowEnd = Math.min(seg.offsetBase + seg.total, baseIdx + GRID_WINDOW_SIZE);
        for (let i = baseIdx + chars.length; i < windowEnd; i++) {
            if (currentCharacters[i] === undefined) currentCharacters[i] = null;
        }
        const grid = document.getElementById('characterGrid');
        const scroller = document.querySelector('.gallery-content');
        if (grid && scroller && currentView === 'characters' && currentCharsList === currentCharacters) {
            updateVisibleCards(grid, scroller, true);
        }
    } catch (e) {
        // An abort is the scheduler cutting a stale window loose, not a failure; if the
        // reader comes back to it, the next reconcile re-asks.
        if (e?.name === 'AbortError') return;
        // A hole paints a placeholder, so a dropped window shimmers: retry twice before the next range
        // change; the in-flight key holds meanwhile.
        if (attempt < 2 && gen === _gridQueryGen && !signal?.aborted) {
            await new Promise(r => setTimeout(r, 500 * (attempt + 1)));
            if (gen === _gridQueryGen && !signal?.aborted) return fetchGridWindow(seg, pageNo, gen, signal, attempt + 1);
        }
    }
}

function performSearch() {
    updateMobileFilterIndicator();
    // the chats view filters its own list off this input; a change made elsewhere is applied by
    // switchView's performSearch on entry
    if ((getCurrentView() || 'characters') !== 'characters') return;
    runGridQuery();
}


function updateMobileChatButtonVisibility() {
    const chatBtn = document.getElementById('modalChatBtn');
    if (!chatBtn) return;

    const isMobile = isMobileMode();
    if (!isMobile) {
        chatBtn.classList.remove('mobile-chat-hidden');
        return;
    }

    const isDetailsActive = document.querySelector('.tab-btn[data-tab="details"]')?.classList.contains('active');
    chatBtn.classList.toggle('mobile-chat-hidden', !isDetailsActive);
}

/**
 * Filter local cards view by creator name
 * Sets the search to "creator:Name" and checks the Author filter
 */
function filterLocalByCreatorNow(creatorName) {
    debugLog('[Gallery] Filtering local by creator:', creatorName);
    
    if ((getCurrentView() || 'characters') !== 'characters') {
        switchView('characters');
    }
    
    const searchInput = document.getElementById('searchInput');
    const clearSearchBtn = document.getElementById('clearSearchBtn');
    if (searchInput) {
        searchInput.value = `creator:${creatorName}`;
        // Show clear button since we're populating programmatically
        if (clearSearchBtn) clearSearchBtn.classList.remove('hidden');
    }
    
    const authorCheckbox = document.getElementById('searchAuthor');
    if (authorCheckbox) {
        authorCheckbox.checked = true;
    }
    
    performSearch();
    
    showToast(`Filtering by creator: ${creatorName}`, 'info');
    return true;
}

// The search box set to a query and run, behind library.search; from another view it switches to
// characters first.
function searchLibraryNow(query) {
    if ((getCurrentView() || 'characters') !== 'characters') switchView('characters');
    const text = String(query ?? '');
    const input = document.getElementById('searchInput');
    if (input && input.value !== text) input.value = text;
    document.getElementById('clearSearchBtn')?.classList.toggle('hidden', !text);
    performSearch();
    return true;
}

// the box's typing, once its wait runs out: a search of the library on the characters view
function runTypedSearch() {
    if ((getCurrentView() || 'characters') !== 'characters') return performSearch();
    const query = document.getElementById('searchInput')?.value || '';
    return runShellCommand('library.search', { query }, a => searchLibraryNow(a.query));
}

/**
 * The search wait, from how much is typed (short queries cost the most) and the reader's recent
 * keystroke gap (1.4x), capped.
 */
const SEARCH_WAIT_CAP_MS = 900;

function searchWaitMs(len, typingGap) {
    const byLen = len <= 0 ? 250   // cleared: the plain indexed grid query, which is cheap
        : len === 1 ? 600
        : len === 2 ? 400
        : len === 3 ? 300
        : 250;
    return Math.min(SEARCH_WAIT_CAP_MS, Math.max(byLen, Math.round(typingGap * 1.4)));
}

/** A field's typing rhythm: tick() on each keystroke answers the smoothed gap between keys, ms. */
function makeTypingRhythm() {
    let lastKeyAt = 0;
    let typingGap = 0;
    return {
        tick() {
            const now = Date.now();
            const gap = lastKeyAt ? now - lastKeyAt : 0;
            lastKeyAt = now;
            // a long gap is a new burst, not a rhythm: a thinking pause averaged in makes the next key wait
            // for a pace nobody types
            if (gap > 0 && gap < 1500) typingGap = typingGap ? Math.round(typingGap * 0.6 + gap * 0.4) : gap;
            else if (gap >= 1500) typingGap = 0;
            return typingGap;
        },
    };
}

let _searchDebounceTimer = null;
const _searchRhythm = makeTypingRhythm();

function debouncedSearch() {
    const gap = _searchRhythm.tick();
    clearTimeout(_searchDebounceTimer);
    // read at schedule time for the wait and again in performSearch, so the run compiles what's in the
    // box when it fires
    const len = (document.getElementById('searchInput')?.value || '').trim().length;
    _searchDebounceTimer = setTimeout(runTypedSearch, searchWaitMs(len, gap));
}

// Extension actions in the topbar menu, rebuilt on every registration and open (desktop and phone),
// each when() judged against the view.
function renderExtensionAppActions() {
    const menu = document.getElementById('moreOptionsMenu');
    if (!menu) return false;
    menu.querySelectorAll('[data-ext-action], #extAppActionsTitle').forEach(el => el.remove());
    const actions = window.ExtensionHost?.actionsFor?.('app', { view: getCurrentView() }) || [];
    if (!actions.length) return true;
    menu.insertAdjacentHTML('beforeend', `<div class="dropdown-section-title" id="extAppActionsTitle">Extensions</div>`
        + actions.map(a => `<button type="button" class="dropdown-item" data-ext-action="${escapeHtml(a.key)}"><i class="fa-solid ${escapeHtml(a.icon)}"></i> ${escapeHtml(a.label)}</button>`).join(''));
    for (const btn of menu.querySelectorAll('[data-ext-action]')) {
        btn.addEventListener('click', () => {
            menu.classList.add('hidden');
            window.ExtensionHost?.runAction?.(btn.dataset.extAction, { view: getCurrentView() });
        });
    }
    return true;
}

const TOPBAR_DROPDOWN_IDS = ['tagFilterPopup', 'playlistFilterPopup', 'searchSettingsMenu', 'moreOptionsMenu', 'notificationsDropdown', 'advFilterPanel'];

function closeAllTopbarDropdowns(exceptId) {
    for (const id of TOPBAR_DROPDOWN_IDS) {
        if (id === exceptId) continue;
        document.getElementById(id)?.classList.add('hidden');
    }
    document.querySelectorAll('.custom-select-menu:not(.hidden)').forEach(m => m.classList.add('hidden'));
    window.closeActiveBrowseDropdowns?.(exceptId);
}

// ========================================
// NOTIFICATIONS CENTER
// Section-based topbar dropdown. Modules contribute sections (gallery sync,
// media downloads); the shell owns the button state, visibility, and open
// dispatch. Warning beats activity beats neutral for the button icon.
// ========================================

const _notifSections = new Map(); // id -> { id, getStatus, onOpen }

// The slot is the shell's to make, so a module adds a section without touching markup; the node
// comes back for its delegates.
function registerNotificationSection(cfg) {
    if (!cfg?.id) return null;
    _notifSections.set(cfg.id, cfg);
    const dropdown = document.getElementById('notificationsDropdown');
    let el = getNotificationSectionEl(cfg.id);
    if (!el && dropdown) {
        el = document.createElement('div');
        el.className = 'notif-section';
        el.dataset.notifSection = cfg.id;
        dropdown.appendChild(el);
    }
    refreshNotificationsUI();
    return el;
}

// Takes a section and its node out; given cfg, only while cfg is still the one held, so a stale removal spares a newer one.
function removeNotificationSection(id, cfg) {
    const held = _notifSections.get(id);
    if (!held || (cfg && held !== cfg)) return false;
    _notifSections.delete(id);
    getNotificationSectionEl(id)?.remove();
    refreshNotificationsUI();
    return true;
}

function getNotificationSectionEl(id) {
    return document.querySelector(`#notificationsDropdown [data-notif-section="${CSS.escape(String(id))}"]`);
}

function refreshNotificationsUI() {
    const btn = document.getElementById('notificationsBtn');
    if (!btn) return;
    const container = btn.closest('.notifications-container');
    const statuses = [];
    for (const s of _notifSections.values()) {
        try { statuses.push(s.getStatus?.() || {}); } catch { statuses.push({}); }
    }
    const anyVisible = statuses.some(s => s.visible);
    const warning = statuses.find(s => s.visible && s.level === 'warning');
    const activity = statuses.find(s => s.visible && s.level === 'activity');
    // Other chrome (the phone's More button and its sheet row) reads the level from here
    // rather than re-deriving it from the sections.
    document.dispatchEvent(new CustomEvent('cl-notifications-changed', {
        detail: { level: warning ? 'warning' : activity ? 'activity' : 'none', visible: anyVisible },
    }));
    container?.classList.toggle('hidden', !anyVisible);
    // A dropdown hosted by another surface (the phone's notifications sheet) is that
    // surface's to show or hide; it renders an empty state instead of vanishing.
    const dropdown = document.getElementById('notificationsDropdown');
    if (!anyVisible && dropdown && !dropdown.closest('[data-notif-host]')) dropdown.classList.add('hidden');
    // A dropdown on screen repaints on every change, so no section waits for a reopen and no
    // module keeps its own is-it-showing check.
    if (dropdown && !dropdown.classList.contains('hidden')) openNotificationsDropdown();
    if (!anyVisible) return;
    const icon = btn.querySelector('i');
    const badge = btn.querySelector('.warning-badge');
    btn.classList.toggle('has-issues', !!warning);
    btn.classList.toggle('notif-activity', !warning && !!activity);
    if (warning) {
        if (icon) icon.className = warning.icon || 'fa-solid fa-triangle-exclamation';
        if (badge) {
            const text = warning.badge != null ? String(warning.badge) : '';
            badge.classList.toggle('hidden', !text);
            badge.textContent = text;
        }
        btn.title = warning.title || 'Attention needed';
    } else if (activity) {
        if (icon) icon.className = activity.icon || 'fa-solid fa-download';
        if (badge) badge.classList.add('hidden');
        btn.title = activity.title || 'Working...';
    } else {
        if (icon) icon.className = 'fa-solid fa-bell';
        if (badge) badge.classList.add('hidden');
        btn.title = 'Notifications';
    }
}

// Renders every visible section; used by the button click and the mobile sheet
function openNotificationsDropdown() {
    const dropdown = document.getElementById('notificationsDropdown');
    if (!dropdown) return;
    dropdown.classList.remove('hidden');
    let shown = 0;
    for (const s of _notifSections.values()) {
        const el = getNotificationSectionEl(s.id);
        if (!el) continue;
        const visible = (() => { try { return !!s.getStatus?.()?.visible; } catch { return false; } })();
        el.classList.toggle('hidden', !visible);
        if (!visible) continue;
        shown++;
        try { s.onOpen?.(el); } catch (e) { console.error('[Notifications] onOpen failed:', s.id, e); }
    }
    // Nothing to report is a state, never an empty box.
    const empty = dropdown.querySelector('.notif-empty');
    if (empty) empty.hidden = shown > 0;
}

function setupNotificationsCenter() {
    const btn = document.getElementById('notificationsBtn');
    const dropdown = document.getElementById('notificationsDropdown');
    if (!btn || !dropdown) return;
    btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const isOpen = !dropdown.classList.contains('hidden');
        closeAllTopbarDropdowns('notificationsDropdown');
        if (isOpen) dropdown.classList.add('hidden');
        else openNotificationsDropdown();
    });
    document.addEventListener('click', (e) => {
        // the path is fixed at dispatch: a section repainting under the tap detaches e.target, which
        // contains() would read as outside
        const path = e.composedPath();
        if (!path.includes(btn) && !path.includes(dropdown)) {
            dropdown.classList.add('hidden');
        }
    });
}

// Event Listeners
function setupEventListeners() {
    setupNotificationsCenter();

    // View Toggle Buttons (Characters / Chats / Online)
    document.querySelectorAll('.view-toggle-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            goToView(btn.dataset.view);
        });
    });
    // an extension's views join after the app's three and give way first; a theme that resizes the buttons refits it
    const viewToggle = document.querySelector('.view-toggle');
    if (viewToggle) fitRow(viewToggle, {
        entries: () => [...viewToggle.querySelectorAll('.view-toggle-btn')],
        more: viewToggle.querySelector('.view-toggle-more'),
        current: '.active',
        watch: true,
    });
    // every view's filter row, a provider's toolbar too, keeps what fits; the rest wait behind one More,
    // never under the bell
    const filtersRow = document.querySelector('.filters-wrapper');
    const filtersMore = document.getElementById('topbarFiltersMore');
    if (filtersRow && filtersMore) fitRow(filtersRow, {
        entries: () => [...filtersRow.querySelectorAll(':scope > .filter-area:not(.online-filters) > *, .online-kind-filter > *')],
        more: filtersMore,
        watch: true,
        // a row reads what the bar shows: a control's words, or its title when it is an icon
        label: (el) => (el.dataset.overflowLabel || el.getAttribute('aria-label') || el.textContent.trim() || el.title || '').replace(/\s+/g, ' '),
    });

    on('searchInput', 'input', debouncedSearch);

    // Filter Checkboxes
    ['searchName', 'searchListingName', 'searchTags', 'searchAuthor', 'searchNotes', 'searchTagline',
        'searchDesc', 'searchFirstMessage', 'searchAltGreetings'].forEach(id => {
        on(id, 'change', performSearch);
    });

    // Tag Filter Toggle
    const tagBtn = document.getElementById('tagFilterBtn');
    const tagPopup = document.getElementById('tagFilterPopup');
    const clearAllTagsBtn = document.getElementById('clearAllTagsBtn');

    if (tagBtn && tagPopup) {
        wireTagFilter();
        tagBtn.onclick = (e) => {
            e.stopPropagation();
            closeAllTopbarDropdowns('tagFilterPopup');
            tagPopup.classList.toggle('hidden');
            if (!tagPopup.classList.contains('hidden')) openTagFilter();
        };
        
        if (clearAllTagsBtn) {
            clearAllTagsBtn.onclick = (e) => {
                e.stopPropagation();
                clearAllTagFilters();
            };
        }
        
        window.addEventListener('click', (e) => {
            if (!tagPopup.classList.contains('hidden') && 
                !tagPopup.contains(e.target) && 
                e.target !== tagBtn && 
                !tagBtn.contains(e.target)) {
                tagPopup.classList.add('hidden');
            }
        });
    }

    // Playlist Filter Toggle
    const plBtn = document.getElementById('playlistFilterBtn');
    const plPopup = document.getElementById('playlistFilterPopup');
    const plContent = document.getElementById('playlistFilterContent');

    if (plBtn && plPopup && plContent) {
        plBtn.onclick = (e) => {
            e.stopPropagation();
            closeAllTopbarDropdowns('playlistFilterPopup');
            populatePlaylistDropdown();
            plPopup.classList.toggle('hidden');
        };

        plContent.addEventListener('click', (e) => {
            const item = e.target.closest('.pl-filter-item');
            if (!item) return;
            const uid = item.dataset.uid;
            setPlaylistFilter(uid || null);
            plPopup.classList.add('hidden');
        });

        const plSearchInput = document.getElementById('playlistFilterSearch');
        if (plSearchInput) {
            plSearchInput.addEventListener('input', () => {
                const query = plSearchInput.value.trim().toLowerCase();
                const items = plContent.querySelectorAll('.pl-filter-item[data-uid]');
                items.forEach(item => {
                    if (!item.dataset.uid) return;
                    const name = (item.querySelector('.pl-filter-name')?.textContent || '').toLowerCase();
                    item.hidden = !!query && !name.includes(query);
                });
            });
        }

        const plManageBtn = document.getElementById('playlistFilterManageBtn');
        if (plManageBtn) {
            plManageBtn.addEventListener('click', () => {
                plPopup.classList.add('hidden');
                window.openPlaylistManager?.();
            });
        }

        window.addEventListener('click', (e) => {
            if (!plPopup.classList.contains('hidden') &&
                !plPopup.contains(e.target) &&
                e.target !== plBtn &&
                !plBtn.contains(e.target)) {
                plPopup.classList.add('hidden');
            }
        });
    }

    // Settings Toggle
    const settingsBtn = document.getElementById('searchSettingsBtn');
    const settingsMenu = document.getElementById('searchSettingsMenu');
    
    if(settingsBtn && settingsMenu) {
        settingsBtn.onclick = (e) => {
            e.stopPropagation();
            closeAllTopbarDropdowns('searchSettingsMenu');
            settingsMenu.classList.toggle('hidden');
        };

        window.addEventListener('click', (e) => {
            if (!settingsMenu.classList.contains('hidden') && 
                !settingsMenu.contains(e.target) && 
                e.target !== settingsBtn && 
                !settingsBtn.contains(e.target)) {
                settingsMenu.classList.add('hidden');
            }
        });
    }
    
    // Advanced Filter Panel
    const advFilterBtn = document.getElementById('advFilterBtn');
    const advFilterPanel = document.getElementById('advFilterPanel');
    const advFilterRows = document.getElementById('advFilterRows');

    if (advFilterBtn && advFilterPanel) {
        advFilterBtn.onclick = (e) => {
            e.stopPropagation();
            toggleAdvFilterPanel();
        };

        on('advFilterAddBtn', 'click', (e) => {
            e.stopPropagation();
            addAdvFilterRule();
        });

        on('advFilterClearAll', 'click', (e) => {
            e.stopPropagation();
            clearAllAdvFilters();
        });

        advFilterPanel.addEventListener('click', (e) => e.stopPropagation());

        on('advFilterPresetsBtn', 'click', (e) => {
            e.stopPropagation();
            toggleAdvFilterPresetsPanel();
        });

        on('advFilterPresetSaveBtn', 'click', (e) => {
            e.stopPropagation();
            saveCurrentAsFilterPreset(document.getElementById('advFilterPresetNameInput')?.value || '');
        });

        document.getElementById('advFilterPresetNameInput')?.addEventListener('keydown', (e) => {
            if (e.key !== 'Enter') return;
            e.stopPropagation();
            saveCurrentAsFilterPreset(e.target.value);
        });

        document.getElementById('advFilterPresetNameInput')?.addEventListener('input', (e) => {
            e.stopPropagation();
            rerenderAdvFilterPresets();
        });

        document.getElementById('advFilterPresetsList')?.addEventListener('click', (e) => {
            const load = e.target.closest('.adv-filter-preset-load');
            if (load) { applyFilterPreset(load.dataset.uid); return; }
            const del = e.target.closest('.adv-filter-preset-delete');
            if (del) deleteFilterPreset(del.dataset.uid);
        });

        if (advFilterRows) {
            advFilterRows.addEventListener('change', (e) => {
                const ruleId = parseInt(e.target.dataset.ruleId);
                const rule = getAdvFilterRules().find(r => r.id === ruleId);
                if (!rule) return;

                if (e.target.classList.contains('adv-filter-field')) {
                    rule.field = e.target.value;
                    const newField = getActiveAdvFilterFields()[rule.field];
                    rule.operator = newField.operators[0];
                    rule.value = getAdvFilterDefaultValue(rule);
                    rerenderAdvFilterRows();
                    updateAdvFilterIndicator();
                    triggerAdvFilterSearch();
                } else if (e.target.classList.contains('adv-filter-operator')) {
                    rule.operator = e.target.value;
                    rule.value = getAdvFilterDefaultValue(rule);
                    rerenderAdvFilterRows();
                    updateAdvFilterIndicator();
                    triggerAdvFilterSearch();
                } else if (e.target.classList.contains('adv-filter-input')) {
                    rule.value = e.target.value;
                    updateAdvFilterIndicator();
                    triggerAdvFilterSearch();
                }
            });

            advFilterRows.addEventListener('input', (e) => {
                if (!e.target.classList.contains('adv-filter-input')) return;
                const ruleId = parseInt(e.target.dataset.ruleId);
                const rule = getAdvFilterRules().find(r => r.id === ruleId);
                if (!rule) return;
                rule.value = e.target.value;
                updateAdvFilterIndicator();
                scheduleAdvFilterSearch(rule.value);
            });

            advFilterRows.addEventListener('click', (e) => {
                const removeBtn = e.target.closest('.adv-filter-remove');
                if (!removeBtn) return;
                const ruleId = parseInt(removeBtn.dataset.ruleId);
                removeAdvFilterRule(ruleId);
            });
        }

        window.addEventListener('click', (e) => {
            if (!advFilterPanel.classList.contains('hidden') &&
                !advFilterPanel.contains(e.target) &&
                e.target !== advFilterBtn &&
                !advFilterBtn.contains(e.target)) {
                closeAdvFilterPanel();
            }
        });

        window.registerOverlay?.({
            id: 'advFilterPanel',
            tier: 10,
            close: () => closeAdvFilterPanel(),
        });
    }

    // More Options Dropdown Toggle
    const moreOptionsBtn = document.getElementById('moreOptionsBtn');
    const moreOptionsMenu = document.getElementById('moreOptionsMenu');
    
    if(moreOptionsBtn && moreOptionsMenu) {
        moreOptionsBtn.onclick = (e) => {
            e.stopPropagation();
            closeAllTopbarDropdowns('moreOptionsMenu');
            if (moreOptionsMenu.classList.contains('hidden')) renderExtensionAppActions();
            moreOptionsMenu.classList.toggle('hidden');
            if (!moreOptionsMenu.classList.contains('hidden')) fitListToViewport(moreOptionsMenu);
        };

        window.addEventListener('click', (e) => {
            if (!moreOptionsMenu.classList.contains('hidden') && 
                !moreOptionsMenu.contains(e.target) && 
                e.target !== moreOptionsBtn && 
                !moreOptionsBtn.contains(e.target)) {
                moreOptionsMenu.classList.add('hidden');
            }
        });
        
        moreOptionsMenu.querySelectorAll('.dropdown-item').forEach(item => {
            item.addEventListener('click', () => {
                moreOptionsMenu.classList.add('hidden');
            });
        });
    }
    
    // Clear Search Button
    const clearSearchBtn = document.getElementById('clearSearchBtn');
    const searchInputEl = document.getElementById('searchInput');
    
    if (clearSearchBtn && searchInputEl) {
        searchInputEl.addEventListener('input', () => {
            clearSearchBtn.classList.toggle('hidden', searchInputEl.value.length === 0);
        });
        
        clearSearchBtn.addEventListener('click', () => {
            searchInputEl.value = '';
            // an input event, so every view's own search listener reacts; a direct performSearch reached only
            // the grid and left chats stuck
            searchInputEl.dispatchEvent(new Event('input', { bubbles: true }));
            searchInputEl.focus();
        });
    }

    // Sort delegates to performSearch so there is ONE sort+render codepath (the dual-sort bug).
    on('sortSelect', 'change', (e) => {
        performSearch();
    });
    
    // Favorites Filter Toggle (inside search settings dropdown)
    const favCheckbox = document.getElementById('searchFavoritesOnly');
    if (favCheckbox) {
        favCheckbox.addEventListener('change', () => toggleFavoritesFilter());
    }
    
    // Favorite Character Button in Modal
    const favoriteCharBtn = document.getElementById('favoriteCharBtn');
    if (favoriteCharBtn) {
        favoriteCharBtn.addEventListener('click', () => {
            if (activeChar) {
                toggleCharacterFavorite(activeChar);
            }
        });
    }

    // Refresh - preserves current filters and search
    on('menuRefreshBtn', 'click', async () => {
        document.getElementById('characterGrid').innerHTML = '';
        document.getElementById('loading').hidden = false;
        
        await fetchCharacters(true);
        performSearch();
    });
    
    // Delete Character Button
    const deleteCharBtn = document.getElementById('deleteCharBtn');
    if (deleteCharBtn) {
        deleteCharBtn.addEventListener('click', () => {
            if (activeChar) {
                showDeleteConfirmation(activeChar);
            }
        });
    }

    // Close Modal
    on('modalClose', 'click', maybeCloseModal);
    on('charModalChangedReload', 'click', reloadCharModalFromServer);
    modal.addEventListener('click', (e) => {
        if (e.target === modal) maybeCloseModal();
    });

    // Char detail prev/next nav (desktop chevrons + keyboard; mobile swipe wired in library-mobile.js).
    on('charModalNavPrev', 'click', () => navigateModal(-1));
    on('charModalNavNext', 'click', () => navigateModal(1));
    // View-mode hero avatar overlay (desktop only; sidebar is hidden on mobile): click opens it in the gallery viewer, gallery images follow as prev/next.
    on('portraitViewOverlay', 'click', () => {
        if (activeChar) openAvatarInGalleryViewer(activeChar);
    });
    // The portrait loads only where the sidebar shows, so a flip back to desktop paints it
    document.addEventListener('cl-mobile-mode-change', () => { if (activeChar) paintModalPortrait(); });
    // Hover preload: warm the sibling's portrait (a grid thumb, so mostly cached already).
    const navPrevBtn = document.getElementById('charModalNavPrev');
    const navNextBtn = document.getElementById('charModalNavNext');
    const previewSiblingAt = (offset) => {
        if (!activeChar) return null;
        const navList = getModalNavList();
        const idx = navIndexOf(navList, activeChar);
        if (idx === -1) return null;
        return navList[idx + offset] || null;
    };
    navPrevBtn?.addEventListener('mouseenter', () => {
        const s = previewSiblingAt(-1);
        if (s) new Image().src = getCharacterAvatarThumbUrl(s.id);
    });
    navNextBtn?.addEventListener('mouseenter', () => {
        const s = previewSiblingAt(1);
        if (s) new Image().src = getCharacterAvatarThumbUrl(s.id);
    });
    document.addEventListener('keydown', (e) => {
        if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
        if (modal.classList.contains('hidden')) return;
        // dont drive char nav while a gallery viewer / sub-modal sits on top of the detail modal
        if (getTopmostOverlay()?.reg?.id !== 'charModal') return;
        if (getSetting('enableCharDetailNav') === false) return;
        const t = e.target;
        const tag = t?.tagName;
        if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || t?.isContentEditable) return;
        e.preventDefault();
        navigateModal(e.key === 'ArrowLeft' ? -1 : 1);
    });

    // Tabs: one listener on the strip, so a later tab (an extension's) switches too; a core tab's own
    // onclick loads its pane first.
    modal.querySelector('.tab-nav')?.addEventListener('click', (e) => {
        const btn = e.target.closest('.tab-btn');
        if (!btn) return;
        deactivateAllTabs();
        btn.classList.add('active');
        const pane = document.getElementById(`pane-${btn.dataset.tab}`);
        if (pane) {
            pane.classList.add('active');
            pane.scrollTop = 0;
            if (btn.dataset.extTab) renderExtensionTab(btn.dataset.extTab, pane);
        }
        updateMobileChatButtonVisibility();
    });
    // the app's tabs first; an extension's give way first, behind the strip's More
    const tabNav = modal.querySelector('.tab-nav');
    if (tabNav) fitRow(tabNav, {
        entries: () => [...tabNav.querySelectorAll('.tab-btn')],
        more: tabNav.querySelector('.tab-more'),
        current: '.active',
    });
    
    // Chat Button: resume this character's most recent conversation, or start their first.
    document.getElementById('modalChatBtn').onclick = async () => {
        if (!activeChar) return;
        await window.chatsModule?.openConversationForCharacter?.(activeChar);
    };

    updateMobileChatButtonVisibility();

    setupCharacterGridDelegates();
    
    // Save Button
    document.getElementById('saveEditBtn').onclick = saveCharacter;
    
    // Cancel Edit Button
    const cancelEditBtn = document.getElementById('cancelEditBtn');
    if (cancelEditBtn) {
        cancelEditBtn.onclick = cancelEditing;
    }
    
    // Edit Lock Toggle Button
    const toggleEditLockBtn = document.getElementById('toggleEditLockBtn');
    if (toggleEditLockBtn) {
        toggleEditLockBtn.onclick = () => setEditLock(!isEditLocked);
    }

    // Card Image change controls (in-place hero overlay)
    const portraitEditOverlay = document.getElementById('portraitEditOverlay');
    const portraitPendingRevertBtn = document.getElementById('portraitPendingRevertBtn');
    const editAvatarFileInput = document.getElementById('editAvatarFileInput');
    if (portraitEditOverlay && editAvatarFileInput) {
        portraitEditOverlay.onclick = () => {
            if (isEditLocked) return;
            editAvatarFileInput.click();
        };
        editAvatarFileInput.addEventListener('change', (e) => {
            const file = e.target.files?.[0];
            if (file) handlePendingAvatarSelected(file);
        });
    }
    if (portraitPendingRevertBtn) {
        portraitPendingRevertBtn.onclick = (e) => {
            e.stopPropagation();
            clearPendingAvatar();
        };
    }
    
    // Edit Fields Expand/Collapse Toggle
    const editFieldsToggleBtn = document.getElementById('editFieldsToggleBtn');
    if (editFieldsToggleBtn) {
        editFieldsToggleBtn.onclick = toggleEditFieldsExpand;
    }
    
    // Confirmation Modal Buttons
    const confirmSaveBtn = document.getElementById('confirmSaveBtn');
    const cancelSaveBtn = document.getElementById('cancelSaveBtn');
    const closeConfirmModal = document.getElementById('closeConfirmModal');
    const confirmModal = document.getElementById('confirmSaveModal');
    
    if (confirmSaveBtn) {
        confirmSaveBtn.onclick = performSave;
    }
    if (cancelSaveBtn) {
        cancelSaveBtn.onclick = () => confirmModal?.classList.add('hidden');
    }
    if (closeConfirmModal) {
        closeConfirmModal.onclick = () => confirmModal?.classList.add('hidden');
    }
    
    // Chats Tab Buttons (delegated to chats module)
    const newChatBtn = document.getElementById('newChatBtn');
    const refreshChatsBtn = document.getElementById('refreshChatsBtn');
    
    if (newChatBtn) {
        newChatBtn.onclick = () => {
            if (activeChar) window.createNewChat?.(activeChar);
        };
    }
    if (refreshChatsBtn) {
        refreshChatsBtn.onclick = () => {
            if (activeChar) window.fetchCharacterChats?.(activeChar);
        };
    }
    
    // Gallery Settings Modal
    setupSettingsModal();
    
    // Add Alternate Greeting Button
    const addAltGreetingBtn = document.getElementById('addAltGreetingBtn');
    if (addAltGreetingBtn) {
        addAltGreetingBtn.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            addAltGreetingField();
        };
    }
    
    // Add Lorebook Entry Button
    const addLorebookEntryBtn = document.getElementById('addLorebookEntryBtn');
    if (addLorebookEntryBtn) {
        addLorebookEntryBtn.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            addLorebookEntryField();
            updateLorebookCount();
        };
    }

    // Insert from library: the link picker in its insert job
    const insertLorebookBtn = document.getElementById('insertLorebookBtn');
    if (insertLorebookBtn) {
        insertLorebookBtn.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (isEditLocked) return;
            void openLinkLorebookPicker({ mode: 'insert' });
        };
    }

    // Remove book: empties the editor; Save then writes the card without a book
    const removeLorebookBtn = document.getElementById('removeLorebookBtn');
    if (removeLorebookBtn) {
        removeLorebookBtn.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            void removeEmbeddedLorebook();
        };
    }

    // Send to library: the saved book onto the shelf, linked, through the lore panel's promote
    const promoteLorebookBtn = document.getElementById('promoteLorebookBtn');
    if (promoteLorebookBtn) {
        promoteLorebookBtn.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            void sendEmbeddedLorebookToLibrary();
        };
    }

    // Upload Zone
    const uploadZone = document.getElementById('uploadZone');
    const fileInput = document.getElementById('imageUploadInput');
    
    if (uploadZone && fileInput) {
        uploadZone.onclick = (e) => {
            if (e.target !== fileInput) fileInput.click();
        };

        fileInput.onchange = (e) => {
            if (e.target.files.length) uploadImages(e.target.files);
            fileInput.value = ''; 
        };
        
        // Drag and drop
        uploadZone.addEventListener('dragover', (e) => {
            e.preventDefault();
            uploadZone.style.borderColor = 'var(--accent)';
            uploadZone.style.backgroundColor = 'rgba(var(--accent-rgb), 0.1)';
        });
        
        uploadZone.addEventListener('dragleave', (e) => {
            e.preventDefault();
            uploadZone.style.borderColor = '';
            uploadZone.style.backgroundColor = '';
        });
        
        uploadZone.addEventListener('drop', (e) => {
            e.preventDefault();
            uploadZone.style.borderColor = '';
            uploadZone.style.backgroundColor = '';
            if (e.dataTransfer.files.length) uploadImages(e.dataTransfer.files);
        });
    }
}

// Alternate Greetings Editor Functions
function populateAltGreetingsEditor(greetings) {
    const container = document.getElementById('altGreetingsEditContainer');
    if (!container) return;
    
    container.innerHTML = '';
    
    if (greetings && greetings.length > 0) {
        greetings.forEach((greeting, index) => {
            addAltGreetingField(container, (greeting || '').trim(), index);
        });
    }
}

function addAltGreetingField(container, value = '', index = null) {
    if (!container) {
        container = document.getElementById('altGreetingsEditContainer');
    }
    if (!container) return;
    
    const idx = index !== null ? index : container.children.length;
    
    const wrapper = document.createElement('div');
    wrapper.className = 'alt-greeting-item';
    wrapper.style.cssText = 'position: relative; margin-bottom: 10px;';
    
    wrapper.innerHTML = `
        <div class="alt-greeting-row">
            <span class="alt-greeting-index">#${idx + 1}</span>
            <textarea class="glass-input alt-greeting-input u-flex-1" rows="3" placeholder="Alternate greeting message..."></textarea>
            <button type="button" class="remove-alt-greeting-btn" title="Remove this greeting">
                <i class="fa-solid fa-trash"></i>
            </button>
        </div>
    `;
    
    container.appendChild(wrapper);
    
    // assigned, never interpolated: a greeting is free text and must not parse as markup
    const textarea = wrapper.querySelector('.alt-greeting-input');
    if (textarea && value) {
        textarea.value = value;
    }
    
    const removeBtn = wrapper.querySelector('.remove-alt-greeting-btn');
    removeBtn.addEventListener('click', () => {
        wrapper.remove();
        renumberAltGreetings();
    });
}

function renumberAltGreetings() {
    const container = document.getElementById('altGreetingsEditContainer');
    if (!container) return;
    
    const items = container.querySelectorAll('.alt-greeting-item');
    items.forEach((item, idx) => {
        const numSpan = item.querySelector('span');
        if (numSpan) {
            numSpan.textContent = `#${idx + 1}`;
        }
    });
}

function getAltGreetingsFromEditor() {
    const container = document.getElementById('altGreetingsEditContainer');
    if (!container) return [];
    
    const inputs = container.querySelectorAll('.alt-greeting-input');
    const greetings = [];
    
    inputs.forEach(input => {
        const value = input.value;
        if (value.trim()) {  // Skip truly empty entries, but preserve original content
            greetings.push(value);
        }
    });
    
    return greetings;
}

// ==========================================
// Lorebook Editor Functions
// ==========================================

/**
 * Populate the lorebook editor with existing entries
 * @param {Object} characterBook - The character_book object from the character
 */
function populateLorebookEditor(characterBook) {
    const container = document.getElementById('lorebookEntriesEdit');
    const countEl = document.getElementById('lorebookEditCount');

    // The Linked Lorebooks row is its own section (linked = separate world files, embedded =
    // in-card entries): one ordered pills list, Add appends, pill X unlinks.
    if (document.getElementById('linkedLorebookEditRow')) populateAuxLorebooksRow();

    if (!container) return;

    container.innerHTML = '';
    _insertedBookName = '';

    const entries = characterBook?.entries || [];

    if (countEl) {
        countEl.textContent = `(${entries.length} ${entries.length === 1 ? 'entry' : 'entries'})`;
    }
    const nameEl = document.getElementById('lorebookEditName');
    if (nameEl) nameEl.textContent = characterBook?.name ? `: ${characterBook.name}` : '';

    entries.forEach((entry, index) => {
        addLorebookEntryField(container, entry, index);
    });
    updateLorebookCount();
}

/**
 * Add a lorebook entry's row to the editor; a null entry makes a blank one.
 * @param {Object} entry
 * @param {number} index - its position in the book, the row count when omitted
 */
function addLorebookEntryField(container, entry = null, index = null) {
    if (!container) {
        container = document.getElementById('lorebookEntriesEdit');
    }
    if (!container) return;
    
    const idx = index !== null ? index : container.children.length;
    
    const name = entry?.comment || entry?.name || '';
    const keys = entry?.keys || entry?.key || [];
    const keyStr = Array.isArray(keys) ? keys.join(', ') : keys;
    const secondaryKeys = entry?.secondary_keys || [];
    const secondaryKeyStr = Array.isArray(secondaryKeys) ? secondaryKeys.join(', ') : secondaryKeys;
    const content = entry?.content || '';
    const enabled = entry?.enabled !== false;
    const selective = entry?.selective || false;
    const constant = entry?.constant || false;
    const order = entry?.order ?? entry?.insertion_order ?? idx;
    const priority = entry?.priority ?? 10;
    
    const wrapper = document.createElement('div');
    wrapper.className = `lorebook-entry-edit${enabled ? '' : ' disabled'}`;
    wrapper.dataset.index = idx;
    
    wrapper.innerHTML = `
        <div class="lorebook-entry-header">
            <input type="search" autocomplete="one-time-code" class="glass-input lorebook-entry-name-input" placeholder="Entry name/comment">
            <div class="lorebook-entry-controls">
                <label class="lorebook-entry-toggle ${enabled ? 'enabled' : 'disabled'}" title="Toggle enabled">
                    <input type="checkbox" class="lorebook-enabled-checkbox" ${enabled ? 'checked' : ''} hidden>
                    ${enabled ? '<i class="fa-solid fa-toggle-on"></i> On' : '<i class="fa-solid fa-toggle-off"></i> Off'}
                </label>
                <span class="lorebook-entry-delete" title="Delete entry">
                    <i class="fa-solid fa-trash"></i>
                </span>
            </div>
        </div>
        <div class="lorebook-entry-fields">
            <div class="lorebook-entry-row">
                <div class="form-group flex-1">
                    <label>Keys <span class="label-hint">(comma-separated)</span></label>
                    <input type="search" autocomplete="one-time-code" class="glass-input lorebook-keys-input" placeholder="keyword1, keyword2">
                </div>
            </div>
            <div class="lorebook-entry-row">
                <div class="form-group flex-1">
                    <label>Secondary Keys <span class="label-hint">(optional, for selective)</span></label>
                    <input type="search" autocomplete="one-time-code" class="glass-input lorebook-secondary-keys-input" placeholder="secondary1, secondary2">
                </div>
            </div>
            <div class="lorebook-entry-row">
                <div class="form-group flex-1">
                    <label>Content</label>
                    <textarea class="glass-input lorebook-content-input" rows="3" placeholder="Lore content..."></textarea>
                </div>
            </div>
            <div class="lorebook-entry-row">
                <label class="u-row-tight u-pointer">
                    <input type="checkbox" class="lorebook-selective-checkbox" ${selective ? 'checked' : ''}>
                    <span class="u-text-sm">Selective</span>
                </label>
                <label class="u-row-tight u-pointer">
                    <input type="checkbox" class="lorebook-constant-checkbox" ${constant ? 'checked' : ''}>
                    <span class="u-text-sm">Constant</span>
                </label>
                <div class="u-row-tight">
                    <label class="u-text-sm">Order:</label>
                    <input type="number" class="glass-input lorebook-order-input">
                </div>
                <div class="u-row-tight">
                    <label class="u-text-sm">Priority:</label>
                    <input type="number" class="glass-input lorebook-priority-input">
                </div>
            </div>
        </div>
    `;
    
    wrapper._originalEntry = entry || null;
    container.appendChild(wrapper);
    
    // assigned, never interpolated: entry text is free text and must not parse as markup
    wrapper.querySelector('.lorebook-entry-name-input').value = name;
    wrapper.querySelector('.lorebook-keys-input').value = keyStr;
    wrapper.querySelector('.lorebook-secondary-keys-input').value = secondaryKeyStr;
    wrapper.querySelector('.lorebook-content-input').value = content;
    wrapper.querySelector('.lorebook-order-input').value = order;
    wrapper.querySelector('.lorebook-priority-input').value = priority;

    // Snapshot what we populated so read-back preserves untouched fields verbatim instead of re-materialising them.
    wrapper._populated = {
        name: wrapper.querySelector('.lorebook-entry-name-input').value,
        keys: wrapper.querySelector('.lorebook-keys-input').value,
        secondaryKeys: wrapper.querySelector('.lorebook-secondary-keys-input').value,
        content: wrapper.querySelector('.lorebook-content-input').value,
        order: wrapper.querySelector('.lorebook-order-input').value,
        priority: wrapper.querySelector('.lorebook-priority-input').value,
        enabled: wrapper.querySelector('.lorebook-enabled-checkbox').checked,
        selective: wrapper.querySelector('.lorebook-selective-checkbox').checked,
        constant: wrapper.querySelector('.lorebook-constant-checkbox').checked,
    };

    const toggleLabel = wrapper.querySelector('.lorebook-entry-toggle');
    toggleLabel.addEventListener('click', (e) => {
        e.preventDefault();
        const checkbox = wrapper.querySelector('.lorebook-enabled-checkbox');
        const isEnabled = checkbox.checked;
        const newEnabled = !isEnabled;
        checkbox.checked = newEnabled;
        toggleLabel.className = `lorebook-entry-toggle ${newEnabled ? 'enabled' : 'disabled'}`;
        toggleLabel.innerHTML = `<input type="checkbox" class="lorebook-enabled-checkbox" ${newEnabled ? 'checked' : ''} hidden>${newEnabled ? '<i class="fa-solid fa-toggle-on"></i> On' : '<i class="fa-solid fa-toggle-off"></i> Off'}`;
        wrapper.classList.toggle('disabled', !newEnabled);
    });
    
    const deleteBtn = wrapper.querySelector('.lorebook-entry-delete');
    deleteBtn.addEventListener('click', () => {
        wrapper.remove();
        updateLorebookCount();
    });
}

/**
 * A native world (entries by uid) as an embedded character_book: the shelf's converter, whose field
 * table also drives the way back.
 * @param {Object} world - { entries: {uid: entry}, ...meta }
 * @param {string} name - the book name the world is known by
 * @returns {{name: string, entries: Object[]}}
 */
function convertWorldToCharacterBook(world, name = '') {
    return window.LoreShelf.convertWorldToCharacterBook(world, name);
}

// The world an insert made the card's book: Save names the book after it and drops the old
// metadata; cleared on repopulate.
let _insertedBookName = '';

/**
 * Copies a library book's entries into the embedded editor as new rows, nothing written until Save;
 * ids minted past the card's own.
 * @param {string} worldName
 */
async function insertWorldIntoEmbeddedLorebook(worldName) {
    if (!activeChar || !worldName || isEditLocked) return;
    const charId = activeChar.id;
    const doc = await getWorldInfoData(worldName);
    if (!activeChar || activeChar.id !== charId) return;
    if (!doc) { showToast(`Could not read "${worldName}"`, 'error'); return; }
    const book = convertWorldToCharacterBook(doc, worldName);
    if (!book.entries.length) { showToast(`"${worldName}" has no entries`, 'warning'); return; }
    const n = book.entries.length;
    const container = document.getElementById('lorebookEntriesEdit');
    if (!container) return;
    // a card holds ONE embedded book, so an insert over one replaces it whole, name included
    const had = container.querySelectorAll('.lorebook-entry-edit').length;
    const count = (k) => `${k} ${k === 1 ? 'entry' : 'entries'}`;
    const ok = await showConfirm({
        title: had ? 'Replace embedded lorebook?' : 'Insert lorebook?',
        message: had
            ? `Replace the embedded lorebook (${count(had)}) with "${worldName}" (${count(n)})? The current entries leave the card on Save; the library book stays as it is.`
            : `Insert ${count(n)} from "${worldName}" into the embedded lorebook? They are copied; the library book stays as it is.`,
        confirmLabel: had ? 'Replace' : 'Insert',
        danger: !!had,
    });
    if (!ok || !activeChar || activeChar.id !== charId) return;
    container.innerHTML = '';
    for (const entry of book.entries) {
        const fresh = { ...entry };
        delete fresh.id;
        addLorebookEntryField(container, fresh);
    }
    _insertedBookName = book.name;
    const nameEl = document.getElementById('lorebookEditName');
    if (nameEl) nameEl.textContent = book.name ? `: ${book.name}` : '';
    updateLorebookCount();
    const details = document.getElementById('lorebookEditDetails');
    if (details) details.open = true;
    showToast(`${had ? 'Replaced the embedded lorebook with' : 'Inserted'} ${count(n)} from "${worldName}". Save to keep ${had ? 'it' : 'them'}.`, 'success', 5000);
}

/**
 * Update the lorebook entry count display; the Remove and Send to library buttons show only
 * while there is a book to remove or send.
 */
function updateLorebookCount() {
    const container = document.getElementById('lorebookEntriesEdit');
    const countEl = document.getElementById('lorebookEditCount');

    if (container && countEl) {
        const count = container.children.length;
        countEl.textContent = `(${count} ${count === 1 ? 'entry' : 'entries'})`;
        document.getElementById('removeLorebookBtn')?.classList.toggle('hidden', count === 0);
        document.getElementById('promoteLorebookBtn')?.classList.toggle('hidden', count === 0);
    }
}

/**
 * Empties the embedded editor so Save writes the card with no book; the library book the entries
 * came from stays.
 */
async function removeEmbeddedLorebook() {
    if (!activeChar || isEditLocked) return;
    const charId = activeChar.id;
    const container = document.getElementById('lorebookEntriesEdit');
    const n = container ? container.querySelectorAll('.lorebook-entry-edit').length : 0;
    if (!container || !n) return;
    const ok = await confirmRemoveEmbeddedLorebook(n);
    if (!ok || !activeChar || activeChar.id !== charId) return;
    container.innerHTML = '';
    _insertedBookName = '';
    const nameEl = document.getElementById('lorebookEditName');
    if (nameEl) nameEl.textContent = '';
    updateLorebookCount();
    showToast('Removed the embedded lorebook. Save to keep the change.', 'success', 5000);
}

/** The one confirm both editors (inline and expanded) put before emptying the embedded book. */
function confirmRemoveEmbeddedLorebook(n) {
    const name = _insertedBookName || activeChar?.data?.character_book?.name || '';
    return showConfirm({
        title: 'Remove embedded lorebook?',
        message: `Remove the embedded lorebook${name ? ` "${name}"` : ''} (${n} ${n === 1 ? 'entry' : 'entries'}) from this card? It leaves the card on Save; a library book it came from stays as it is.`,
        confirmLabel: 'Remove',
        danger: true,
    });
}

let _sendingEmbeddedBook = false;

/**
 * Shelves the card's SAVED embedded book and links it (the one promote); unsaved edits ask for a
 * Save first.
 */
async function sendEmbeddedLorebookToLibrary() {
    if (!activeChar || isEditLocked || _sendingEmbeddedBook) return;
    const charId = activeChar.id;
    if (!window.CardDiff.lorebooksEqual(originalValues?.character_book, getCharacterBookFromEditor(), { normalizeKeys: false })) {
        showToast('Save the card first: the library gets the saved book, and this one has unsaved changes', 'warning');
        return;
    }
    _sendingEmbeddedBook = true;
    try {
        const done = await window.promoteEmbeddedLorebook?.(charId);
        if (!done || activeChar?.id !== charId) return;
        populateAuxLorebooksRow();
        populateLinkedLorebookBox(activeChar);
    } finally {
        _sendingEmbeddedBook = false;
    }
}

/**
 * Lossless merge of one entry's editor state: the original entry with only the changed inputs
 * overridden; a new entry gets the full shape.
 */
function buildLorebookEntryFromInputs(orig, pop, cur, idx) {
    const entry = orig ? { ...orig } : {
        position: 'before_char',
        case_sensitive: false,
        use_regex: false,
        extensions: {}
    };
    const dirty = (c, w) => !orig || c !== w;
    const parseList = (s) => String(s).split(',').map(k => k.trim()).filter(Boolean);

    if (dirty(cur.keys, pop.keys)) entry.keys = parseList(cur.keys);
    if (dirty(cur.secondaryKeys, pop.secondaryKeys)) entry.secondary_keys = parseList(cur.secondaryKeys);
    if (dirty(cur.content, pop.content)) entry.content = cur.content;
    if (dirty(cur.name, pop.name)) entry.comment = String(cur.name).trim() || `Entry ${idx + 1}`;
    if (dirty(cur.enabled, pop.enabled)) entry.enabled = cur.enabled;
    if (dirty(cur.selective, pop.selective)) entry.selective = cur.selective;
    if (dirty(cur.constant, pop.constant)) entry.constant = cur.constant;
    if (dirty(cur.order, pop.order)) {
        const o = parseInt(cur.order);
        const v = Number.isNaN(o) ? idx : o;
        entry.insertion_order = v;
        // Carry order only when the original had it; dont inject it onto entries that only stored insertion_order.
        if (!orig || 'order' in entry) entry.order = v;
    }
    if (dirty(cur.priority, pop.priority)) {
        const p = parseInt(cur.priority);
        entry.priority = Number.isNaN(p) ? 10 : p;
    }
    return entry;
}

// Reads the 9 editable fields off one inline `.lorebook-entry-edit` element into the editor-neutral shape.
function readInlineLorebookInputs(el) {
    return {
        name: el.querySelector('.lorebook-entry-name-input')?.value ?? '',
        keys: el.querySelector('.lorebook-keys-input')?.value ?? '',
        secondaryKeys: el.querySelector('.lorebook-secondary-keys-input')?.value ?? '',
        content: el.querySelector('.lorebook-content-input')?.value ?? '',
        order: el.querySelector('.lorebook-order-input')?.value ?? '',
        priority: el.querySelector('.lorebook-priority-input')?.value ?? '',
        enabled: el.querySelector('.lorebook-enabled-checkbox')?.checked ?? true,
        selective: el.querySelector('.lorebook-selective-checkbox')?.checked || false,
        constant: el.querySelector('.lorebook-constant-checkbox')?.checked || false,
    };
}

/**
 * Get lorebook entries from the editor
 * @returns {Array} Array of lorebook entry objects
 */
function getLorebookFromEditor() {
    const container = document.getElementById('lorebookEntriesEdit');
    if (!container) return [];

    const entries = [];
    const entryEls = container.querySelectorAll('.lorebook-entry-edit');

    // Preserve each entry's imported id; only mint ids for entries added in the editor.
    let maxExistingId = -1;
    entryEls.forEach((el) => {
        const origId = el._originalEntry?.id;
        if (typeof origId === 'number' && origId > maxExistingId) maxExistingId = origId;
    });
    let nextNewId = maxExistingId + 1;

    entryEls.forEach((el, idx) => {
        const entry = buildLorebookEntryFromInputs(el._originalEntry, el._populated || {}, readInlineLorebookInputs(el), idx);
        if (typeof entry.id !== 'number') entry.id = nextNewId++;
        entries.push(entry);
    });

    return entries;
}

/**
 * Builds a character_book from editor state, keeping the existing book's metadata.
 * @returns {Object|null} The character_book object or null if no entries
 */
function getCharacterBookFromEditor() {
    const entries = getLorebookFromEditor();
    
    if (entries.length === 0) {
        return null;
    }
    
    const existing = activeChar?.data?.character_book;
    // Spread the whole existing book so unmodelled fields survive; defaults only seed a new book. An
    // insert replaced it: the world's now
    const replaced = !!_insertedBookName;
    return {
        name: '',
        description: '',
        scan_depth: 2,
        token_budget: 512,
        recursive_scanning: false,
        ...(existing && !replaced ? existing : {}),
        ...(replaced ? { name: _insertedBookName, extensions: {} } : {}),
        entries: entries
    };
}

// ==============================================
// Utility Functions
// ==============================================

// Memoized on the manifest generation: the listing name and the held re-read walk it per card,
// and a provider registered after boot joins.
let _providerExtKeys = null;
let _providerExtKeysGen = -1;
function providerExtKeys() {
    const gen = window.ProviderRegistry?.manifestGeneration?.() ?? 0;
    if (!_providerExtKeys || gen !== _providerExtKeysGen) {
        _providerExtKeys = Object.values(PROVIDER_MANIFEST).map(p => p.extNamespace);
        _providerExtKeysGen = gen;
    }
    return _providerExtKeys;
}

function getListingNameFromExtensions(char) {
    const ext = char?.data?.extensions;
    if (!ext) return null;
    const activeProvider = window.ProviderRegistry?.getCharacterProvider(char);
    if (activeProvider?.linkInfo) {
        const pn = ext[activeProvider.provider.id]?.pageName;
        if (pn) return pn;
    }
    // CL-owned fallback checked before other provider namespaces, so a migrated cl value wins over a stale leftover.
    if (ext.cl?.pageName) return ext.cl.pageName;
    for (const key of providerExtKeys()) {
        if (ext[key]?.pageName) return ext[key].pageName;
    }
    return null;
}

// The alternate name a display source resolves to, or null; 'card' resolves via the caller's
// fallback. Display-only, never identity.
function resolveNameSource(char, source) {
    if (source === 'listing') return getListingNameFromExtensions(char);
    if (source === 'nickname') return char?.data?.nickname || null;
    return null;
}

// The sources the per-character toggle cycles: 'card' always, alternates only when present and
// different (else a dead switch).
function getNameSources(char) {
    const cardName = (char?.name || char?.data?.name || '').toLowerCase();
    const sources = ['card'];
    for (const source of ['listing', 'nickname']) {
        const value = resolveNameSource(char, source);
        if (value && value.toLowerCase() !== cardName) sources.push(source);
    }
    return sources;
}

function getCharacterName(char, fallback = 'Unknown') {
    if (!char) return fallback;
    const prefs = getSetting('namePreferences') || {};
    const pref = prefs[char.id]
        || getSetting('displayNamePreference')
        || 'card';
    const alternate = pref !== 'card' ? resolveNameSource(char, pref) : null;
    if (alternate) return alternate;
    return char.name || char.data?.name || char.definition?.name || fallback;
}

// Avatar assets are addressed by uuid (an object or a bare id); a filename is refused loudly, not
// stripped, to expose its caller.
function avatarKeyOf(charOrId) {
    // an object with avatar but no id was never given an identity: say so rather than return a silent empty
    if (charOrId && typeof charOrId === 'object' && !charOrId.id && charOrId.avatar) {
        console.error('[Avatar] object has avatar but no id, so it cannot resolve:', charOrId, new Error().stack);
        return '';
    }
    const v = typeof charOrId === 'string' ? charOrId : (charOrId?.id || '');
    if (/\.png$/i.test(v)) {
        console.error('[Avatar] identity is the character uuid, not a filename:', v, new Error().stack);
        return '';
    }
    return v;
}

function getCharacterAvatarUrl(charOrId) {
    const id = avatarKeyOf(charOrId);
    if (!id) return '';
    ensureAvatarCacheBustLoaded();
    const bust = _avatarCacheBust.get(id);
    return serverUrl(bust
        ? `/avatars/${encodeURIComponent(id)}.png?v=${bust}`
        : `/avatars/${encodeURIComponent(id)}.png`);
}

// Tagline lives in the active provider namespace (cl when unlinked).
function getDisplayTagline(char) {
    if (!char?.data?.extensions) return '';
    const activeId = window.ProviderRegistry?.getActiveTaglineNamespace?.(char) ?? 'cl';
    return char?.data?.extensions?.[activeId]?.tagline || '';
}

// Collapses and (re)wires the tagline row's expand toggle. onclick assignment replaces, never stacks.
function wireProviderTaglineExpand() {
    const taglineRow = document.getElementById('modalProviderTaglineRow');
    if (!taglineRow) return;
    taglineRow.classList.remove('expanded');
    taglineRow.setAttribute('aria-expanded', 'false');
    taglineRow.setAttribute('role', 'button');
    taglineRow.onclick = () => {
        const isExpanded = taglineRow.classList.toggle('expanded');
        taglineRow.setAttribute('aria-expanded', isExpanded ? 'true' : 'false');
    };
}

function renderProviderTaglineRow(char) {
    const taglineRow = document.getElementById('modalProviderTaglineRow');
    const taglineEl = document.getElementById('modalProviderTagline');
    if (!taglineRow || !taglineEl) return;
    const providerTagline = getDisplayTagline(char);
    if (getSetting('showProviderTagline') !== false && providerTagline) {
        taglineEl.innerHTML = sanitizeTaglineHtml(providerTagline, char.name);
        taglineRow.hidden = false;
    } else {
        taglineEl.textContent = '';
        taglineRow.hidden = true;
    }
}

// The pictures an avatar <img> falls back to in its onerror: a '?' tile, and a blank one.
const AVATAR_FALLBACK_SVG = 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><rect fill=%22%23333%22 width=%22100%22 height=%22100%22/><text x=%2250%22 y=%2255%22 text-anchor=%22middle%22 fill=%22%23666%22 font-size=%2240%22>?</text></svg>';
const AVATAR_BLANK_SVG = 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><rect fill=%22%23333%22 width=%22100%22 height=%22100%22/></svg>';

// The server's thumbnail widths (THUMB_SIZES in server/lib/thumb-cache.js, held equal by a test).
const THUMB_SIZES = Object.freeze([96, 192, 384, 512, 768, 1280, 1920]);

/**
 * A stored picture's thumbnail URL, its one spelling; the size snaps to the server's widths so
 * alike renders share a file.
 * @param {'avatar'|'media'|'background'|'persona'} kind
 * @param {string} id the row's id
 * @param {number} size the rendered width in device pixels
 * @param {number} [bust] a cache-bust token for a picture replaced in place
 * @returns {string} the URL, '' without an id
 */
function thumbUrl(kind, id, size, bust) {
    if (!id) return '';
    const want = Number(size) || 512;
    const rung = THUMB_SIZES.reduce((best, s) => (Math.abs(s - want) < Math.abs(best - want) ? s : best), THUMB_SIZES[0]);
    return serverUrl(`/thumbs/${kind}/${encodeURIComponent(id)}?s=${rung}${bust ? `&v=${bust}` : ''}`);
}

// Small-render tier (chat rows, header thumbs, mini-cards): 192px covers retina at ~96 css px.
function getCharacterAvatarSmallThumbUrl(charOrId) {
    return getCharacterAvatarThumbUrl(charOrId, 192);
}

// Grid tier: 512px baseline, sharp resizes on demand and caches on disk. A bigger render
// (the chat gallery hero) passes its own size.
function getCharacterAvatarThumbUrl(charOrId, size = 512) {
    const id = avatarKeyOf(charOrId);
    if (!id) return '';
    ensureAvatarCacheBustLoaded();
    return thumbUrl('avatar', id, size, _avatarCacheBust.get(id));
}

// Per-avatar cache-bust tokens for in-place image swaps, persisted so the new image survives a reload.
const AVATAR_CACHEBUST_KEY = 'cl_avatarCacheBust_v2'; // v1 keyed on {uuid}.png; abandoned, not translated
const AVATAR_CACHEBUST_CAP = 600;
const _avatarCacheBust = new Map();
// Loaded on first touch: the key is per-account, and the handle exists only once the session
// probe lands.
let _avatarCacheBustLoaded = false;
function ensureAvatarCacheBustLoaded() {
    if (_avatarCacheBustLoaded) return;
    _avatarCacheBustLoaded = true;
    try {
        const raw = localStorage.getItem(userScopedKey(AVATAR_CACHEBUST_KEY));
        if (raw) for (const [k, v] of Object.entries(JSON.parse(raw))) _avatarCacheBust.set(k, v);
    } catch { /* blocked storage or a torn value: no busts carried over */ }
}
// one character or id, or a list or Set of them: a feed flush naming several pictures writes the map once
function bumpAvatarCacheBust(charOrIds) {
    const list = typeof charOrIds !== 'string' && typeof charOrIds?.[Symbol.iterator] === 'function' ? [...charOrIds] : [charOrIds];
    const ids = list.map(avatarKeyOf).filter(Boolean);
    if (!ids.length) return;
    ensureAvatarCacheBustLoaded();
    const now = Date.now();
    for (const id of ids) _avatarCacheBust.set(id, now);
    if (_avatarCacheBust.size > AVATAR_CACHEBUST_CAP) {
        // Drop oldest; those swaps aged out of the browser cache long ago.
        const stale = [..._avatarCacheBust.entries()].sort((a, b) => a[1] - b[1]).slice(0, _avatarCacheBust.size - AVATAR_CACHEBUST_CAP);
        for (const [k] of stale) _avatarCacheBust.delete(k);
    }
    try { localStorage.setItem(userScopedKey(AVATAR_CACHEBUST_KEY), JSON.stringify(Object.fromEntries(_avatarCacheBust))); } catch { /* storage full or blocked: the busts last this session */ }
}

/**
 * Replace a character's picture, the one door every replace goes through. Throws the server's
 * refusal; a landed picture busts this tab's cache and is announced.
 * @param {string} charId
 * @param {Blob|ArrayBuffer|Uint8Array} bytes - any image; the server converts it and keeps the card off it
 */
async function editAvatar(charId, bytes) {
    const resp = await apiRequest(`/characters/${encodeURIComponent(charId)}/avatar`, 'PUT', bytes,
        { raw: true, headers: { 'Content-Type': 'application/octet-stream' } });
    await readAnswer(resp);
    bumpAvatarCacheBust(charId);
    // the picture never goes through writeCardFields, so an open conversation hears of it here
    notifyCharacterChanged(charId);
}

/**
 * Render a lorebook entry as HTML
 * @param {Object} entry - Lorebook entry object
 * @param {number} index - Entry index
 * @returns {string} HTML string
 */
function renderLorebookEntryHtml(entry, index) {
    const keys = entry.keys || entry.key || [];
    const keyArr = Array.isArray(keys) ? keys : (keys ? [keys] : []);
    // V2 embedded uses secondary_keys; native world uses keysecondary.
    const secondaryKeys = entry.secondary_keys || entry.keysecondary || [];
    const secondaryKeyArr = Array.isArray(secondaryKeys) ? secondaryKeys : (secondaryKeys ? [secondaryKeys] : []);
    const content = entry.content || '';
    const name = entry.comment || entry.name || `Entry ${index + 1}`;
    // Embedded V2 entries use `enabled`; native world entries use `disable` (inverted).
    const enabled = entry.disable !== undefined ? !entry.disable : entry.enabled !== false;
    // "Selective" is only meaningful when secondary keys actually exist (filters the match).
    const selective = secondaryKeyArr.length > 0;
    const constant = entry.constant;

    let statusItems = [];
    if (selective) statusItems.push('<span class="lorebox-stat-sel" title="Selective: triggers only when both primary AND secondary keys match"><i class="fa-solid fa-filter"></i>Selective</span>');
    if (constant) statusItems.push('<span class="lorebox-stat-const" title="Constant: always injected into context"><i class="fa-solid fa-thumbtack"></i>Constant</span>');
    statusItems.push(`<span class="${enabled ? 'lorebox-stat-on' : 'lorebox-stat-off'}" title="${enabled ? 'Entry is active' : 'Entry is disabled'}"><i class="fa-solid fa-${enabled ? 'circle-check' : 'circle-xmark'}"></i>${enabled ? 'Active' : 'Off'}</span>`);
    const statusRow = statusItems.join('<span class="lorebox-stat-sep"> · </span>');
    
    const keyChips = keyArr.length 
        ? keyArr.map(k => `<span class="lorebox-key-chip">${escapeHtml(k.trim())}</span>`).join('')
        : '<span class="lorebox-empty-keys">no keys</span>';
    
    const secondaryChips = secondaryKeyArr.length
        ? secondaryKeyArr.map(k => `<span class="lorebox-key-chip lorebox-secondary">${escapeHtml(k.trim())}</span>`).join('')
        : '';
    
    return `<details class="lorebox-entry${enabled ? '' : ' lorebox-disabled'}"><summary><i class="fa-solid fa-caret-right lorebox-arrow"></i><i class="fa-solid fa-file-lines lorebox-icon"></i><span class="lorebox-name">${escapeHtml(name.trim())}</span></summary><div class="lorebox-entry-body"><div class="lorebox-status-row">${statusRow}</div><div class="lorebox-section"><div class="lorebox-section-header"><i class="fa-solid fa-key"></i> Keys</div><div class="lorebox-keys-list">${keyChips}</div></div>${secondaryChips ? `<div class="lorebox-section"><div class="lorebox-section-header"><i class="fa-solid fa-key"></i> Secondary Keys</div><div class="lorebox-keys-list">${secondaryChips}</div></div>` : ''}<div class="lorebox-section"><div class="lorebox-section-header"><i class="fa-solid fa-align-left"></i> Content</div><div class="lorebox-content-box">${escapeHtml(content.trim()) || '<em>No content</em>'}</div></div></div></details>`;
}

/**
 * Render lorebook entries for modal display
 * @param {Array} entries - Array of lorebook entries
 * @returns {string} HTML string
 */
function renderLorebookEntriesHtml(entries) {
    if (!entries || !entries.length) return '';
    return entries.map((entry, i) => renderLorebookEntryHtml(entry, i)).join('');
}

// Rendered linked-world box cache (name to {count, html}): every save repopulates the box, so a big
// world isnt refetched; busted on world writes.
const _linkedWorldRenderCache = new Map();
function invalidateLinkedWorldRenderCache(worldName) {
    if (worldName) _linkedWorldRenderCache.delete(worldName);
    else _linkedWorldRenderCache.clear();
}

/**
 * Announces a world change, THE call every world writer makes: each surface holding rows decides
 * if it cares and re-reads.
 * @param {string|null} worldName the world that changed, or null to make every listener re-read
 * @param {string} [source] the writer, so its own surface can ignore the echo
 */
function notifyWorldsChanged(worldName = null, source = '') {
    invalidateLinkedWorldRenderCache(worldName || undefined);
    document.dispatchEvent(new CustomEvent('cl-worlds-changed', {
        detail: { world: worldName || null, source: source || '' },
    }));
}

// Fetch + render one world through the shared cache. World files store entries as an
// object keyed by uid; flatten to an array for the renderer.
async function getRenderedWorldCached(worldName) {
    const cached = _linkedWorldRenderCache.get(worldName);
    if (cached) return cached;
    let data = null;
    try { data = await getWorldInfoData(worldName); } catch (_) { /* missing or unreadable */ }
    const entries = data?.entries ? Object.values(data.entries).filter(e => e && typeof e === 'object') : [];
    const out = { count: entries.length, html: entries.length ? renderLorebookEntriesHtml(entries) : '' };
    _linkedWorldRenderCache.set(worldName, out);
    return out;
}

// Same-gen ordering token: aux add/remove repopulate without navigating, so last-started wins over
// a slow older run.
let _linkedBoxRunId = 0;

/**
 * Populates the details' Linked Lorebook box from the primary link and the additional books; async
 * and gen-guarded, never blocking paint.
 * @param {Object} char
 */
async function populateLinkedLorebookBox(char) {
    const box = document.getElementById('modalLinkedLorebookBox');
    if (!box) return;
    // Reset like every async modal surface: hidden until this char's data lands, so a slow
    // no-opener settings fetch can't leave the previous character's box painted.
    box.hidden = true;
    const worldName = char?.data?.extensions?.world || '';

    const gen = _modalOpenGen;
    const run = ++_linkedBoxRunId;
    const stale = () => gen !== _modalOpenGen || run !== _linkedBoxRunId;
    let auxBooks = [];
    try { auxBooks = await getCharLinkedLorebooks(char?.id) || []; } catch (_) { /* shown without aux */ }
    if (stale()) return;
    // The head renders as the main content; the rest of the list renders once each.
    auxBooks = auxBooks.filter(b => b && b !== worldName);
    if (!worldName && !auxBooks.length) { box.hidden = true; return; }

    const nameEl = document.getElementById('linkedLorebookName');
    const countEl = document.getElementById('linkedLorebookEntryCount');
    const contentEl = document.getElementById('modalLinkedLorebookContent');
    const headName = worldName || auxBooks[0] || '';
    const extraCount = worldName ? auxBooks.length : Math.max(0, auxBooks.length - 1);
    if (nameEl) nameEl.textContent = extraCount ? `${headName} +${extraCount}` : headName;

    const primary = worldName ? await getRenderedWorldCached(worldName) : { count: 0, html: '' };
    if (stale()) return; // navigated away or superseded mid-fetch
    const auxRendered = [];
    for (const b of auxBooks) {
        const r = await getRenderedWorldCached(b);
        if (stale()) return;
        auxRendered.push({ name: b, ...r });
    }

    const total = primary.count + auxRendered.reduce((n, r) => n + r.count, 0);
    // Nothing renderable anywhere (empty or missing files) hides the box, same as the
    // old primary-only behavior.
    if (total === 0) { box.hidden = true; return; }

    const auxHtml = auxRendered.map(r => `
        <details class="detail-collapsible linked-aux-book">
            <summary><i class="fa-solid fa-book"></i> ${escapeHtml(r.name)} (${r.count} ${r.count === 1 ? 'entry' : 'entries'})</summary>
            <div class="detail-collapsible-body">${r.html}</div>
        </details>`).join('');

    if (countEl) countEl.innerText = total;
    if (contentEl) contentEl.innerHTML = primary.html + auxHtml;
    box.hidden = false;
}

// Handles both class systems (cl-modal uses .visible, confirm-modal uses .hidden).
function hideModal(modalId) {
    const el = document.getElementById(modalId);
    if (!el) return;
    if (el.classList.contains('cl-modal')) el.classList.remove('visible');
    else el.classList.add('hidden');
}

function escapeHtml(text) {
    return String(text ?? '')
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

// CSS ignores <!-- and -->, but DOMPurify drops a <style> holding <!--; a space per marker keeps the text either side apart
function stripStyleCommentMarkers(node, data) {
    if (data.tagName !== 'style' || node.namespaceURI !== 'http://www.w3.org/1999/xhtml') return;
    const text = node.textContent;
    if (text.includes('<!--') || text.includes('-->')) node.textContent = text.replace(/<!--|-->/g, ' ');
}

/**
 * Sanitizes HTML, failing closed (escaped) without DOMPurify; forces rel=noopener noreferrer on
 * targeted links.
 * @param {string} html - Pre-formatted HTML to sanitize
 * @param {object} [config] - DOMPurify config
 * @returns {string} Sanitized HTML, or escaped text if DOMPurify is missing
 */
function safePurify(html, config) {
    if (html == null || html === '') return '';
    if (typeof DOMPurify === 'undefined' || !DOMPurify || typeof DOMPurify.sanitize !== 'function') {
        return escapeHtml(html);
    }
    let sanitized;
    DOMPurify.addHook('uponSanitizeElement', stripStyleCommentMarkers);
    try {
        sanitized = DOMPurify.sanitize(html, config || {});
    } catch {
        return escapeHtml(html);
    } finally {
        DOMPurify.removeHook('uponSanitizeElement', stripStyleCommentMarkers);
    }
    // Tab-nabbing post-pass: every <a target="..."> must have rel="noopener noreferrer"
    if (typeof sanitized === 'string' && sanitized.indexOf('<a') !== -1 && sanitized.indexOf('target') !== -1) {
        const tmp = document.createElement('div');
        tmp.innerHTML = sanitized;
        tmp.querySelectorAll('a[target]').forEach(a => {
            a.setAttribute('rel', 'noopener noreferrer');
        });
        sanitized = tmp.innerHTML;
    }
    return sanitized;
}

// What a rendered card field may carry wherever the page shows it: the standard formatter's tags,
// audio players included.
const CARD_FIELD_PURIFY_CONFIG = Object.freeze({
    ALLOWED_TAGS: ['p', 'br', 'strong', 'b', 'em', 'i', 'u', 's', 'strike', 'del',
        'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote', 'code', 'pre',
        'ul', 'ol', 'li', 'a', 'img', 'span', 'div', 'hr', 'table',
        'thead', 'tbody', 'tr', 'th', 'td', 'sup', 'sub', 'details', 'summary', 'audio', 'source'],
    ALLOWED_ATTR: ['href', 'src', 'alt', 'title', 'class', 'style', 'target', 'rel', 'width', 'height', 'loading', 'controls', 'preload', 'type'],
    ALLOW_DATA_ATTR: false,
});

/** A card field (description, first message, a greeting) as page html: formatted, then purified. */
function cardFieldHtml(text, charName) {
    return safePurify(formatRichText(text, charName), CARD_FIELD_PURIFY_CONFIG);
}

/** The details tab's alternate greetings list, the paint and the localized repaint alike. */
function altGreetingsListHtml(greetings, charName) {
    return greetings.map((g, i) =>
        `<div class="alt-greeting-item"><strong class="text-accent">#${i + 1}:</strong> <span>${cardFieldHtml((g || '').trim(), charName)}</span></div>`
    ).join('');
}

function formatNumber(num) {
    if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
    if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
    return String(num);
}

// Token shape is the caller's: chat runs inline markdown before the restore, so its token must
// match no markdown regex.
function createPlaceholderStore(makeToken) {
    const items = [];
    return {
        add(html) {
            const token = makeToken(items.length);
            items.push({ token, html });
            return token;
        },
        restore(str) {
            let out = str;
            // Newest first: a container's html can hold earlier tokens, and oldest-first leaked the sentinel;
            // a function replacement keeps $&.
            for (let i = items.length - 1; i >= 0; i--) out = out.replace(items[i].token, () => items[i].html);
            return out;
        }
    };
}

// Tags built from markdown; esc escapes each attribute value: escapeHtml for text, quoteAttr for
// author html, whose entities already mean what they say.
const quoteAttr = (s) => String(s).replace(/"/g, '&quot;');
function embeddedImageHtml(src, alt, esc) {
    return `<img src="${esc(src)}"${alt ? ` alt="${esc(alt)}"` : ''} class="embedded-image" loading="lazy">`;
}
function embeddedLinkedImageHtml(href, src, alt, esc) {
    const safeLink = /^https?:\/\//i.test(href) ? href : '#';
    return `<a href="${esc(safeLink)}" target="_blank" rel="noopener">${embeddedImageHtml(src, alt, esc)}</a>`;
}
function embeddedLinkHtml(href, innerHtml, esc) {
    return `<a href="${esc(href)}" target="_blank" rel="noopener" class="embedded-link">${innerHtml}</a>`;
}

// Media and link extraction for the card and chat formatters; chat opts out of audio (its config
// strips <audio>). A src goes back escaped.
function extractMediaAndLinks(text, add, { audio = true, linkText = escapeHtml } = {}) {
    let out = text;

    // Preserve existing HTML img tags (allow http/https and local paths)
    out = out.replace(/<img\s+[^>]*src=["']((?:https?:\/\/|\/)[^"'\s<>]+)["'][^>]*\/?>/gi, (match, src) => {
        return add(`<img src="${escapeHtml(src)}" class="embedded-image" loading="lazy">`);
    });

    if (audio) {
        // Rebuild audio players from their safe src alone, dropping author attributes so an <audio onerror>
        // cant ride through.
        out = out.replace(/<audio[^>]*>[\s\S]*?<\/audio>/gi, (match) => {
            const m = match.match(/\ssrc=["']((?:https?:\/\/|\/)[^"'\s<>]+)["']/i);
            if (!m) return '';
            const src = m[1];
            const ext = (src.split(/[?#]/)[0].split('.').pop() || '').toLowerCase();
            const typeAttr = /^(mp3|wav|ogg|m4a|flac|aac)$/.test(ext) ? ` type="audio/${ext}"` : '';
            return add(`<audio controls class="audio-player embedded-audio" preload="metadata"><source src="${escapeHtml(src)}"${typeAttr}>Your browser does not support audio.</audio>`);
        });

        // Convert audio source tags to full audio players
        out = out.replace(/<source\s+[^>]*src=["']((?:https?:\/\/|\/)[^"'\s<>]+\.(?:mp3|wav|ogg|m4a|flac|aac))["'][^>]*\/?>/gi, (match, src) => {
            const ext = src.split('.').pop().toLowerCase();
            return add(`<audio controls class="audio-player embedded-audio" preload="metadata"><source src="${escapeHtml(src)}" type="audio/${ext}">Your browser does not support audio.</audio>`);
        });
    }

    // Convert linked images: [![alt](img-url)](link-url)
    out = out.replace(/\[\!\[([^\]]*)\]\(((?:[^()]|\([^()]*\))+|[^)]+)\)\]\(([^)]+)\)/g, (match, alt, imgSrc, linkHref) => {
        // Allow http/https URLs and local paths (starting with /)
        if (!imgSrc.match(/^(https?:\/\/|\/)/i)) return match;
        return add(embeddedLinkedImageHtml(linkHref, imgSrc, alt, escapeHtml));
    });

    // Convert standalone markdown images: ![alt](url) or ![alt](url "title")
    out = out.replace(/!\[([^\]]*)\]\(((?:[^\s()]|\([^\s()]*\))+|[^)\s]+)(?:\s+"[^"]*")?\)/g, (match, alt, src) => {
        // Allow http/https URLs and local paths (starting with /)
        if (!src.match(/^(https?:\/\/|\/)/i)) return match;
        return add(embeddedImageHtml(src, alt, escapeHtml));
    });

    if (audio) {
        // Convert markdown audio links: [any text](url.mp3) or [??](url.mp3)
        out = out.replace(/\[([^\]]*)\]\(((?:https?:\/\/|\/)[^)\s]+\.(?:mp3|wav|ogg|m4a|flac|aac))(?:\s+"[^"]*)?\)/gi, (match, text, src) => {
            const ext = src.split('.').pop().toLowerCase();
            return add(`<audio controls class="audio-player embedded-audio" preload="metadata" title="${escapeHtml(text || 'Audio')}"><source src="${escapeHtml(src)}" type="audio/${ext}">Your browser does not support audio.</audio>`);
        });
    }

    // Convert markdown links: [text](url)
    out = out.replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, (match, text, href) => add(embeddedLinkHtml(href, linkText(text), escapeHtml)));

    return out;
}

// The persona pronoun macros: the persona's key and the word an empty form answers (the server's PRONOUN_MACROS).
const PERSONA_PRONOUN_MACROS = { sub: ['sub', 'they'], obj: ['obj', 'them'], poss: ['poss', 'their'], poss_p: ['possP', 'theirs'], ref: ['ref', 'themselves'] };

// the server's pronounInCase, spelled the same: lower as stored, Capitalised, UPPER, any other mix as stored
function pronounInCase(written, form, word) {
    const text = (typeof form === 'string' && form.trim()) || word;
    const name = String(written ?? '').trim();
    if (name === name.toLowerCase()) return text;
    if (name === name.toUpperCase()) return text.toUpperCase();
    if (name === name[0].toUpperCase() + name.slice(1).toLowerCase()) {
        const [first = '', ...rest] = text;
        return first.toUpperCase() + rest.join('');
    }
    return text;
}

/** The five pronoun macros in text answered from a persona's forms, each word through wrap; no forms leaves them raw. */
function answerPronounMacros(text, forms, wrap = (word) => word) {
    if (!forms) return text;
    return text.replace(/\{\{(sub|obj|poss_p|poss|ref)\}\}/gi, (m, written) => {
        const [key, word] = PERSONA_PRONOUN_MACROS[written.toLowerCase()];
        return wrap(pronounInCase(written, forms[key], word));
    });
}

// The macros land after everything is escaped, so each name (card data, maybe markup) is escaped
// on either branch. userName, pronouns: the caller's persona.
function substituteMacros(html, charName, { spans = true, userName = null, pronouns = undefined } = {}) {
    const personaName = userName || getPersonaName();
    // a caller naming its own persona hands its pronouns too, or the five stay as written
    const forms = pronouns !== undefined ? pronouns : (userName ? null : getPersonaPronouns());
    const named = charName || '{{char}}';
    const user = spans ? `<span class="placeholder-user">${escapeHtml(personaName)}</span>` : escapeHtml(personaName);
    const char = spans ? `<span class="placeholder-char">${escapeHtml(named)}</span>` : escapeHtml(named);
    const pronoun = spans ? (word) => `<span class="placeholder-user">${escapeHtml(word)}</span>` : escapeHtml;
    return answerPronounMacros(html
        .replace(/\{\{user\}\}/gi, () => user)
        .replace(/\{\{char\}\}/gi, () => char), forms, pronoun);
}

// Bold/italic pass. The lookbehind guards keep markers out of URLs, paths and attribute values.
function applyInlineEmphasis(html, { strike = false, emClass = '' } = {}) {
    const em = emClass ? `<em class="${emClass}">` : '<em>';
    let out = html;

    // Bold: **text** or __text__
    out = out.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    out = out.replace(/__(.+?)__/g, '<strong>$1</strong>');

    // Italic: *text* or _text_ (but not inside words or URLs)
    // Require whitespace before underscore to avoid matching in file paths like localized_media_123
    out = out.replace(/(?<![\w*])\*([^*]+?)\*(?![\w*])/g, `${em}$1</em>`);
    out = out.replace(/(?:^|(?<=\s))_([^_]+?)_(?![\w_])/g, `${em}$1</em>`);

    // An emphasised word in a line leaves the outer pair unmatched; any asterisk left is unpaired, so a
    // line wrapped in one is that wrapper.
    out = out.split('\n').map(line => {
        const m = line.match(/^(\s*)\*(\S.*\S|\S)\*(\s*)$/);
        // a run of nothing but asterisks is a scene divider, not an emphasis wrapper
        if (!m || !/[^*]/.test(m[2])) return line;
        return `${m[1]}${em}${m[2]}</em>${m[3]}`;
    }).join('\n');

    if (strike) out = out.replace(/~~([^~]+?)~~/g, '<del>$1</del>');

    return out;
}

// Block markdown in a note or card field (never chat text): headings, lists, rules on their own
// lines; nothing inside a line.
function applyMarkdownBlocks(text) {
    const out = [];
    let list = null;
    const flush = () => { if (list) { out.push(`<${list.tag}>${list.items.map(i => `<li>${i}</li>`).join('')}</${list.tag}>`); list = null; } };
    for (const line of text.split('\n')) {
        let m;
        if ((m = /^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/.exec(line))) { flush(); out.push(`<h${m[1].length} class="embedded-heading">${m[2]}</h${m[1].length}>`); continue; }
        if (/^\s{0,3}(?:-{3,}|\*{3,}|_{3,})\s*$/.test(line)) { flush(); out.push('<hr>'); continue; }
        if ((m = /^\s{0,3}[-*+]\s+(.+)$/.exec(line))) { if (!list || list.tag !== 'ul') { flush(); list = { tag: 'ul', items: [] }; } list.items.push(m[1]); continue; }
        if ((m = /^\s{0,3}\d+[.)]\s+(.+)$/.exec(line))) { if (!list || list.tag !== 'ol') { flush(); list = { tag: 'ol', items: [] }; } list.items.push(m[1]); continue; }
        flush();
        out.push(line);
    }
    flush();
    return out.join('\n');
}

// a line break the newline pass made beside a block is the block's own edge, not a gap
const BLOCK_EDGE_BR = [[/(<\/(?:h[1-6]|ul|ol)>|<hr>)(?:<br>)+/g, '$1'], [/(?:<br>)+(<(?:h[1-6]\b|ul>|ol>|hr>))/g, '$1']];
function trimBlockEdgeBreaks(html) {
    return BLOCK_EDGE_BR.reduce((h, [re, to]) => h.replace(re, to), html);
}

function formatRichText(text, charName = '', preserveHtml = false, opts = {}) {
    if (!text) return "";
    // a stored text (macros: false) answers no macro but the pronoun forms a caller hands, as formatChatText
    const macros = (t) => (opts.macros !== false ? substituteMacros(t, charName) : answerPronounMacros(t, opts.pronouns, escapeHtml));
    
    let processedText = text.trim();
    
    // Normalize line endings (Windows \r\n and old Mac \r to Unix \n)
    processedText = processedText.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    processedText = processedText
        .replace(/\x00/g, '')               // NUL delimits the placeholder tokens; card text never forges one
        .replace(/[ \t]+$/gm, '')           // Remove trailing spaces/tabs from each line
        .replace(/\n{4,}/g, '\n\n\n')       // Collapse 4+ newlines to 3 (double paragraph break)
        .replace(/[ \t]{2,}/g, ' ');        // Collapse multiple spaces/tabs to single space
    
    // If preserving HTML (for creator notes with custom styling), use hybrid approach
    if (preserveHtml) {
        // Detect content type for appropriate processing
        // Ultra CSS: <style> tag near the START of content (first 200 chars) = fully styled card
        const hasStyleTagAtStart = /^[\s\S]{0,200}<style[^>]*>[\s\S]{50,}<\/style>/i.test(processedText);
        // Style tag anywhere (for later exclusion from markdown processing)
        const hasStyleTag = /<style[^>]*>[\s\S]*?<\/style>/i.test(processedText);
        const hasInlineStyles = /style\s*=\s*["'][^"']*(?:display|position|flex|grid)[^"']*["']/i.test(processedText);
        
        // Ultra CSS mode: <style> tag at START with substantial CSS - touch almost nothing
        if (hasStyleTagAtStart) {
            // Only convert markdown images (safe - won't be in CSS)
            processedText = processedText.replace(/!\[([^\]]*)\]\(((?:[^\s()]|\([^\s()]*\))+|[^)\s]+)(?:\s*=[^)]*)?(?:\s+"[^"]*")?\)/g, (match, alt, src) => {
                // Allow http/https URLs and local paths (starting with /)
                if (!src.match(/^(https?:\/\/|\/)/i)) return match;
                return embeddedImageHtml(src, alt, quoteAttr);
            });

            processedText = macros(processedText);

            return processedText;
        }
        
        // For content with <style> at the end (footer banners), extract and protect it
        let styleBlocks = [];
        if (hasStyleTag) {
            processedText = processedText.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, (match) => {
                const placeholder = `\x00STYLEBLOCK${styleBlocks.length}\x00`;
                styleBlocks.push(match);
                return placeholder;
            });
        }
        
        // Pure CSS mode: has inline styles with layout properties - skip text formatting
        const isPureCssMode = hasInlineStyles;
        
        // Convert markdown images and links (safe for all modes):
        
        // Convert linked images: [![alt](img-url)](link-url)
        processedText = processedText.replace(/\[\!\[([^\]]*)\]\(((?:[^\s()]|\([^\s()]*\))+|[^)\s]+)(?:\s*=[^)]*)?(?:\s+"[^"]*")?\)\]\(([^)]+)\)/g, (match, alt, imgSrc, linkHref) => {
            // Allow http/https URLs and local paths (starting with /)
            if (!imgSrc.match(/^(https?:\/\/|\/)/i)) return match;
            return embeddedLinkedImageHtml(linkHref, imgSrc, alt, quoteAttr);
        });

        // Convert standalone markdown images: ![alt](url) or ![alt](url =WxH) or ![alt](url "title")
        processedText = processedText.replace(/!\[([^\]]*)\]\(((?:[^\s()]|\([^\s()]*\))+|[^)\s]+)(?:\s*=[^)]*)?(?:\s+"[^"]*")?\)/g, (match, alt, src) => {
            // Allow http/https URLs and local paths (starting with /)
            if (!src.match(/^(https?:\/\/|\/)/i)) return match;
            return embeddedImageHtml(src, alt, quoteAttr);
        });

        // Convert markdown links: [text](url) - but not image links we just processed
        processedText = processedText.replace(/(?<!!)\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, (match, text, href) => embeddedLinkHtml(href, text, quoteAttr));
        
        // Markdown formatting, not in pure CSS mode; not the shared applyInlineEmphasis set, since this
        // runs over unescaped author HTML and must dodge attributes.
        if (!isPureCssMode) {
            // Bold: **text** or __text__
            processedText = processedText.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
            processedText = processedText.replace(/__(.+?)__/g, '<strong>$1</strong>');

            // Italic: *text* or _text_, the lookbehind keeping it out of URLs, paths and HTML attributes
            processedText = processedText.replace(/(?<![\w*/"=])\*([^*\n]+?)\*(?![\w*])/g, '<em>$1</em>');
            processedText = processedText.replace(/(?<![\w_\/."'=])\s_([^_\n]+?)_(?![\w_])/g, ' <em>$1</em>');

            // Strikethrough: ~~text~~
            processedText = processedText.replace(/~~([^~]+?)~~/g, '<del>$1</del>');
        }

        processedText = macros(processedText);

        // Newline handling based on mode
        // Only skip newlines if it's heavily structured HTML (many divs/tables) or has layout CSS
        const divCount = (processedText.match(/<div/gi) || []).length;
        const isHeavyHtml = divCount > 5 || /<table[^>]*>/i.test(processedText);
        
        if (isPureCssMode || isHeavyHtml) {
            // Pure CSS or heavy HTML mode: Don't convert newlines - layout handles it
        } else {
            // Mixed/Light HTML / Markdown mode: the block marks, then the newlines
            // But be careful around HTML tags - don't add breaks inside tag sequences
            processedText = applyMarkdownBlocks(processedText);
            processedText = processedText.replace(/\n\n+/g, '<br><br>');
            processedText = processedText.replace(/([^>])\n([^<])/g, '$1<br>$2');
            processedText = trimBlockEdgeBreaks(processedText);
        }
        
        styleBlocks.forEach((block, i) => {
            processedText = processedText.replace(`\x00STYLEBLOCK${i}\x00`, block);
        });
        
        return processedText;
    }
    
    // Standard mode escapes HTML. Lifted tags return only after every text and line pass, under a token
    // no markdown, quote or macro pattern matches.
    const ph = createPlaceholderStore(i => `\x00CLRICH${i}\x00`);
    // the inline passes, over the text and over a lifted link's or heading's own text alike
    const inline = (s) => {
        let h = escapeHtml(s);
        h = macros(h);
        h = applyInlineEmphasis(h);
        // Quoted text: "text"
        return h.replace(/&quot;(.+?)&quot;/g, '<span class="quoted-text">"$1"</span>');
    };

    processedText = extractMediaAndLinks(processedText, ph.add, { linkText: inline });

    // Preserve HTML heading tags
    processedText = processedText.replace(/<(h[1-6])>([^<]*)<\/\1>/gi, (match, tag, content) => {
        return ph.add(`<${tag} class="embedded-heading">${inline(content)}</${tag}>`);
    });

    let formatted = inline(processedText);

    // Convert line breaks - use paragraph breaks for double newlines, single <br> for single
    // Also handle literal \n (escaped backslash-n from JSON) as actual newlines
    formatted = formatted.replace(/\\n/g, '\n');         // Convert literal \n to actual newlines first
    formatted = applyMarkdownBlocks(formatted);          // Headings, lists and rules on their own lines
    formatted = formatted.replace(/\n\n+/g, '</p><p>');  // Double+ newlines become paragraph breaks
    formatted = formatted.replace(/\n/g, '<br>');        // Single newlines become line breaks
    formatted = '<p>' + formatted + '</p>';              // Wrap in paragraphs
    formatted = ph.restore(formatted);
    formatted = trimBlockEdgeBreaks(formatted);
    // a block sits between paragraphs, never inside one
    formatted = formatted.replace(/(<(?:h[1-6][^>]*>[\s\S]*?<\/h[1-6]>|ul>[\s\S]*?<\/ul>|ol>[\s\S]*?<\/ol>|hr>))/g, '</p>$1<p>');
    formatted = formatted.replace(/<p><\/p>/g, '');      // Remove empty paragraphs
    
    return formatted;
}

// Dialogue quotes as opener and closer; straight quotes arrive as &quot; (escaped already), curly ' is left out (usually an apostrophe).
const CHAT_QUOTE_PAIRS = { default: [['“', '”'], ['&quot;', '&quot;']], extended: [['「', '」'], ['『', '』'], ['＂', '＂'], ['«', '»']] };
// one line only, as models emit odd quote counts
const chatQuoteRe = (pairs) => new RegExp(pairs.map(([open, close]) => `${open}([^\\n]*?)${close}`).join('|'), 'g');
const CHAT_QUOTE_RE_DEFAULT = chatQuoteRe(CHAT_QUOTE_PAIRS.default);
const CHAT_QUOTE_RE_EXTENDED = chatQuoteRe([...CHAT_QUOTE_PAIRS.default, ...CHAT_QUOTE_PAIRS.extended]);

function wrapChatQuotes(html, families) {
    const re = families === 'extended' ? CHAT_QUOTE_RE_EXTENDED : CHAT_QUOTE_RE_DEFAULT;
    return html.replace(re, function () {
        const match = arguments[0];
        const caps = Array.prototype.slice.call(arguments, 1, -2);
        const inner = caps.find(c => typeof c === 'string');
        if (!inner || !inner.trim()) return match;
        // the whole match is wrapped so the glyphs stay inside the span, entities included
        return `<span class="cl-quote">${match}</span>`;
    });
}

// Inline presentational tags a message may carry verbatim: no div or style (the island and iframe
// paths own those); [^<>] bounds attributes.
const INLINE_HTML_RE = /<\/?(?:b|i|u|s|em|strong|del|mark|small|sub|sup|code|kbd|abbr|q|br|font|span)(?:\s[^<>]*)?\/?>/gi;

// Block-level HTML islands: a BALANCED run from a block open tag to its close, lifted verbatim, the
// sanitizer re-validating it; unbalanced stays literal.
const BLOCK_HTML_RE = /<(div|details|table|blockquote|h[1-6]|ul|ol|p|center|figure|section|article|aside)(?=[\s>])/gi;
const VOID_BLOCK_HTML_RE = /<hr\b[^<>]*\/?>/gi;

function extractChatHtmlIslands(src, add, blockTokens) {
    let out = '';
    let pos = 0;
    BLOCK_HTML_RE.lastIndex = 0;
    let m;
    while ((m = BLOCK_HTML_RE.exec(src)) !== null) {
        const start = m.index;
        if (start < pos) continue;   // inside the island just taken
        const root = m[1].toLowerCase();
        const walker = new RegExp(`<(/?)${root}(?=[\\s>/])[^<>]*>`, 'gi');
        walker.lastIndex = start;
        let depth = 0;
        let end = -1;
        let w;
        while ((w = walker.exec(src)) !== null) {
            if (w[1]) { depth--; if (depth === 0) { end = walker.lastIndex; break; } }
            else depth++;
        }
        if (end === -1) continue;    // unbalanced: stays literal
        const token = add(src.slice(start, end));
        blockTokens.add(token);
        // Own line either side, so the paragraphizer sees the token as a block and never
        // wraps it in a <p>.
        out += src.slice(pos, start) + '\n' + token + '\n';
        pos = end;
        BLOCK_HTML_RE.lastIndex = end;
    }
    out += src.slice(pos);
    // hr has no close, so a bare one is its own island; img is not here, extractMediaAndLinks rebuilds
    // it from its src.
    return out.replace(VOID_BLOCK_HTML_RE, (tag) => {
        const token = add(tag);
        blockTokens.add(token);
        return '\n' + token + '\n';
    });
}

// A model stopping mid-emphasis leaves the rest italic; only asterisks that can delimit count, so
// "5 * 3 = 15" stays plain.
function repairChatLine(line) {
    if (!line.trim()) return line;
    let out = line;
    if ((out.match(/(?<=\S)\*|\*(?=\S)/g) || []).length % 2 === 1) out += '*';
    if ((out.match(/"/g) || []).length % 2 === 1) out += '"';
    return out;
}

// The copy button is appended by the renderer, keeping <button> out of the allowlist and the glyph
// out of textContent.
function buildChatCodeBlock(lang, code) {
    const label = String(lang || '').trim().split(/\s+/)[0].replace(/[^\w+#.-]/g, '');
    const cls = label ? ` class="language-${label}"` : '';
    return `<div class="cl-code-block"><div class="cl-code-head"><span class="cl-code-lang">${escapeHtml(label || 'code')}</span></div><pre><code${cls}>${escapeHtml(code)}</code></pre></div>`;
}

// Block markdown on escaped text, each block stored as a placeholder so the paragraph and inline
// passes never re-enter it.
function buildChatBlocks(html, add, blockTokens, { tables = true, emClass = '' } = {}) {
    const inline = (s) => applyInlineEmphasis(s, { strike: true, emClass });
    const store = (markup) => {
        const token = add(markup);
        blockTokens.add(token);
        return token;
    };
    const BULLET = /^ {0,3}[-*+]\s+(.*)$/;
    const NUMBERED = /^ {0,3}\d+[.)]\s+(.*)$/;
    const isRow = (s) => /^\s*\|.*\|\s*$/.test(s);
    const isSep = (s) => /^\s*\|[\s:|-]+\|\s*$/.test(s);

    const lines = html.split('\n');
    const out = [];
    let i = 0;

    while (i < lines.length) {
        const line = lines[i];

        const heading = line.match(/^ {0,3}(#{1,6})\s+(.*)$/);
        if (heading) {
            const lvl = heading[1].length;
            out.push(store(`<h${lvl}>${inline(heading[2].trim())}</h${lvl}>`));
            i++;
            continue;
        }

        if (/^ {0,3}(?:-{3,}|\*{3,}|_{3,})\s*$/.test(line)) {
            out.push(store('<hr>'));
            i++;
            continue;
        }

        // after the escape pass a quoted line starts with &gt;, not >
        if (/^ {0,3}&gt;\s?/.test(line)) {
            const buf = [];
            while (i < lines.length && /^ {0,3}&gt;\s?/.test(lines[i])) {
                buf.push(lines[i].replace(/^ {0,3}&gt;\s?/, ''));
                i++;
            }
            out.push(store(`<blockquote>${inline(buf.join('\n')).replace(/\n/g, '<br>')}</blockquote>`));
            continue;
        }

        if (tables && isRow(line) && !isSep(line) && i + 1 < lines.length && isSep(lines[i + 1])) {
            const cells = (s) => s.trim().replace(/^\||\|$/g, '').split('|').map(c => inline(c.trim()));
            const head = cells(line);
            i += 2;
            const rows = [];
            while (i < lines.length && isRow(lines[i]) && !isSep(lines[i])) {
                rows.push(cells(lines[i]));
                i++;
            }
            const thead = `<thead><tr>${head.map(c => `<th>${c}</th>`).join('')}</tr></thead>`;
            const tbody = rows.length
                ? `<tbody>${rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody>`
                : '';
            // The wrapper comes from the producer because CSS cannot create one, and a
            // <table> cannot be both full width and horizontally scrollable without it.
            out.push(store(`<div class="cl-table-scroll"><table>${thead}${tbody}</table></div>`));
            continue;
        }

        const ordered = !BULLET.test(line) && NUMBERED.test(line);
        if (ordered || BULLET.test(line)) {
            const re = ordered ? NUMBERED : BULLET;
            const items = [];
            while (i < lines.length) {
                if (re.test(lines[i])) {
                    items.push(inline(lines[i].match(re)[1].trim()));
                    i++;
                    continue;
                }
                // A LOOSE list: a blank-line gap is crossed only to another item of the same kind, so ordered
                // lists dont restart at 1.
                let j = i;
                while (j < lines.length && lines[j].trim() === '') j++;
                if (j > i && j < lines.length && re.test(lines[j])) { i = j; continue; }
                break;
            }
            const tag = ordered ? 'ol' : 'ul';
            out.push(store(`<${tag}>${items.map(it => `<li>${it}</li>`).join('')}</${tag}>`));
            continue;
        }

        out.push(line);
        i++;
    }

    return out.join('\n');
}

/**
 * Formats a chat message: everything escaped first, then a known tag set re-emitted. UNSANITISED:
 * pair with safePurify(..., CHAT_PURIFY_CONFIG).
 * @param {string} text - Raw message text
 * @param {string} charName - Character name for {{char}}
 * @param {object} [opts] - macros (false shows the text as stored), userName, pronouns (with macros false, the five pronoun macros alone answered from these forms), macroSpans, quoteFamilies, repairEmphasis, escapeStrings, streaming
 * @returns {string} Formatted HTML
 */
function formatChatText(text, charName = '', opts = {}) {
    if (!text) return '';

    const macroSpans = opts.macroSpans === true;
    const families = opts.quoteFamilies || getSetting('chatQuoteFamilies') || 'default';
    const repair = opts.repairEmphasis !== undefined ? opts.repairEmphasis : getSetting('chatRepairEmphasis') !== false;
    const escapeStrings = opts.escapeStrings !== undefined ? opts.escapeStrings : (getSetting('chatEscapeStrings') || '');
    const streaming = opts.streaming === true;

    // NUL is the placeholder sentinel, so an authored one would let a message forge a token
    let src = String(text).trim()
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .replace(/\x00/g, '')
        .replace(/[ \t]+$/gm, '')
        .replace(/\n{4,}/g, '\n\n\n');

    // a tag or emphasis opener still arriving would draw as text, then vanish: a jolt per line
    if (streaming) src = src.replace(/<\/?(?:[A-Za-z][^<>]*)?$/, '').replace(/(^|\s)[*_]{1,3}$/, '$1');

    const ph = createPlaceholderStore(i => `\x00CLCHAT${i}\x00`);
    const blockTokens = new Set();

    // an unterminated fence never matches, so a half-streamed block stays plain by construction
    if (!streaming) {
        src = src.replace(/(^|\n)[ \t]*(```|~~~)([^\n]*)\n([\s\S]*?)\n[ \t]*\2[ \t]*(?=\n|$)/g, (m, lead, fence, lang, code) => {
            const token = ph.add(buildChatCodeBlock(lang, code));
            blockTokens.add(token);
            return lead + token;
        });
    }
    src = src.replace(/`([^`\n]+)`/g, (m, code) => ph.add(`<code class="cl-code-inline">${escapeHtml(code)}</code>`));

    for (const lit of String(escapeStrings).split(',').map(s => s.trim()).filter(Boolean)) {
        let acc = '', pos = 0, at;
        while ((at = src.indexOf(lit, pos)) !== -1) {
            acc += src.slice(pos, at) + ph.add(escapeHtml(lit));
            pos = at + lit.length;
        }
        src = acc + src.slice(pos);
    }

    // before repair so attr quotes arent counted, before media embeds so island srcs stay put
    const renderHtml = opts.renderHtml !== undefined ? opts.renderHtml : getSetting('chatRenderHtml') !== false;
    if (!streaming && renderHtml) src = extractChatHtmlIslands(src, ph.add, blockTokens);

    // after code extraction so the counts ignore code, before escaping so it counts " not &quot;
    if (repair) src = src.split('\n').map(repairChatLine).join('\n');

    src = extractMediaAndLinks(src, ph.add, { audio: false });

    // Cards ship authored inline markup; only this fixed INLINE list lifts out, the sanitizer
    // re-validating each. Unbalanced block wrappers stay literal.
    src = src.replace(INLINE_HTML_RE, (tag) => ph.add(tag));

    let html = escapeHtml(src);
    html = wrapChatQuotes(html, families);
    html = buildChatBlocks(html, ph.add, blockTokens, { tables: !streaming, emClass: 'cl-narration' });
    html = applyInlineEmphasis(html, { strike: true, emClass: 'cl-narration' });

    // real <p> elements rather than <br> soup, and a block never ends up nested inside one
    const parts = [];
    for (const chunk of html.split(/\n{2,}/)) {
        if (!chunk.trim()) continue;
        let buf = [];
        const flush = () => {
            const t = buf.join('\n').trim();
            buf = [];
            if (t) parts.push(`<p>${t.replace(/\n/g, '<br>')}</p>`);
        };
        for (const line of chunk.split('\n')) {
            if (blockTokens.has(line.trim())) {
                flush();
                parts.push(line.trim());
            } else {
                buf.push(line);
            }
        }
        flush();
    }
    html = parts.join('');

    // a chat message shows as it is stored (macros: false): a sent turn was expanded when it was sent
    if (opts.macros === false) return answerPronounMacros(ph.restore(html), opts.pronouns, escapeHtml);
    return substituteMacros(ph.restore(html), charName, { spans: macroSpans, userName: opts.userName || null, pronouns: opts.pronouns });
}

function sanitizeTaglineHtml(content, charName) {
    if (!content) return '';

    if (getSetting('allowRichTagline') !== true) {
        return escapeHtml(content);
    }

    const formatted = formatRichText(content, charName, true);

    const sanitized = safePurify(formatted, {
        ALLOWED_TAGS: [
            'p', 'br', 'hr', 'div', 'span',
            'strong', 'b', 'em', 'i', 'u', 's', 'del',
            'a', 'img', 'ul', 'ol', 'li', 'blockquote',
            'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
            'center', 'font'
        ],
        ALLOWED_ATTR: [
            'href', 'src', 'alt', 'title', 'target', 'rel', 'class',
            'color', 'size', 'align', 'style'
        ],
        ADD_ATTR: ['target'],
        FORBID_TAGS: ['script', 'iframe', 'object', 'embed', 'form', 'input', 'button', 'select', 'textarea', 'style', 'link'],
        FORBID_ATTR: ['onerror', 'onclick', 'onload', 'onmouseover'],
        ALLOW_UNKNOWN_PROTOCOLS: false,
        KEEP_CONTENT: true
    });

    return sanitizeTaglineStyles(sanitized);
}

function sanitizeTaglineStyles(html) {
    if (!html) return '';

    const container = document.createElement('div');
    container.innerHTML = html;

    const allowedProps = new Set([
        'color', 'background-color', 'font-size', 'font-weight', 'font-style',
        'text-align', 'text-decoration', 'line-height',
        'border', 'border-color', 'border-width', 'border-style', 'border-radius',
        'margin', 'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
        'padding', 'padding-top', 'padding-right', 'padding-bottom', 'padding-left'
    ]);

    const hasUnsafeValue = (value) => {
        const lower = value.toLowerCase();
        return lower.includes('expression(') || lower.includes('javascript:') || lower.includes('url(');
    };

    container.querySelectorAll('[style]').forEach(node => {
        const style = node.getAttribute('style') || '';
        const safeParts = [];
        style.split(';').forEach(part => {
            const [rawProp, rawValue] = part.split(':');
            if (!rawProp || !rawValue) return;
            const prop = rawProp.trim().toLowerCase();
            const value = rawValue.trim();
            if (!allowedProps.has(prop)) return;
            if (!value || hasUnsafeValue(value)) return;
            safeParts.push(`${prop}: ${value}`);
        });

        if (safeParts.length > 0) {
            node.setAttribute('style', safeParts.join('; '));
        } else {
            node.removeAttribute('style');
        }
    });

    return container.innerHTML;
}

/* Upload Helpers */
async function uploadImages(files) {
    if (!activeChar) {
        console.warn('[Gallery] No active character for image upload');
        showToast('No character selected', 'error');
        return;
    }
    
    let uploadedCount = 0;
    let errorCount = 0;

    for (let file of files) {
        if (!file.type.startsWith('image/') && !file.type.startsWith('video/') && !file.type.startsWith('audio/')) {
            console.warn(`[Gallery] Skipping unsupported file: ${file.name}`);
            continue;
        }

        try {
            const res = await apiRequest(`/characters/${encodeURIComponent(activeChar.id)}/media?name=${encodeURIComponent(file.name)}`, 'POST', file,
                { raw: true, headers: { 'Content-Type': file.type || 'application/octet-stream' } });

            if (res.ok) {
                await res.text().catch(() => { /* the upload landed; its body is only drained */ });
                uploadedCount++;
            } else {
                const errorText = await res.text();
                console.error(`[Gallery] Upload error for ${file.name}:`, res.status, errorText);
                errorCount++;
            }

        } catch (e) {
            console.error(`[Gallery] Upload failed for ${file.name}:`, e);
            errorCount++;
        }
    }
    
    if (uploadedCount > 0) {
        showToast(`Uploaded ${uploadedCount} file(s)`, 'success');
        fetchCharacterImages(activeChar);
    } else if (errorCount > 0) {
        showToast(`Upload failed for ${errorCount} file(s)`, 'error');
    }
}

// ========================================
// CHARACTER IMPORTER
// ========================================

const importModal = document.getElementById('importModal');
const importBtn = document.getElementById('importBtn');
const closeImportModal = document.getElementById('closeImportModal');
const startImportBtn = document.getElementById('startImportBtn');
const importUrlsInput = document.getElementById('importUrlsInput');
const importProgress = document.getElementById('importProgress');
const importProgressCount = document.getElementById('importProgressCount');
const importProgressFill = document.getElementById('importProgressFill');
const importLog = document.getElementById('importLog');
const importAutoDownloadGallery = document.getElementById('importAutoDownloadGallery');
const importAutoDownloadMedia = document.getElementById('importAutoDownloadMedia');

// Local import elements
const importSourceUrl = document.getElementById('importSourceUrl');
const importSourceLocal = document.getElementById('importSourceLocal');
const importDropZone = document.getElementById('importDropZone');
const importFileInput = document.getElementById('importFileInput');
const importDropPlaceholder = document.getElementById('importDropPlaceholder');
const importFileList = document.getElementById('importFileList');
const importFileCount = document.getElementById('importFileCount');
const importFileCountText = document.getElementById('importFileCountText');
const importClearFiles = document.getElementById('importClearFiles');
const importInfoHint = document.getElementById('importInfoHint');

let isImporting = false;
let importSourceMode = 'url'; // 'url' or 'local'
let importLocalFiles = []; // Array of File objects for local import

// Track active import for cancellation
let importAbortState = {
    abort: false,
    controller: null  // AbortController for in-flight network requests
};

function resetImportAbortState() {
    importAbortState.abort = false;
    importAbortState.controller?.abort();
    importAbortState.controller = null;
}

function cancelActiveImport() {
    importAbortState.abort = true;
    importAbortState.controller?.abort();
    setRunVerb(startImportBtn, 'stopping');
}

// Open/close import modal: the menu opens on links, the empty library on files
importBtn?.addEventListener('click', () => openImportModal('url'));

function openImportModal(source) {
    importModal.classList.add('visible');
    importUrlsInput.value = '';
    importProgress.classList.add('hidden');
    importLog.innerHTML = '';
    startImportBtn.disabled = false;
    startImportBtn.innerHTML = '<i class="fa-solid fa-download"></i> Import';
    startImportBtn.classList.remove('cl-btn-secondary', 'cl-btn-danger-hover');
    startImportBtn.classList.add('cl-btn-primary');
    delete startImportBtn.dataset.runState;
    syncImportAutoDownloadGallery();
    syncImportAutoDownloadMedia();
    const importStats = document.getElementById('importStats');
    if (importStats) importStats.classList.add('hidden');
    switchImportSource(source);
    clearImportLocalFiles();
    resetImportAbortState();
}

function syncImportAutoDownloadGallery() {
    if (!importAutoDownloadGallery) return;
    const includeProviderGallery = getSetting('includeProviderGallery');
    importAutoDownloadGallery.checked = includeProviderGallery !== false;
}

function syncImportAutoDownloadMedia() {
    if (!importAutoDownloadMedia) return;
    const mediaLocalizationEnabled = getSetting('mediaLocalizationEnabled');
    importAutoDownloadMedia.checked = mediaLocalizationEnabled !== false;
}

// every way out of the import dialog: a running import asks first, and closing cancels it
async function closeImportDialog() {
    if (isImporting) {
        const confirmClose = await showConfirm({
            title: 'Cancel import?',
            message: 'Import is still running. Cancel and close?',
            icon: 'fa-solid fa-triangle-exclamation',
            iconColor: 'var(--cl-warning-bright)',
            confirmLabel: 'Cancel Import',
            cancelLabel: 'Keep Importing',
            danger: true,
        });
        if (!confirmClose) return;
        cancelActiveImport();
    }
    importModal.classList.remove('visible');
}

closeImportModal?.addEventListener('click', closeImportDialog);
importModal?.addEventListener('click', (e) => {
    if (e.target === importModal) closeImportDialog();
});

// ========================================
// IMPORT SOURCE TOGGLE
// ========================================

/**
 * Switch import modal between URL and local PNG modes
 * @param {string} source - 'url' or 'local'
 */
function switchImportSource(source) {
    importSourceMode = source;
    
    document.querySelectorAll('.import-source-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.source === source);
    });
    
    if (importSourceUrl) importSourceUrl.classList.toggle('hidden', source !== 'url');
    if (importSourceLocal) importSourceLocal.classList.toggle('hidden', source !== 'local');

    if (importInfoHint) {
        if (source === 'url') {
            importInfoHint.innerHTML = '<i class="fa-solid fa-info-circle"></i><span>Supports character links from any source you have switched on.</span>';
        } else {
            importInfoHint.innerHTML = '<i class="fa-solid fa-info-circle"></i><span>Import character card files (PNG or CHARX) directly. Card metadata will be preserved, and a CHARX\'s images join the gallery.</span>';
        }
    }
}

document.querySelectorAll('.import-source-btn').forEach(btn => {
    btn.addEventListener('click', () => {
        if (isImporting) return;
        switchImportSource(btn.dataset.source);
    });
});

// ========================================
// LOCAL FILE HANDLING
// ========================================

/**
 * A byte count in the largest unit under 1024 of it (B, KB, MB, GB); the one formatter (CoreAPI.formatBytes).
 * @param {number} bytes
 * @returns {string} '-' when the count is not a number
 */
function formatBytes(bytes) {
    if (!Number.isFinite(bytes)) return '-';
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1048576) return `${(bytes / 1024).toFixed(1)} KB`;
    if (bytes < 1073741824) return `${(bytes / 1048576).toFixed(1)} MB`;
    return `${(bytes / 1073741824).toFixed(2)} GB`;
}

/**
 * Add files to the local import list (deduplicates by name+size)
 * @param {FileList|File[]} files
 */
function addImportLocalFiles(files) {
    // A CL bundle zip takes over the whole drop; the bundle importer has its own review flow.
    const bundle = [...files].find(f => f.name.toLowerCase().endsWith('.zip'));
    if (bundle) {
        if (files.length > 1) {
            showToast('Importing the bundle; other dropped files were ignored', 'info');
        }
        importModal?.classList.remove('visible');
        window.openBatchImportReview?.(bundle);
        return;
    }
    for (const file of files) {
        if (!/\.(png|charx)$/i.test(file.name)) {
            showToast(`Skipped "${file.name}": only PNG and CHARX card files are supported`, 'warning');
            continue;
        }
        const isDupe = importLocalFiles.some(f => f.name === file.name && f.size === file.size);
        if (!isDupe) {
            importLocalFiles.push(file);
        }
    }
    renderImportFileList();
}

/**
 * Remove a file from the local import list by index
 * @param {number} index
 */
function removeImportLocalFile(index) {
    importLocalFiles.splice(index, 1);
    renderImportFileList();
}

/**
 * Clear all local import files
 */
function clearImportLocalFiles() {
    importLocalFiles = [];
    if (importFileInput) importFileInput.value = '';
    renderImportFileList();
}

/**
 * Render the file list UI for local imports
 */
function renderImportFileList() {
    if (!importFileList || !importDropPlaceholder || !importFileCount) return;
    
    if (importLocalFiles.length === 0) {
        importFileList.classList.add('hidden');
        importFileList.innerHTML = '';
        importDropPlaceholder.classList.remove('hidden');
        importFileCount.classList.add('hidden');
        return;
    }
    
    importDropPlaceholder.classList.add('hidden');
    importFileList.classList.remove('hidden');
    importFileCount.classList.remove('hidden');
    
    importFileList.innerHTML = importLocalFiles.map((file, idx) => `
        <div class="import-file-item" data-index="${idx}">
            <i class="fa-solid fa-file-image"></i>
            <span class="import-file-name" title="${escapeHtml(file.name)}">${escapeHtml(file.name)}</span>
            <span class="import-file-size">${formatBytes(file.size)}</span>
            <button class="import-file-remove" data-index="${idx}" title="Remove file">
                <i class="fa-solid fa-xmark"></i>
            </button>
        </div>
    `).join('');
    
    if (importFileCountText) {
        importFileCountText.textContent = `${importLocalFiles.length} file${importLocalFiles.length !== 1 ? 's' : ''} selected`;
    }
    
    importFileList.querySelectorAll('.import-file-remove').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            removeImportLocalFile(parseInt(btn.dataset.index));
        });
    });
}

importFileInput?.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
        addImportLocalFiles(e.target.files);
    }
});

importDropZone?.addEventListener('click', (e) => {
    if (e.target.closest('.import-browse-btn')) {
        importFileInput?.click();
    }
});

// Drag & drop handlers
importDropZone?.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.stopPropagation();
    importDropZone.classList.add('drag-over');
});

importDropZone?.addEventListener('dragleave', (e) => {
    e.preventDefault();
    e.stopPropagation();
    // Only remove highlight if leaving the drop zone entirely
    if (!importDropZone.contains(e.relatedTarget)) {
        importDropZone.classList.remove('drag-over');
    }
});

importDropZone?.addEventListener('drop', (e) => {
    e.preventDefault();
    e.stopPropagation();
    importDropZone.classList.remove('drag-over');
    if (e.dataTransfer.files.length > 0) {
        addImportLocalFiles(e.dataTransfer.files);
    }
});

importClearFiles?.addEventListener('click', () => {
    clearImportLocalFiles();
});

// ========================================
// LOCAL CARD FILE IMPORT
// ========================================

// Direct-URL import via the hardened media fetch (the proxy when CORS blocks); a PNG is read here,
// anything else staged.
async function fetchDirectImportFile(url, signal) {
    const dl = await downloadMediaToMemory(url, 30000, signal);
    if (!dl.success) {
        throw new Error(`download failed: ${dl.error}`);
    }
    const png = /^image\/png$/i.test(dl.detectedType || dl.contentType || '');
    let name = '';
    try { name = decodeURIComponent(new URL(url).pathname.split('/').pop() || ''); } catch { /* an unreadable path names it "character" */ }
    if (!name) name = 'character';
    if (png && !/\.png$/i.test(name)) name = `${name}.png`;
    return new File([dl.arrayBuffer], name, png ? { type: 'image/png' } : {});
}

const PNG_SIGNATURE = [137, 80, 78, 71, 13, 10, 26, 10];
function isPngBytes(buffer) {
    const head = new Uint8Array(buffer, 0, Math.min(8, buffer.byteLength));
    return head.length === 8 && PNG_SIGNATURE.every((b, i) => head[i] === b);
}
// by its bytes, never its name: a card PNG saved as .charx is still a PNG
async function isPngFile(file) {
    return isPngBytes(await file.slice(0, 8).arrayBuffer());
}

// file -> the stage its duplicate check made, so the import that follows commits that stage
// rather than sending the file a second time
const _stagedCardFiles = new WeakMap();

/**
 * Stages a card file the page doesnt read (a charx): the server reads it and answers its card;
 * staged once per file.
 * @returns {Promise<{stageId: string, format: string, card: Object, picture: boolean, media: {name: string, size: number}[]}>}
 */
async function stageCardFile(file) {
    const known = _stagedCardFiles.get(file);
    if (known) return known;
    const resp = await apiRequest(`/characters/import/stage?name=${encodeURIComponent(file.name || 'card')}`, 'POST', file,
        { raw: true, headers: { 'Content-Type': 'application/octet-stream' } });
    const body = await readAnswer(resp);
    if (!body) throw new Error(`server returned ${resp.status} with no answer`);
    _stagedCardFiles.set(file, body);
    return body;
}

/** Drop a file's stage (its duplicate was skipped); an unclaimed stage also goes by itself after an hour. */
async function dropStagedCardFile(file) {
    const staged = _stagedCardFiles.get(file);
    if (!staged) return;
    _stagedCardFiles.delete(file);
    try { await apiRequest(`/characters/import/stage/${encodeURIComponent(staged.stageId)}`, 'DELETE'); } catch { /* the hour takes it */ }
}

/** The card a local file holds, for the import modal's duplicate check: a PNG read here, anything else staged. Null for none. */
async function readLocalCardFile(file) {
    if (await isPngFile(file)) return extractCharacterDataFromPng(await file.arrayBuffer());
    return (await stageCardFile(file)).card || null;
}

/**
 * One local card file in, behind character.import: read or staged, enriched by its provider, posted.
 * Asks nothing; onExisting picks copy or replace.
 * @param {File|Blob} file - The card file (a PNG or a charx)
 * @param {{onExisting?: 'copy'|{replace: string}|null}} [opts]
 * @returns {Promise<Object>} Import result: { success, id, characterName, alreadyPresent, skippedReason, mediaCount, error }
 */
async function importLocalCharacterNow(file, { onExisting = null, staged: given = null } = {}) {
    const fileName = given ? String(given.name || '') : file.name;
    try {
        const png = given ? false : await isPngFile(file);
        const arrayBuffer = png ? await file.arrayBuffer() : null;
        const staged = given || (png ? null : await stageCardFile(file));
        if (staged && !given) _stagedCardFiles.delete(file);

        let cardData = png ? extractCharacterDataFromPng(arrayBuffer) : staged.card;
        if (!cardData) {
            throw new Error('No character card data found in PNG. Is this a V2 character card?');
        }
        
        // Normalize V1 cards (flat object with name/description at top level) to V2 wrapper
        if (!cardData.data && cardData.name) {
            cardData = { spec: 'chara_card_v2', spec_version: '2.0', data: cardData };
        }
        if (!cardData.data) cardData.data = {};
        if (!cardData.data.extensions) cardData.data.extensions = {};
        
        const characterName = cardData.data.name || String(fileName || '').replace(/\.(png|charx)$/i, '');

        let needsReembed = false;

        // Each registered provider checks its own extension metadata first (instant), then may search its
        // API to detect and enrich an unlinked card.
        let providerResult = null;
        const registry = window.ProviderRegistry;
        if (registry) {
            for (const provider of registry.getAllProviders()) {
                try {
                    const enrichment = await provider.enrichLocalImport(cardData, fileName);
                    if (enrichment) {
                        if (enrichment.cardData && enrichment.cardData !== cardData) {
                            cardData = enrichment.cardData;
                        }
                        providerResult = enrichment.providerInfo;
                        needsReembed = true;
                        debugLog(`[Local Import] Enriched by ${provider.name}:`, providerResult);
                        break;
                    }
                } catch (e) {
                    debugLog(`[Local Import] ${provider.name} enrichment failed:`, e.message);
                }
            }
        }
        
        const { embeddedUrls: importEmbeddedUrls, lorebookUrls: importLorebookUrls } = findCharacterMediaUrls(cardData, { split: true });
        
        await window.ensureExtractorsLoaded?.();
        const importGalleryPageUrls = typeof window.findCharacterGalleryUrls === 'function'
            ? window.findCharacterGalleryUrls(cardData) : [];

        // the claiming provider names itself, so a card embedding several namespaces keeps
        // that one as its link (the server's source outranks divert order)
        const source = providerResult?.providerId || null;
        const replaceId = onExisting && typeof onExisting === 'object' ? String(onExisting.replace) : null;
        let result;
        if (png) {
            const pngToUpload = needsReembed ? embedCharacterDataInPng(arrayBuffer, cardData) : arrayBuffer;
            const qs = `${source ? `&source=${encodeURIComponent(source)}` : ''}${onExisting === 'copy' ? '&onExisting=copy' : ''}`;
            const endpoint = replaceId
                ? `/characters/${encodeURIComponent(replaceId)}/replace${source ? `?source=${encodeURIComponent(source)}` : ''}`
                : `/characters/import?name=${encodeURIComponent(fileName)}${qs}`;
            result = await readAnswer(await apiRequest(endpoint, 'POST', pngToUpload, { raw: true, headers: { 'Content-Type': 'image/png' } }));
        } else if (replaceId) {
            result = await readAnswer(await apiRequest(`/characters/${encodeURIComponent(replaceId)}/replace`, 'POST',
                { stage: staged.stageId, card: needsReembed ? cardData : undefined, source: source || undefined }));
        } else {
            // the staged card imports as the server read it unless a provider amended it
            result = await readAnswer(await apiRequest(`/characters/import/stage/${encodeURIComponent(staged.stageId)}`, 'POST',
                { card: needsReembed ? cardData : undefined, source: source || undefined, onExisting: onExisting === 'copy' ? 'copy' : undefined }));
        }
        debugLog('[Local Import] Answer:', result);
        // imports never overwrite: a duplicate comes back skipped (id = the match) and the caller decides;
        // copy runs it as a new character
        if (result?.skipped) {
            return { success: true, id: result.id, characterName, alreadyPresent: true, skippedReason: result.reason || null, mediaCount: result.media || 0 };
        }

        if (!result?.id) throw new Error('Import failed: server returned no character id');

        return {
            success: true,
            id: result.id,
            replaced: !!result.replaced,
            row: result.row || null,
            characterName: characterName,
            mediaCount: result.media || 0,
            embeddedMediaUrls: importEmbeddedUrls,
            lorebookMediaUrls: importLorebookUrls,
            galleryPageUrls: importGalleryPageUrls,
            linkedProvider: providerResult?.providerId || null,
            providerCharId: providerResult?.charId || null,
            fullPath: providerResult?.fullPath || null,
            hasGallery: providerResult?.hasGallery || false,
        };
        
    } catch (error) {
        console.error(`Failed to import local file ${fileName}:`, error);
        return { success: false, error: error.message };
    }
}

// A link to a provider's character page, as that provider and its identifier; null when no
// registered provider reads it
function resolveImportUrl(url) {
    const line = String(url || '').trim();
    const provider = window.ProviderRegistry?.getProviderForUrl(line, { accept: (p) => !!p.parseUrl?.(line) });
    const identifier = provider?.parseUrl(line);
    return provider && identifier ? { provider, identifier } : null;
}

async function importFromProviderNow(provider, identifier, data, options) {
    const p = typeof provider === 'string' ? window.ProviderRegistry?.getProvider(provider) : provider;
    if (!p?.supportsImport) throw new Error(`character.import: no provider imports from ${typeof provider === 'string' ? provider : p?.id}`);
    return p.importCharacter(identifier, data ?? null, options);
}

/**
 * character.import: one card in from exactly one source (file, url, provider with id, or stage);
 * asks nothing, onExisting picks copy or replace.
 */
async function importCharacterFrom({ file, url, provider, id, stage, data = null, onExisting = null, options = {} } = {}) {
    if ([file, url, provider, stage].filter(v => v != null).length !== 1) throw new Error('character.import: name one source, file, url, provider or stage');
    if (stage != null && !(typeof stage.stageId === 'string' && stage.stageId && stage.card && typeof stage.card === 'object')) {
        throw new Error('character.import: a stage is { stageId, card } as the server answered it');
    }
    const replacing = onExisting != null && typeof onExisting === 'object' && typeof onExisting.replace === 'string' && onExisting.replace !== '';
    if (onExisting != null && onExisting !== 'copy' && !replacing) throw new Error("character.import: onExisting takes 'copy' or { replace: id }");
    let result;
    if (file != null) {
        result = await importLocalCharacterNow(file, { onExisting });
    } else if (stage != null) {
        result = await importLocalCharacterNow(null, { onExisting, staged: stage });
    } else if (provider != null) {
        result = await importFromProviderNow(provider, id, data, { ...options, onExisting });
    } else {
        const target = resolveImportUrl(url);
        if (target) result = await importFromProviderNow(target.provider, target.identifier, null, { ...options, onExisting });
        else if (/^https?:\/\//i.test(String(url))) result = await importLocalCharacterNow(await fetchDirectImportFile(String(url), options.signal), { onExisting });
        else throw new Error('character.import: the url is neither a provider\'s character page nor a web link');
    }
    if (result?.success && result.id && !result.alreadyPresent) {
        // a replace wrote a new picture under the same id; the feed never tells the tab that made it
        if (result.replaced) bumpAvatarCacheBust(result.id);
        await adoptCreatedCharacter(result.id, result.row);
        if (result.missing?.length) sayImportMissing(result);
    }
    return result;
}

// a partial import stays an import: what it came in without is said once, a batch folded into one toast
function sayImportMissing(result) {
    const parts = result.missing;
    const what = parts.length > 1 ? `${parts.slice(0, -1).join(', ')} and ${parts.at(-1)}` : parts[0];
    showToast(`${result.replaced ? 'Replaced with' : 'Imported'} "${result.characterName}" without ${what}`, 'warning', 8000,
        { group: 'import-missing', item: { name: result.characterName, what }, many: summarizeImportMissing });
}

function summarizeImportMissing(items) {
    const shown = items.slice(0, 2).map(i => `"${i.name}" without ${i.what}`).join('; ');
    const more = items.length > 2 ? ` (and ${items.length - 2} more)` : '';
    return `${items.length} characters came in incomplete: ${shown}${more}`;
}

// The import modal's run of one item: an identical file is said, a different-content match asks
// before coming in as a copy.
async function runImportFromModal(args) {
    try {
        let result = await runShellCommand('character.import', args, importCharacterFrom);
        if (args.file && result?.alreadyPresent && result.skippedReason === 'identical') {
            showToast(`"${result.characterName}" is already in your library (identical)`, 'info');
        } else if (args.file && result?.alreadyPresent && result.skippedReason && await askImportAsCopy(result)) {
            result = await runShellCommand('character.import', { ...args, onExisting: 'copy' }, importCharacterFrom);
        }
        return result || { success: false, error: 'the import was held back' };
    } catch (e) {
        return { success: false, error: e.message };
    }
}

async function askImportAsCopy(result) {
    const existing = await ensureCharacterById(result.id).catch(() => null);
    return showConfirm({
        title: 'Already in your library?',
        message: `"${result.characterName}" matches "${existing ? getCharField(existing, 'name') : 'an existing character'}" but its content differs. Nothing was changed. Import this version as a separate copy?`,
        icon: 'fa-solid fa-clone',
        confirmLabel: 'Import as Copy',
        cancelLabel: 'Skip',
    });
}

function crc32(data) {
    let crc = -1;
    for (let i = 0; i < data.length; i++) {
        crc = (crc >>> 8) ^ crc32Table[(crc ^ data[i]) & 0xff];
    }
    return (crc ^ -1) >>> 0;
}

// Pre-computed CRC32 table
const crc32Table = new Uint32Array(256);
for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) {
        c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    }
    crc32Table[i] = c;
}

// Anchor-click download for a Blob, named by the server's safeFileName rule. Revoke is deferred:
// an immediate revoke can abort a still-starting download in some engines.
function downloadBlobAsFile(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = String(filename ?? '').replace(/[<>:"/\\|?*\x00-\x1f]/g, '_').trim();
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * Convert any image (WebP, JPEG, etc.) to PNG using canvas
 * @param {ArrayBuffer} imageBuffer - The source image data
 * @returns {Promise<ArrayBuffer>} PNG image data
 */
async function convertImageToPng(imageBuffer) {
    return new Promise((resolve, reject) => {
        let blob = new Blob([imageBuffer]);
        const url = URL.createObjectURL(blob);
        const img = new Image();
        
        img.onload = () => {
            URL.revokeObjectURL(url);
            blob = null; // release the source blob once decoded
            
            const canvas = document.createElement('canvas');
            canvas.width = img.naturalWidth;
            canvas.height = img.naturalHeight;
            
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0);
            
            // Release decoded image bitmap
            img.src = '';
            
            canvas.toBlob((pngBlob) => {
                // Release canvas backing store (can be 10-20MB for high-res images)
                canvas.width = 0;
                canvas.height = 0;
                
                if (pngBlob) {
                    pngBlob.arrayBuffer().then(resolve).catch(reject);
                } else {
                    reject(new Error('Failed to convert image to PNG'));
                }
            }, 'image/png');
        };
        
        img.onerror = () => {
            URL.revokeObjectURL(url);
            reject(new Error('Failed to load image for conversion'));
        };
        
        img.src = url;
    });
}

function createTextChunk(keyword, text) {
    const keywordBytes = new TextEncoder().encode(keyword);
    const textBytes = new TextEncoder().encode(text);
    const dataLength = keywordBytes.length + 1 + textBytes.length; // +1 for null separator
    
    // Chunk: length (4) + type (4) + data + crc (4)
    const chunk = new Uint8Array(12 + dataLength);
    const view = new DataView(chunk.buffer);
    
    // Length (big-endian)
    view.setUint32(0, dataLength, false);
    
    // Type: 'tEXt'
    chunk[4] = 0x74; // t
    chunk[5] = 0x45; // E
    chunk[6] = 0x58; // X
    chunk[7] = 0x74; // t
    
    // Keyword
    chunk.set(keywordBytes, 8);
    
    // Null separator
    chunk[8 + keywordBytes.length] = 0;
    
    // Text
    chunk.set(textBytes, 9 + keywordBytes.length);
    
    // CRC (type + data)
    const crcData = chunk.slice(4, 8 + dataLength);
    const crcValue = crc32(crcData);
    view.setUint32(8 + dataLength, crcValue, false);
    
    return chunk;
}

/**
 * Extract character card data from a PNG file
 * Reads the 'chara' tEXt/iTXt chunk and decodes the base64 JSON
 * @param {ArrayBuffer} pngBuffer - The PNG file data
 * @returns {Object|null} The parsed character card object, or null if not found/invalid
 */
function extractCharacterDataFromPng(pngBuffer) {
    try {
        const bytes = new Uint8Array(pngBuffer);
        
        if (!isPngBytes(pngBuffer)) {
            debugLog('[PNG Extract] Invalid PNG signature');
            return null;
        }

        // Read the V2 'chara' chunk, the canonical complete one; a V3 'ccv3' is provider-dependent and may
        // be incomplete.
        let pos = 8;
        
        while (pos < bytes.length) {
            const view = new DataView(bytes.buffer, pos);
            const length = view.getUint32(0, false);
            const typeBytes = bytes.slice(pos + 4, pos + 8);
            const type = String.fromCharCode(...typeBytes);
            const chunkEnd = pos + 12 + length;
            
            if (type === 'tEXt' || type === 'iTXt') {
                // Check keyword (null-terminated string at start of data)
                const dataStart = pos + 8;
                let keyword = '';
                let keywordEnd = dataStart;
                
                for (let i = dataStart; i < dataStart + Math.min(20, length); i++) {
                    if (bytes[i] === 0) {
                        keywordEnd = i;
                        break;
                    }
                    keyword += String.fromCharCode(bytes[i]);
                }
                
                if (keyword.toLowerCase() === 'chara') {
                    debugLog('[PNG Extract] Found chara chunk, type:', type);
                    
                    // Extract the base64 data after the null terminator
                    let textStart = keywordEnd + 1;
                    
                    // For iTXt, skip compression flag, compression method, language tag, and translated keyword
                    if (type === 'iTXt') {
                        textStart += 2;
                        while (textStart < dataStart + length && bytes[textStart] !== 0) textStart++;
                        textStart++;
                        while (textStart < dataStart + length && bytes[textStart] !== 0) textStart++;
                        textStart++;
                    }
                    
                    const textEnd = dataStart + length;
                    // Build base64 string in chunks (avoid spread operator stack overflow on large data)
                    let base64Data = '';
                    const slice = bytes.subarray(textStart, textEnd);
                    const chunkSz = 32768;
                    for (let ci = 0; ci < slice.length; ci += chunkSz) {
                        base64Data += String.fromCharCode.apply(null, slice.subarray(ci, Math.min(ci + chunkSz, slice.length)));
                    }
                    
                    try {
                        const jsonString = decodeURIComponent(escape(atob(base64Data)));
                        const cardData = JSON.parse(jsonString);
                        debugLog('[PNG Extract] Successfully extracted card data:', {
                            spec: cardData.spec,
                            spec_version: cardData.spec_version,
                            name: cardData.data?.name
                        });
                        return cardData;
                    } catch (decodeError) {
                        debugLog('[PNG Extract] Failed to decode chara data:', decodeError.message);
                        return null;
                    }
                }
            }
            
            pos = chunkEnd;
        }
        
        debugLog('[PNG Extract] No chara chunk found in PNG');
        return null;
        
    } catch (error) {
        debugLog('[PNG Extract] Error extracting character data:', error.message);
        return null;
    }
}

// Embed character data into PNG (removes existing chara and ccv3 chunks first)
function embedCharacterDataInPng(pngBuffer, characterJson) {
    const bytes = new Uint8Array(pngBuffer);
    
    if (!isPngBytes(pngBuffer)) throw new Error('Invalid PNG file');

    // First pass: find chunk boundaries and identify which to keep/skip.
    // Uses subarray views (zero-copy) instead of slice copies.
    const chunkRanges = []; // [{start, end, type, skip}]
    let pos = 8;
    
    while (pos < bytes.length) {
        const view = new DataView(bytes.buffer, bytes.byteOffset + pos);
        const length = view.getUint32(0, false);
        const type = String.fromCharCode(bytes[pos+4], bytes[pos+5], bytes[pos+6], bytes[pos+7]);
        const chunkEnd = pos + 12 + length;
        
        // Skip any character card tEXt chunks (chara = V2, ccv3 = V3)
        let skipChunk = false;
        if (type === 'tEXt' || type === 'iTXt' || type === 'zTXt') {
            const dataStart = pos + 8;
            let keyword = '';
            for (let j = dataStart; j < dataStart + Math.min(20, length); j++) {
                if (bytes[j] === 0) break;
                keyword += String.fromCharCode(bytes[j]);
            }
            const kwLower = keyword.toLowerCase();
            if (kwLower === 'chara' || kwLower === 'ccv3') {
                debugLog(`[PNG] Removing existing '${type}' chunk with '${keyword}' keyword`);
                skipChunk = true;
            }
        }
        
        chunkRanges.push({ start: pos, end: chunkEnd, type, skip: skipChunk });
        pos = chunkEnd;
    }
    
    const iendIndex = chunkRanges.findIndex(c => c.type === 'IEND');
    if (iendIndex === -1) {
        throw new Error('Invalid PNG: IEND chunk not found');
    }
    
    const jsonString = JSON.stringify(characterJson);
    const base64Data = btoa(unescape(encodeURIComponent(jsonString)));
    const textChunk = createTextChunk('chara', base64Data);
    
    debugLog(`[PNG] Adding new chara chunk: JSON=${jsonString.length} chars, base64=${base64Data.length} chars`);
    
    // Calculate total size (no intermediate copies)
    let totalSize = 8 + textChunk.length; // PNG signature + new chara chunk
    for (const range of chunkRanges) {
        if (!range.skip) totalSize += (range.end - range.start);
    }
    
    // Build the new PNG: write directly from source using subarray views
    const result = new Uint8Array(totalSize);
    result.set(bytes.subarray(0, 8), 0); // PNG signature (view, no copy until set)
    
    let offset = 8;
    for (let i = 0; i < chunkRanges.length; i++) {
        if (i === iendIndex) {
            result.set(textChunk, offset);
            offset += textChunk.length;
        }
        const range = chunkRanges[i];
        if (!range.skip) {
            result.set(bytes.subarray(range.start, range.end), offset);
            offset += (range.end - range.start);
        }
    }
    
    return result;
}

// Shared log entry icons
const LOG_ICONS = {
    success: 'fa-check-circle',
    error: 'fa-times-circle',
    pending: 'fa-spinner fa-spin',
    info: 'fa-info-circle',
    divider: 'fa-minus'
};

/**
 * Add an entry to a log container
 * @param {string} status - 'success', 'error', 'pending', 'info' or 'divider'
 * @returns {HTMLElement} the entry, for updateLogEntry
 */
function addLogEntry(container, message, status = 'pending') {
    const entry = document.createElement('div');
    
    if (status === 'divider') {
        entry.className = 'import-log-divider';
        entry.innerHTML = '<hr>';
    } else {
        entry.className = `import-log-entry ${status}`;
        entry.innerHTML = `<i class="fa-solid ${LOG_ICONS[status] || LOG_ICONS.pending}"></i>${escapeHtml(message)}`;
    }
    container.appendChild(entry);
    container.scrollTop = container.scrollHeight;
    return entry;
}

/** Re-word a log entry and set its status (addLogEntry's statuses); the entry knows its log. */
function updateLogEntry(entry, message, status) {
    entry.className = `import-log-entry ${status}`;
    entry.innerHTML = `<i class="fa-solid ${LOG_ICONS[status]}"></i>${escapeHtml(message)}`;
}

function addImportLogEntry(message, status = 'pending') {
    return addLogEntry(importLog, message, status);
}

// Start import process
startImportBtn?.addEventListener('click', async () => {
    // a run that has ended leaves the verb reading Close
    if (startImportBtn.dataset.runState === 'done') {
        importModal.classList.remove('visible');
        return;
    }
    
    // If currently importing, this click means "Cancel"
    if (isImporting) {
        cancelActiveImport();
        return;
    }
    
    // Validate input
    let importItems = []; // Array of { displayName, identifier?, provider?, file? }
    
    if (importSourceMode === 'url') {
        const text = importUrlsInput.value.trim();
        if (!text) {
            showToast('Please enter at least one URL', 'warning');
            return;
        }
        
        const lines = text.split('\n').map(l => l.trim()).filter(l => l);
        const directDownloadEnabled = getSetting('importDirectDownloads') === true;
        let skippedDirectCandidates = 0;

        for (const line of lines) {
            const target = resolveImportUrl(line);
            if (target) {
                const slug = String(target.identifier).split('/').pop() || target.identifier;
                importItems.push({ displayName: slug, identifier: target.identifier, provider: target.provider, url: line });
            } else if (directDownloadEnabled && /^https?:\/\//i.test(line)) {
                // an unrecognized URL is a direct card download
                let displayName = line;
                try { displayName = decodeURIComponent(new URL(line).pathname.split('/').pop() || line); } catch { /* an unreadable path shows the URL itself */ }
                importItems.push({ displayName: displayName.replace(/\.png$/i, ''), directUrl: line });
            } else if (/^https?:\/\//i.test(line)) {
                skippedDirectCandidates++;
            }
        }

        if (importItems.length === 0) {
            showToast(skippedDirectCandidates > 0
                ? `No recognized provider for ${skippedDirectCandidates === 1 ? 'that link' : 'those links'}. To import plain file links (catbox, Discord, etc.), turn on Direct Downloads in Settings > General > Imports.`
                : 'No valid character URLs found. Make sure a provider supports the URL format.', 'error');
            return;
        }
        if (skippedDirectCandidates > 0) {
            showToast(`${skippedDirectCandidates} unrecognized link${skippedDirectCandidates === 1 ? '' : 's'} skipped. Turn on Direct Downloads in Settings > General > Imports to import plain file links.`, 'info');
        }
    } else {
        // Local file mode
        if (importLocalFiles.length === 0) {
            showToast('Please select at least one card file', 'warning');
            return;
        }

        importItems = importLocalFiles.map(file => ({
            displayName: file.name.replace(/\.(png|charx)$/i, ''),
            file: file
        }));
    }
    
    const skipDuplicates = document.getElementById('importSkipDuplicates')?.checked ?? true;
    const autoDownloadGallery = document.getElementById('importAutoDownloadGallery')?.checked ?? false;
    const autoDownloadMedia = document.getElementById('importAutoDownloadMedia')?.checked ?? false;
    
    // Start importing
    isImporting = true;
    resetImportAbortState();
    importAbortState.controller = new AbortController();
    
    setRunVerb(startImportBtn, 'running');
    if (importSourceMode === 'url') {
        importUrlsInput.disabled = true;
    }
    document.querySelectorAll('.import-source-btn').forEach(btn => btn.disabled = true);
    
    importProgress.classList.remove('hidden');
    importLog.innerHTML = '';
    importProgressFill.style.width = '0%';
    importProgressCount.textContent = `0/${importItems.length}`;
    
    let successCount = 0;
    let errorCount = 0;
    let skippedCount = 0;
    let mediaDownloadCount = 0;
    let wasCancelled = false;
    
    const importStats = document.getElementById('importStats');
    const importStatImported = document.getElementById('importStatImported');
    const importStatSkipped = document.getElementById('importStatSkipped');
    const importStatMedia = document.getElementById('importStatMedia');
    const importStatErrors = document.getElementById('importStatErrors');
    const importMediaProgress = document.getElementById('importMediaProgress');
    const importMediaProgressFill = document.getElementById('importMediaProgressFill');
    const importMediaProgressCount = document.getElementById('importMediaProgressCount');
    
    if (importStats) {
        importStats.classList.remove('hidden');
        importStatImported.textContent = '0';
        importStatSkipped.textContent = '0';
        importStatMedia.textContent = '0';
        importStatErrors.textContent = '0';
    }
    
    const updateStats = () => {
        if (importStatImported) importStatImported.textContent = successCount;
        if (importStatSkipped) importStatSkipped.textContent = skippedCount;
        if (importStatMedia) importStatMedia.textContent = mediaDownloadCount;
        if (importStatErrors) importStatErrors.textContent = errorCount;
    };
    
    const shouldStop = () => importAbortState.abort;
    
    const batchImportedIds = new Set();
    // the reader's word on a duplicate check that could not run, asked once a run
    const dupeRun = {};

    for (let i = 0; i < importItems.length; i++) {
        if (shouldStop()) {
            wasCancelled = true;
            break;
        }

        const item = importItems[i];
        const displayName = item.displayName;
        let unchecked = null;

        const logEntry = addImportLogEntry(`Checking ${displayName}`, 'pending');

        // Direct-URL items download first so the file-based checks below apply
        if (item.directUrl && !item.file) {
            try {
                updateLogEntry(logEntry, `Downloading ${displayName}`, 'pending');
                item.file = await fetchDirectImportFile(item.directUrl, importAbortState.controller.signal);
                updateLogEntry(logEntry, `Checking ${displayName}`, 'pending');
            } catch (e) {
                if (shouldStop()) { wasCancelled = true; break; }
                errorCount++;
                updateStats();
                updateLogEntry(logEntry, `${displayName}: ${e.message}`, 'error');
                const progress = ((i + 1) / importItems.length) * 100;
                importProgressFill.style.width = `${progress}%`;
                importProgressCount.textContent = `${i + 1}/${importItems.length}`;
                continue;
            }
        }

        // Pre-import duplicate check
        if (skipDuplicates) {
            try {
                if (shouldStop()) { wasCancelled = true; break; }

                if (item.provider) {
                    // URL mode: check if any existing character is linked to same provider+identifier
                    const importId = String(item.identifier).toLowerCase();
                    const batchKey = `${item.provider.id}:${importId}`;
                    
                    if (batchImportedIds.has(batchKey)) {
                        skippedCount++;
                        updateStats();
                        updateLogEntry(logEntry, `${displayName} skipped - duplicate URL in this batch`, 'info');
                        const progress = ((i + 1) / importItems.length) * 100;
                        importProgressFill.style.width = `${progress}%`;
                        importProgressCount.textContent = `${i + 1}/${importItems.length}`;
                        continue;
                    }
                    
                    // one probe of this item's key under its own provider, before anything is downloaded
                    const urlIndex = await batchDuplicateCheck(() => probeLinkOwners({ providers: [item.provider.id], keys: [String(item.identifier)] }), dupeRun);
                    unchecked = urlIndex.failed || null;
                    const existingMatch = urlIndex.answer?.providerIndex.get(batchKey) || null;
                    
                    if (existingMatch) {
                        const existingName = getCharField(existingMatch, 'name');
                        skippedCount++;
                        updateStats();
                        updateLogEntry(logEntry, `${displayName} skipped - already exists as "${existingName}" (same ${item.provider.name} character)`, 'info');
                        
                        const progress = ((i + 1) / importItems.length) * 100;
                        importProgressFill.style.width = `${progress}%`;
                        importProgressCount.textContent = `${i + 1}/${importItems.length}`;
                        continue;
                    }
                } else {
                    // Local mode: the file's card for the duplicate check (a staged file keeps its
                    // stage for the import that follows)
                    let cardData = await readLocalCardFile(item.file);

                    if (shouldStop()) { await dropStagedCardFile(item.file); wasCancelled = true; break; }
                    
                    // Normalize V1 (flat) cards to V2 wrapper
                    if (cardData && !cardData.data && cardData.name) {
                        cardData = { spec: 'chara_card_v2', data: cardData };
                    }
                    
                    if (cardData && cardData.data) {
                        const characterName = cardData.data.name || displayName;
                        const characterCreator = cardData.data.creator || '';
                        
                        let providerFullPath = null;
                        let providerId = '';
                        const allProviders = window.ProviderRegistry?.getAllProviders() || [];
                        for (const provider of allProviders) {
                            const linkInfo = provider.getLinkInfo({ data: cardData.data });
                            if (linkInfo?.fullPath) { providerFullPath = linkInfo.fullPath; providerId = provider.id; break; }
                        }
                        
                        const dupeProbe = {
                            name: characterName,
                            creator: characterCreator,
                            fullPath: providerFullPath,
                            providerId,
                            definition: {
                                description: cardData.data.description || '',
                                personality: cardData.data.personality || '',
                                first_mes: cardData.data.first_mes || '',
                                scenario: cardData.data.scenario || ''
                            }
                        };
                        const checked = await batchDuplicateCheck(() => checkCharacterForDuplicatesAsync(dupeProbe), dupeRun);
                        unchecked = checked.failed || null;
                        const duplicateMatches = checked.answer || [];

                        if (duplicateMatches.length > 0) {
                            const bestMatch = duplicateMatches[0];
                            const existingName = getCharField(bestMatch.char, 'name');
                            await dropStagedCardFile(item.file);
                            skippedCount++;
                            updateStats();
                            updateLogEntry(logEntry, `${displayName} skipped - already exists as "${existingName}" (${bestMatch.matchReason})`, 'info');

                            const progress = ((i + 1) / importItems.length) * 100;
                            importProgressFill.style.width = `${progress}%`;
                            importProgressCount.textContent = `${i + 1}/${importItems.length}`;
                            continue;
                        }
                    }
                }
            } catch (e) {
                // a card the probe could not be read from goes on to the import, which says why it fails
                debugLog('[Import] Error reading the card for the duplicate check:', e);
            }
        }

        if (unchecked && !dupeRun.uncheckedGo) {
            await dropStagedCardFile(item.file);
            skippedCount++;
            updateStats();
            updateLogEntry(logEntry, `${displayName} skipped - the duplicate check could not run (${unchecked})`, 'error');
            const progress = ((i + 1) / importItems.length) * 100;
            importProgressFill.style.width = `${progress}%`;
            importProgressCount.textContent = `${i + 1}/${importItems.length}`;
            continue;
        }

        if (shouldStop()) { wasCancelled = true; break; }

        updateLogEntry(logEntry, `Importing ${displayName}`, 'pending');
        
        const importArgs = item.provider
            ? { provider: item.provider.id, id: item.identifier, options: {
                // Slow imports (eg. janitorai hidden-definition recovery) narrate their phases
                onProgress: (msg) => updateLogEntry(logEntry, `${displayName}: ${msg}`, 'pending'),
            } }
            : { file: item.file };
        const result = await runImportFromModal(importArgs);
        
        // Check abort AFTER import completes (import itself is atomic: card was already uploaded)
        if (shouldStop()) {
            // If the import succeeded, still count it since the card is already in the library
            if (result.success) {
                successCount++;
                if (item.provider) batchImportedIds.add(`${item.provider.id}:${String(item.identifier).toLowerCase()}`);
                updateStats();
                updateLogEntry(logEntry, `${displayName} imported successfully`, 'success');
            }
            wasCancelled = true;
            break;
        }
        
        // Yield to browser for GC + UI updates between imports (critical for mobile)
        await new Promise(r => setTimeout(r, 50));
        
        if (result.success && result.alreadyPresent) {
            // the server answered with the EXISTING character: nothing was imported
            skippedCount++;
            if (item.provider) batchImportedIds.add(`${item.provider.id}:${String(item.identifier).toLowerCase()}`);
            updateStats();
            updateLogEntry(logEntry, `${displayName} skipped - already in your library`, 'info');
        } else if (result.success) {
            successCount++;
            if (item.provider) batchImportedIds.add(`${item.provider.id}:${String(item.identifier).toLowerCase()}`);
            updateStats();
            const fromCard = result.mediaCount ? ` (${result.mediaCount} gallery file${result.mediaCount === 1 ? '' : 's'} from the card)` : '';
            // a card file's own gallery files are media this import added, beside any it downloads
            mediaDownloadCount += result.mediaCount || 0;
            updateStats();
            updateLogEntry(logEntry, `${displayName} imported successfully${fromCard}${unchecked ? ' (not checked for duplicates)' : ''}`, 'success');
            
            let galleryProvider = null;
            let galleryLinkInfo = null;
            if (item.provider) {
                galleryProvider = item.provider;
                galleryLinkInfo = { id: result.providerCharId, fullPath: result.fullPath };
            } else if (result.linkedProvider) {
                galleryProvider = window.ProviderRegistry?.getProvider(result.linkedProvider) || null;
                galleryLinkInfo = { id: result.providerCharId, fullPath: result.fullPath };
            }

            const importPhases = [];
            if (autoDownloadMedia) {
                if (result.embeddedMediaUrls?.length > 0) importPhases.push('embedded');
                if (result.lorebookMediaUrls?.length > 0) importPhases.push('lorebook');
                if (getSetting('includeExternalGalleries') !== false && result.galleryPageUrls?.length > 0) importPhases.push('extGallery');
            }
            if (autoDownloadGallery && result.hasGallery && galleryProvider?.supportsGallery && galleryLinkInfo) {
                importPhases.push('providerGallery');
            }

            if (importPhases.length > 0 && getSetting('importMediaAction') === 'background') {
                // Background mode: hand the already-computed payload to the queue
                // and keep importing; the import itself already succeeded
                window.enqueueMediaDownloadJob?.({
                    charId: result.id,
                    name: result.characterName,
                    phases: importPhases,
                    embeddedUrls: result.embeddedMediaUrls || [],
                    lorebookUrls: result.lorebookMediaUrls || [],
                    galleryPageUrls: result.galleryPageUrls || [],
                    providerOverride: galleryProvider ? { provider: galleryProvider, linkInfo: galleryLinkInfo } : undefined,
                });
                addImportLogEntry('  ↳ Media downloads queued in background', 'info');
            } else if (importPhases.length > 0) {
                if (shouldStop()) { wasCancelled = true; break; }

                const totalMediaUrls = (result.embeddedMediaUrls?.length || 0) + (result.lorebookMediaUrls?.length || 0);
                const embeddedCount = result.embeddedMediaUrls?.length || 0;
                const phaseLogEntries = {};
                const phaseLabels = {
                    embedded: 'Embedded Media',
                    lorebook: 'Lorebook Media',
                    providerGallery: `${galleryProvider?.name || 'Provider'} Gallery`,
                    extGallery: 'External Galleries'
                };

                const pipelineResult = await downloadCharacterMedia(result.id, {
                    embeddedUrls: result.embeddedMediaUrls || [],
                    lorebookUrls: result.lorebookMediaUrls || [],
                    galleryPageUrls: result.galleryPageUrls || [],
                    providerOverride: galleryProvider ? { provider: galleryProvider, linkInfo: galleryLinkInfo } : undefined,
                    phases: importPhases,
                    signal: importAbortState.controller.signal,
                    shouldAbort: shouldStop,
                    onPhaseStart: (phase, ctx) => {
                        if (importMediaProgress) {
                            importMediaProgress.classList.remove('hidden');
                            importMediaProgressFill.style.width = '0%';
                            importMediaProgressCount.textContent = (phase === 'embedded' || phase === 'lorebook')
                                ? `0/${totalMediaUrls}` : `0/${ctx.count || '?'}`;
                        }
                        const label = phaseLabels[phase] || phase;
                        const msg = phase === 'extGallery'
                            ? `  ↳ ${label}: resolving ${ctx.count} URL(s)...`
                            : `  ↳ ${label}: downloading${ctx.count ? ` ${ctx.count} file(s)` : ''}...`;
                        phaseLogEntries[phase] = addImportLogEntry(msg, 'pending');
                    },
                    onPhaseEnd: (phase, pr) => {
                        const entry = phaseLogEntries[phase];
                        if (!entry) return;
                        const label = phaseLabels[phase] || phase;
                        if (pr.aborted) {
                            updateLogEntry(entry, `  ↳ ${label}: cancelled (${pr.success || 0} downloaded before stop)`, 'warning');
                        } else if (pr.success > 0) {
                            updateLogEntry(entry, `  ↳ ${label}: ${pr.success} downloaded, ${pr.skipped || 0} skipped, ${pr.errors || 0} failed`, 'success');
                        } else if (pr.skipped > 0) {
                            updateLogEntry(entry, `  ↳ ${label}: ${pr.skipped} already exist`, 'info');
                        } else {
                            const noMsg = phase === 'providerGallery' ? 'no images available'
                                : phase === 'extGallery' ? 'no images found' : 'no files downloaded';
                            updateLogEntry(entry, `  ↳ ${label}: ${noMsg}`, 'info');
                        }
                    },
                    onProgress: (phase, current, total) => {
                        if (!importMediaProgressFill) return;
                        if (phase === 'embedded' || phase === 'lorebook') {
                            const done = (phase === 'lorebook' ? embeddedCount : 0) + current;
                            importMediaProgressFill.style.width = `${(done / totalMediaUrls) * 100}%`;
                            importMediaProgressCount.textContent = `${done}/${totalMediaUrls}`;
                        } else {
                            importMediaProgressFill.style.width = `${(current / total) * 100}%`;
                            importMediaProgressCount.textContent = `${current}/${total}`;
                        }
                    }
                });

                mediaDownloadCount += pipelineResult.totals.success;
                updateStats();

                if (pipelineResult.aborted) {
                    wasCancelled = true;
                    break;
                }
            }
        } else {
            errorCount++;
            updateStats();
            updateLogEntry(logEntry, `${displayName}: ${result.error}`, 'error');
        }
        
        const progress = ((i + 1) / importItems.length) * 100;
        importProgressFill.style.width = `${progress}%`;
        importProgressCount.textContent = `${i + 1}/${importItems.length}`;
    }
    
    // Finalize
    
    if (wasCancelled) {
        addImportLogEntry('Import cancelled by user', 'warning');
    }
    
    isImporting = false;
    importAbortState.controller = null;
    importUrlsInput.disabled = false;
    document.querySelectorAll('.import-source-btn').forEach(btn => btn.disabled = false);
    setRunVerb(startImportBtn, 'done');
    
    if (importMediaProgress) {
        importMediaProgress.classList.add('hidden');
    }
    
    if (successCount > 0 || skippedCount > 0) {
        const parts = [];
        if (successCount > 0) parts.push(`Imported ${successCount}`);
        if (skippedCount > 0) parts.push(`${skippedCount} skipped`);
        if (mediaDownloadCount > 0) parts.push(`${mediaDownloadCount} media`);
        if (errorCount > 0) parts.push(`${errorCount} failed`);
        if (wasCancelled) parts.push('cancelled');
        showToast(parts.join(', '), successCount > 0 ? 'success' : 'info');
    } else if (!wasCancelled) {
        showToast(`Import failed: ${errorCount} error${errorCount > 1 ? 's' : ''}`, 'error');
    } else {
        showToast('Import cancelled', 'info');
    }
});

// ==============================================
// Import Summary Modal
// ==============================================

let pendingMediaCharacters = [];
let pendingGalleryCharacters = [];
// Track active import-summary downloads for cancel/cleanup
let importSummaryDownloadState = {
    active: false,
    abort: false,
    controller: null
};

function resetImportSummaryDownloads() {
    importSummaryDownloadState.active = false;
    importSummaryDownloadState.abort = false;
    importSummaryDownloadState.controller = null;
    pendingMediaCharacters = [];
    pendingGalleryCharacters = [];
}

async function handleImportSummaryCloseRequest() {
    if (importSummaryDownloadState.active) {
        const confirmClose = await showConfirm({
            title: 'Stop downloads?',
            message: 'Downloads are still running. Stop and close?',
            icon: 'fa-solid fa-triangle-exclamation',
            iconColor: 'var(--cl-warning-bright)',
            confirmLabel: 'Stop Downloads',
            cancelLabel: 'Keep Downloading',
            danger: true,
        });
        if (!confirmClose) return;
        importSummaryDownloadState.abort = true;
        importSummaryDownloadState.controller?.abort();
        importSummaryDownloadState.active = false;
        pendingMediaCharacters = [];
        pendingGalleryCharacters = [];
    } else {
        resetImportSummaryDownloads();
    }
    hideModal('importSummaryModal');
}

// Merge the two pending lists into per-character download jobs, shared by Download All and the
// background-queue gate so the phases cant drift.
function buildImportSummaryJobs(mediaCharacters, galleryCharacters) {
    const includeGallery = getSetting('includeProviderGallery') !== false;
    const includeExt = getSetting('includeExternalGalleries') !== false;
    const charMap = new Map();
    for (const c of mediaCharacters) {
        if (c.id) charMap.set(c.id, { ...c });
    }
    for (const c of galleryCharacters) {
        const key = c.id;
        if (!key) continue;
        if (charMap.has(key)) {
            const existing = charMap.get(key);
            existing.provider = c.provider;
            existing.linkInfo = c.linkInfo;
        } else {
            charMap.set(key, { ...c });
        }
    }
    const jobs = [];
    for (const charInfo of charMap.values()) {
        const phases = [];
        if (charInfo.mediaUrls?.length > 0) phases.push('embedded');
        if (includeGallery && charInfo.provider?.supportsGallery && charInfo.linkInfo) phases.push('providerGallery');
        if (includeExt && charInfo.galleryPageUrls?.length > 0) phases.push('extGallery');
        if (phases.length === 0) continue;
        jobs.push({ charInfo, phases });
    }
    return jobs;
}

function queueImportMediaJobs({ galleryCharacters = [], mediaCharacters = [] }) {
    const jobs = buildImportSummaryJobs(mediaCharacters, galleryCharacters);
    let queued = 0;
    for (const job of jobs) {
        const ok = window.enqueueMediaDownloadJob?.({
            charId: job.charInfo.id,
            name: job.charInfo.name,
            phases: job.phases,
            embeddedUrls: job.charInfo.mediaUrls || [],
            lorebookUrls: [],
            galleryPageUrls: job.charInfo.galleryPageUrls || [],
            providerOverride: job.charInfo.provider ? { provider: job.charInfo.provider, linkInfo: job.charInfo.linkInfo } : undefined,
        });
        if (ok) queued++;
    }
    return queued;
}

/**
 * Show import summary modal with 2 rows: gallery and/or embedded media
 * @param {Object} options
 * @param {Array<{name: string, fullPath: string, url: string, chubId: number}>} options.galleryCharacters - Characters with ChubAI galleries
 * @param {Array<{name: string, avatar: string, mediaUrls: string[]}>} options.mediaCharacters - Characters with embedded media
 */
function showImportSummaryModal({ galleryCharacters = [], mediaCharacters = [] }) {
    // Background mode: queue everything silently instead of offering the
    // blocking download step; the modal never opens.
    if (getSetting('importMediaAction') === 'background') {
        const queued = queueImportMediaJobs({ galleryCharacters, mediaCharacters });
        if (queued > 0) {
            showToast(`Media downloads queued in background (${queued} character${queued === 1 ? '' : 's'})`, 'info', 3000, {
                group: 'import-activity', item: { kind: 'media', count: queued }, many: summarizeImportActivity,
            });
        }
        return;
    }
    const modal = document.getElementById('importSummaryModal');
    const galleryRow = document.getElementById('importSummaryGalleryRow');
    const galleryDesc = document.getElementById('importSummaryGalleryDesc');
    const mediaRow = document.getElementById('importSummaryMediaRow');
    const mediaDesc = document.getElementById('importSummaryMediaDesc');
    const mediaBadge = document.getElementById('importSummaryMediaBadge');
    const extGalleryRow = document.getElementById('importSummaryExtGalleryRow');
    const extGalleryDesc = document.getElementById('importSummaryExtGalleryDesc');
    const extGalleryBadge = document.getElementById('importSummaryExtGalleryBadge');
    const downloadAllBtn = document.getElementById('importSummaryDownloadAllBtn');
    const progressWrap = document.getElementById('importSummaryProgress');
    const progressFill = document.getElementById('importSummaryProgressFill');
    const progressLabel = document.getElementById('importSummaryProgressLabel');
    const progressCount = document.getElementById('importSummaryProgressCount');
    
    if (!modal) return;
    
    pendingMediaCharacters = mediaCharacters;
    pendingGalleryCharacters = galleryCharacters;
    
    galleryRow?.classList.add('hidden');
    mediaRow?.classList.add('hidden');
    extGalleryRow?.classList.add('hidden');
    
    const includeProviderGallery = getSetting('includeProviderGallery') !== false;

    if (galleryCharacters.length > 0 && galleryRow) {
        const galleryTitle = document.getElementById('importSummaryGalleryTitle');
        const providerName = galleryCharacters[0]?.provider?.name || 'Provider';
        if (galleryTitle) galleryTitle.textContent = `${providerName} Gallery`;

        if (galleryCharacters.length === 1) {
            if (galleryDesc) {
                galleryDesc.textContent = includeProviderGallery
                    ? `Additional artwork available from ${providerName}`
                    : `Additional artwork available from ${providerName} (disabled in settings)`;
            }
        } else {
            if (galleryDesc) {
                galleryDesc.textContent = includeProviderGallery
                    ? `${galleryCharacters.length} characters have gallery images`
                    : `${galleryCharacters.length} characters have gallery images (disabled in settings)`;
            }
        }
        galleryRow.classList.toggle('disabled', !includeProviderGallery);
        galleryRow.classList.remove('hidden');
    }
    
    if (mediaCharacters.length > 0) {
        const totalFiles = mediaCharacters.reduce((sum, c) => sum + (c.mediaUrls?.length || 0), 0);
        const allGalleryUrls = mediaCharacters.flatMap(c => c.galleryPageUrls || []);
        const totalExtGalleries = allGalleryUrls.length;

        // Embedded media row
        if (totalFiles > 0 && mediaRow) {
            if (mediaBadge) mediaBadge.textContent = totalFiles;
            if (mediaDesc) {
                mediaDesc.textContent = totalFiles === 1
                    ? 'Image referenced in the card text'
                    : `${totalFiles} images and files referenced in the card`;
            }
            mediaRow.classList.remove('hidden');
        }

        // External galleries row
        if (totalExtGalleries > 0 && extGalleryRow) {
            if (extGalleryBadge) extGalleryBadge.textContent = totalExtGalleries;
            if (extGalleryDesc) {
                const sources = typeof window.identifyGallerySources === 'function'
                    ? window.identifyGallerySources(allGalleryUrls) : [];
                if (sources.length > 0) {
                    extGalleryDesc.textContent = sources.join(', ');
                } else {
                    extGalleryDesc.textContent = totalExtGalleries === 1
                        ? 'Gallery page linked in the card'
                        : `${totalExtGalleries} gallery pages linked in the card`;
                }
            }
            extGalleryRow.classList.remove('hidden');
        }
    }
    
    if (downloadAllBtn) {
        downloadAllBtn.disabled = false;
        downloadAllBtn.innerHTML = '<i class="fa-solid fa-download"></i> Download All';
        downloadAllBtn.classList.remove('cl-btn-secondary', 'cl-btn-danger-hover');
        downloadAllBtn.classList.add('download-all-btn');
        delete downloadAllBtn.dataset.runState;
    }

    if (progressWrap && progressFill && progressLabel && progressCount) {
        progressWrap.classList.add('hidden');
        progressFill.style.width = '0%';
        progressLabel.textContent = 'Preparing downloads...';
        progressCount.textContent = '0/0';
    }

    modal.classList.add('visible');
}

// Import Summary Modal Event Listeners
on('closeImportSummaryModal', 'click', handleImportSummaryCloseRequest);

// Download All button - downloads both gallery and embedded media
on('importSummaryDownloadAllBtn', 'click', async () => {
    const btn = document.getElementById('importSummaryDownloadAllBtn');
    const progressWrap = document.getElementById('importSummaryProgress');
    const progressFill = document.getElementById('importSummaryProgressFill');
    const progressLabel = document.getElementById('importSummaryProgressLabel');
    const progressCount = document.getElementById('importSummaryProgressCount');
    
    if (btn.dataset.runState === 'done') {
        hideModal('importSummaryModal');
        pendingMediaCharacters = [];
        pendingGalleryCharacters = [];
        return;
    }
    
    const hasGallery = pendingGalleryCharacters.length > 0 && getSetting('includeProviderGallery') !== false;
    const hasMedia = pendingMediaCharacters.length > 0;
    
    if (!hasGallery && !hasMedia) {
        showToast('Nothing to download', 'info');
        return;
    }
    
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Downloading...';

    importSummaryDownloadState.active = true;
    importSummaryDownloadState.abort = false;
    importSummaryDownloadState.controller?.abort();
    importSummaryDownloadState.controller = new AbortController();
    
    let totalGallerySuccess = 0;
    let totalMediaSuccess = 0;
    let totalExtGallerySuccess = 0;
    let wasAborted = false;

    const setProgress = (label, current, total) => {
        if (!progressWrap || !progressFill || !progressLabel || !progressCount) return;
        progressWrap.classList.remove('hidden');
        progressLabel.textContent = label;
        if (typeof total === 'number' && total > 0) {
            const pct = Math.min(100, Math.round((current / total) * 100));
            progressFill.style.width = `${pct}%`;
            progressCount.textContent = `${current}/${total}`;
        } else {
            progressFill.style.width = '20%';
            progressCount.textContent = current ? String(current) : '0';
        }
    };

    // Unified per-character job list (shared with the background-queue gate)
    for (const job of buildImportSummaryJobs(pendingMediaCharacters, pendingGalleryCharacters)) {
        if (importSummaryDownloadState.abort) { wasAborted = true; break; }
        const { charInfo, phases } = job;

        const pResult = await downloadCharacterMedia(charInfo.id, {
            embeddedUrls: charInfo.mediaUrls || [],
            lorebookUrls: [],
            galleryPageUrls: charInfo.galleryPageUrls || [],
            providerOverride: charInfo.provider ? { provider: charInfo.provider, linkInfo: charInfo.linkInfo } : undefined,
            phases,
            signal: importSummaryDownloadState.controller.signal,
            shouldAbort: () => importSummaryDownloadState.abort,
            onProgress: (phase, current, total) => {
                const phaseLabel = { embedded: 'Embedded media', providerGallery: `${charInfo.provider?.name || 'Provider'} gallery`, extGallery: 'External galleries' }[phase] || phase;
                setProgress(`${phaseLabel}: ${charInfo.name || 'files'}`, current, total);
            }
        });

        totalMediaSuccess += (pResult.embedded?.success || 0);
        totalGallerySuccess += (pResult.providerGallery?.success || 0);
        totalExtGallerySuccess += (pResult.extGallery?.success || 0);
        if (pResult.aborted) { wasAborted = true; break; }
    }
    
    importSummaryDownloadState.active = false;
    importSummaryDownloadState.controller = null;
    if (wasAborted) {
        showToast('Downloads cancelled', 'info');
        if (progressWrap && progressFill && progressLabel && progressCount) {
            progressWrap.classList.add('hidden');
            progressFill.style.width = '0%';
            progressLabel.textContent = 'Preparing downloads...';
            progressCount.textContent = '0/0';
        }
        resetImportSummaryDownloads();
        return;
    }
    
    // the run is over: the green download verb becomes the neutral Close of the vocabulary
    btn.classList.remove('download-all-btn');
    setRunVerb(btn, 'done');
    
    const totalDownloaded = totalGallerySuccess + totalMediaSuccess + totalExtGallerySuccess;
    if (totalDownloaded > 0) {
        showToast(`Downloaded ${totalDownloaded} file${totalDownloaded > 1 ? 's' : ''}`, 'success');
        fetchCharacters(true);
    } else {
        showToast('All files already exist', 'info');
    }

    if (progressWrap && progressFill && progressLabel && progressCount) {
        progressWrap.classList.add('hidden');
        progressFill.style.width = '0%';
        progressLabel.textContent = 'Preparing downloads...';
        progressCount.textContent = '0/0';
    }

    resetImportSummaryDownloads();
});

// ==============================================
// Provider Link Feature
// ==============================================

// The server's divert list is the one authority on which extensions keys are link rows; transient
// failures never cache (null = retry).
let _linkNamespaces = null;
let _linkNamespacesInFlight = null;
function ensureLinkNamespaces() {
    if (_linkNamespaces || _linkNamespacesInFlight) return _linkNamespacesInFlight;
    _linkNamespacesInFlight = (async () => {
        try {
            const resp = await apiRequest('/extensions', 'GET');
            if (!resp.ok) return;
            const body = await resp.json();
            if (Array.isArray(body?.namespaces)) _linkNamespaces = body.namespaces;
        } catch (_) { /* transient: stays null, retried on the next render */ }
        finally { _linkNamespacesInFlight = null; }
    })();
    return _linkNamespacesInFlight;
}

// Link rows whose provider isnt registered now: the data is intact and diverts server-side, so
// they get the greyed indicator, never vanish.
function getOrphanedLinkNamespaces(char) {
    if (!_linkNamespaces) return [];
    const ext = char?.data?.extensions;
    if (!ext) return [];
    return _linkNamespaces.filter(ns => ext[ns] != null && !isNamespaceServed(ns));
}

// A namespace is served when a REGISTERED provider's manifest row claims it.
function isNamespaceServed(ns) {
    const registry = window.ProviderRegistry;
    if (!registry) return false;
    return Object.entries(PROVIDER_MANIFEST).some(([id, row]) => row.extNamespace === ns && !!registry.getProvider(id));
}

// An orphaned link's name: its declared row's (a bundled provider switched off), else the namespace
// (an extension removed)
function orphanLinkLabel(ns) {
    return Object.values(PROVIDER_MANIFEST).find(row => row.extNamespace === ns)?.name || ns;
}

/**
 * Update the provider link indicator in the modal (generic: any provider)
 * @param {Object} char - Character object
 */
function updateProviderLinkIndicator(char) {
    const indicator = document.getElementById('providerLinkIndicator');
    if (!indicator) return;
    indicator.style.pointerEvents = '';

    const result = window.ProviderRegistry?.getCharacterProvider(char) || null;
    const textSpan = indicator.querySelector('.provider-link-text');
    const locked = isUpdateLocked(char);
    delete indicator.dataset.orphanNs;
    indicator.classList.remove('orphaned');

    if (result) {
        const { provider, linkInfo } = result;
        indicator.classList.add('linked');
        indicator.title = `Linked to ${provider.name}: ${linkInfo.fullPath}`;
        indicator.dataset.providerId = provider.id;
        const lockIcon = locked ? ' <i class="fa-solid fa-lock provider-link-lock-icon" title="Updates locked"></i>' : '';
        if (textSpan) {
            textSpan.innerHTML = `<i class="provider-link-icon ${escapeHtml(provider.icon)}"></i><span class="provider-link-name">${escapeHtml(provider.name)}</span> <i class="fa-solid fa-check"></i>${lockIcon}`;
        }
    } else {
        indicator.classList.remove('linked');
        delete indicator.dataset.providerId;
        // one link per character (schema invariant), so at most one orphan exists
        const orphanNs = getOrphanedLinkNamespaces(char)[0];
        if (orphanNs) {
            indicator.classList.add('orphaned');
            indicator.dataset.orphanNs = orphanNs;
            const label = orphanLinkLabel(orphanNs);
            indicator.title = `Linked to unavailable provider ${label}. The link is intact and reconnects if the provider returns. Click to manage.`;
            if (textSpan) {
                textSpan.innerHTML = `<i class="provider-link-icon fa-solid fa-plug-circle-xmark"></i><span class="provider-link-name">${escapeHtml(label)}</span>`;
            }
        } else {
            indicator.title = 'Click to link to a provider';
            if (textSpan) {
                textSpan.innerHTML = '<span class="provider-link-name">Link</span>';
            }
            // the list loads lazily; when it lands, re-check so an orphan chip is not
            // missed on the very first modal open of the session
            if (!_linkNamespaces) ensureLinkNamespaces()?.then(() => {
                if (activeChar?.id === char?.id) updateProviderLinkIndicator(char);
            });
        }
    }

    updateNamePreferenceToggle(char);
}

const NAME_SOURCE_LABELS = { card: 'Card', listing: 'Listing', nickname: 'Nickname' };

// The source the toggle is effectively SHOWING: the resolved pref when this character
// can honour it, card otherwise (getCharacterName falls back the same way).
function effectiveNameSource(char, sources) {
    const prefs = getSetting('namePreferences') || {};
    const pref = prefs[char.id] || getSetting('displayNamePreference') || 'card';
    return sources.includes(pref) ? pref : 'card';
}

function updateNamePreferenceToggle(char) {
    const toggle = document.getElementById('namePreferenceToggle');
    if (!toggle) return;

    const label = toggle.querySelector('.name-pref-label');
    const sources = getNameSources(char);

    if (sources.length < 2 || !getSetting('showNameToggle')) {
        toggle.classList.add('hidden');
        return;
    }

    toggle.classList.remove('hidden');
    const prefs = getSetting('namePreferences') || {};
    const current = effectiveNameSource(char, sources);
    const next = sources[(sources.indexOf(current) + 1) % sources.length];
    const nameOf = (source) => source === 'card'
        ? (char.name || char.data?.name || '')
        : resolveNameSource(char, source);

    toggle.classList.toggle('active', current !== 'card');
    const hasOverride = !!(prefs[char.id]) && prefs[char.id] !== (getSetting('displayNamePreference') || 'card');
    toggle.classList.toggle('override', hasOverride);
    if (label) label.textContent = NAME_SOURCE_LABELS[current];
    toggle.title = `Showing ${NAME_SOURCE_LABELS[current].toLowerCase()} name "${nameOf(current)}". Click to use ${NAME_SOURCE_LABELS[next].toLowerCase()} name "${nameOf(next)}".`;
}

let _isTogglingNamePref = false;
async function toggleCharNamePreference(char) {
    if (!char?.id || _isTogglingNamePref) return;
    _isTogglingNamePref = true;

    try {
        const prefs = { ...(getSetting('namePreferences') || {}) };
        const globalPref = getSetting('displayNamePreference') || 'card';
        // Cycle through what THIS character actually has (card -> listing -> nickname,
        // absent sources skipped); the override clears when it lands on the global.
        const sources = getNameSources(char);
        const current = effectiveNameSource(char, sources);
        const newPref = sources[(sources.indexOf(current) + 1) % sources.length];

        if (newPref === globalPref) {
            delete prefs[char.id];
        } else {
            prefs[char.id] = newPref;
        }
        setSetting('namePreferences', prefs);

        updateNamePreferenceToggle(char);

        const headerName = document.querySelector('#charModal .modal-header h2');
        if (headerName) headerName.textContent = getCharacterName(char);

        performSearch();
    } finally {
        _isTogglingNamePref = false;
    }
}

// Tracks which provider the link modal is currently showing
let linkModalActiveProvider = null;

// Session-sticky source filter for the link-modal name search ('all' or a provider id)
let linkSearchSourceFilter = 'all';

/**
 * Open the provider link modal (works for any provider, not just ChubAI)
 * @param {Object} [char] - Character to link (sets activeChar if provided)
 */
function openProviderLinkModal(char) {
    if (char) activeChar = char;
    if (!activeChar) return;
    
    const modal = document.getElementById('providerLinkModal');
    const linkedState = document.getElementById('providerLinkLinkedState');
    const unlinkedState = document.getElementById('providerLinkUnlinkedState');
    const titleEl = document.getElementById('providerLinkModalTitle');
    const searchResults = document.getElementById('providerLinkSearchResults');
    
    const avatarEl = document.getElementById('providerLinkCharAvatar');
    const charNameEl = document.getElementById('providerLinkCharName');
    const charName = getCharacterName(activeChar) || 'Character';
    
    if (avatarEl) {
        avatarEl.src = getCharacterAvatarSmallThumbUrl(activeChar.id);
        avatarEl.onerror = () => { avatarEl.src = '/img/no-portrait.png'; };
    }
    if (charNameEl) {
        charNameEl.textContent = charName;
        charNameEl.title = charName;
    }
    
    const statusIcon = document.getElementById('providerLinkStatusIcon');
    
    const providerMatch = window.ProviderRegistry?.getCharacterProvider(activeChar) || null;
    const provider = providerMatch?.provider;
    const linkInfo = providerMatch?.linkInfo;
    linkModalActiveProvider = providerMatch;
    
    if (linkInfo && linkInfo.fullPath) {
        // Linked state
        linkedState.classList.remove('hidden');
        unlinkedState.classList.add('hidden');
        titleEl.textContent = `${provider.name} Link`;
        
        if (statusIcon) {
            statusIcon.className = 'provider-link-status-icon linked';
            statusIcon.innerHTML = '<i class="fa-solid fa-link"></i>';
        }
        
        const pathEl = document.getElementById('providerLinkCurrentPath');
        if (pathEl) {
            const charUrl = provider.getCharacterUrl?.(linkInfo) || '#';
            pathEl.href = charUrl;
            const pathSpan = pathEl.querySelector('span');
            if (pathSpan) pathSpan.textContent = linkInfo.fullPath;
        }
        
        const viewBtn = document.getElementById('providerLinkViewInGalleryBtn');
        const galleryBtn = document.getElementById('providerLinkGalleryBtn');
        const versionsBtn = document.getElementById('providerLinkVersionsBtn');
        const statsEl = document.getElementById('providerLinkStats');
        
        if (viewBtn) {
            viewBtn.classList.remove('hidden');
            viewBtn.innerHTML = `<i class="fa-solid fa-eye"></i> View on ${escapeHtml(provider.name)}`;
        }
        if (galleryBtn) galleryBtn.classList.toggle('hidden', !provider.supportsGallery);
        if (versionsBtn) versionsBtn.classList.remove('hidden');
        
        if (typeof provider.fetchLinkStats === 'function') {
            if (statsEl) {
                const fields = provider.linkStatFields || {};
                const slots = ['stat1', 'stat2', 'stat3'];
                statsEl.innerHTML = slots
                    .filter(k => fields[k])
                    .map(k => `<span><i class="${fields[k].icon}"></i> <span data-stat="${k}">-</span></span>`)
                    .join('');
                statsEl.classList.remove('hidden');
            }
            provider.fetchLinkStats(linkInfo).then(stats => {
                if (!stats || !statsEl) return;
                for (const key of ['stat1', 'stat2', 'stat3']) {
                    const el = statsEl.querySelector(`[data-stat="${key}"]`);
                    if (el) el.textContent = stats[key] != null ? formatNumber(stats[key]) : '-';
                }
            });
        } else {
            if (statsEl) statsEl.classList.add('hidden');
        }

        updateLockToggleUI(isUpdateLocked(activeChar));
        
    } else {
        // Unlinked state
        linkedState.classList.add('hidden');
        unlinkedState.classList.remove('hidden');
        titleEl.textContent = 'Link to Provider';
        linkModalActiveProvider = null;
        
        if (statusIcon) {
            statusIcon.className = 'provider-link-status-icon unlinked';
            statusIcon.innerHTML = '<i class="fa-solid fa-link-slash"></i>';
        }
        
        const nameInput = document.getElementById('providerLinkSearchName');
        const creatorInput = document.getElementById('providerLinkSearchCreator');
        const urlInput = document.getElementById('providerLinkUrlInput');

        const creator = activeChar.creator || activeChar.data?.creator || '';

        if (nameInput) nameInput.value = charName;
        if (creatorInput) creatorInput.value = creator;
        if (urlInput) urlInput.value = '';
        if (searchResults) searchResults.innerHTML = '';

        // Rebuild the source filter from currently-enabled searchable providers (enablement can change mid-session)
        const sourceSelect = document.getElementById('providerLinkSourceSelect');
        if (sourceSelect) {
            const disabledSet = new Set(getSetting('disabledProviders') || []);
            const searchable = (window.ProviderRegistry?.getAllProviders() || [])
                .filter(p => p.supportsBulkLink && !disabledSet.has(p.id));
            if (linkSearchSourceFilter !== 'all' && !searchable.some(p => p.id === linkSearchSourceFilter)) {
                linkSearchSourceFilter = 'all';
            }
            sourceSelect.innerHTML = '<option value="all">All Providers</option>'
                + searchable.map(p => `<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)}</option>`).join('');
            sourceSelect.value = linkSearchSourceFilter;
            sourceSelect._customSelect?.refresh?.();
            sourceSelect._customSelect?.relockWidth?.();
        }
    }

    modal.classList.add('visible');
}

/**
 * Search all providers for characters matching name/creator.
 * Results are tagged with providerId so linkToSearchResult knows which provider to save with.
 */
async function searchProvidersForLink(name, creator) {
    const resultsContainer = document.getElementById('providerLinkSearchResults');
    if (!resultsContainer) return;
    
    if (!name.trim()) {
        resultsContainer.innerHTML = '<div class="provider-link-search-empty">Enter a character name to search</div>';
        return;
    }
    
    resultsContainer.innerHTML = '<div class="provider-link-search-loading"><i class="fa-solid fa-spinner fa-spin"></i> Searching...</div>';
    
    try {
        const registry = window.ProviderRegistry;
        const disabledSet = new Set(getSetting('disabledProviders') || []);
        const providers = registry ? registry.getAllProviders().filter(p =>
            p.supportsBulkLink && !disabledSet.has(p.id)
            && (linkSearchSourceFilter === 'all' || p.id === linkSearchSourceFilter)) : [];

        if (providers.length === 0) {
            resultsContainer.innerHTML = '<div class="provider-link-search-empty"><i class="fa-solid fa-exclamation-triangle"></i> No providers available</div>';
            return;
        }
        
        const searchPromises = providers.map(async (provider) => {
            try {
                const results = await provider.searchForBulkLink(name.trim(), creator?.trim() || '');
                return results.map(r => ({ ...r, providerId: provider.id, providerName: provider.name }));
            } catch (e) {
                debugLog(`[LinkSearch] ${provider.name} search failed:`, e.message);
                return [];
            }
        });
        
        const allProviderResults = await Promise.all(searchPromises);
        let allResults = allProviderResults.flat();
        
        if (allResults.length === 0) {
            resultsContainer.innerHTML = '<div class="provider-link-search-empty"><i class="fa-solid fa-search"></i> No characters found</div>';
            return;
        }
        
        if (activeChar) {
            allResults = sortResultsByContentSimilarity(allResults, activeChar);
        }
        
        resultsContainer.innerHTML = allResults.map(result => {
            const provider = registry.getProvider(result.providerId);
            const avatarUrl = provider?.getResultAvatarUrl?.(result) || result.avatarUrl || '';
            const rating = result.rating ? result.rating.toFixed(1) : '';
            const starCount = result.starCount || 0;
            // Providers whose fullPath is a bare id have no author segment, so use the explicit creator field
            // when supplied.
            const creator = result.creator || (result.fullPath || '').split('/')[0];
            
            const statsHtml = [
                rating ? `<span><i class="fa-solid fa-star"></i> ${rating}</span>` : '',
                starCount ? `<span><i class="fa-solid fa-heart"></i> ${formatNumber(starCount)}</span>` : '',
            ].filter(Boolean).join('');
            
            return `
                <div class="provider-link-search-result" data-fullpath="${escapeHtml(result.fullPath)}" data-id="${result.id || ''}" data-provider-id="${escapeHtml(result.providerId)}">
                    <img class="provider-link-search-result-avatar" src="${avatarUrl}" alt="" onerror="this.src='${AVATAR_FALLBACK_SVG}'">
                    <div class="provider-link-search-result-info">
                        <div class="provider-link-search-result-name">${escapeHtml(result.name || result.fullPath.split('/').pop())}</div>
                        <div class="provider-link-search-result-creator">by ${escapeHtml(creator)} · ${escapeHtml(result.providerName)}</div>
                        <div class="provider-link-search-result-stats">${statsHtml}</div>
                    </div>
                    <button class="cl-btn cl-btn-primary cl-btn-sm provider-link-search-result-btn">
                        <i class="fa-solid fa-link"></i> Link
                    </button>
                </div>
            `;
        }).join('');
        
    } catch (error) {
        console.error('[LinkSearch] Search error:', error);
        resultsContainer.innerHTML = `<div class="provider-link-search-empty"><i class="fa-solid fa-exclamation-triangle"></i> Search failed: ${error.message}</div>`;
    }
}

/**
 * Link to a character from search results (multi-provider aware)
 */
async function linkToSearchResult(btn) {
    const resultEl = btn.closest('.provider-link-search-result');
    if (!resultEl || !activeChar) return;
    
    const fullPath = resultEl.dataset.fullpath;
    let resultId = resultEl.dataset.id;
    const providerId = resultEl.dataset.providerId;
    
    if (!providerId) {
        showToast('No provider specified for this result', 'error');
        return;
    }
    
    const registry = window.ProviderRegistry;
    const provider = registry?.getProvider(providerId);
    
    if (!provider) {
        showToast('Provider not found', 'error');
        return;
    }
    
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';
    
    try {
        // Fetch metadata to get numeric ID (needed for gallery, versioning)
        let pageName = null;
        if (!resultId && provider.fetchMetadata) {
            const metadata = await provider.fetchMetadata(fullPath);
            if (metadata) {
                if (metadata.id) resultId = metadata.id;
                pageName = provider.getListingName(metadata);
            }
        }
        
        await saveProviderLink(activeChar, provider, { id: resultId, fullPath, pageName });
        
        showToast(`Linked to ${fullPath} (${provider.name})`, 'success');
        
        updateProviderLinkIndicator(activeChar);
        hideModal('providerLinkModal');
        
    } catch (error) {
        console.error('[LinkSearch] Link error:', error);
        if (!error.told) showToast('Failed to save link', 'error');
        btn.disabled = false;
        btn.innerHTML = '<i class="fa-solid fa-link"></i> Link';
    }
}



/**
 * Link using a pasted URL: tries all providers' canHandleUrl/parseUrl
 */
async function linkToProviderUrl(url) {
    if (!activeChar) return;
    
    const btn = document.getElementById('providerLinkUrlBtn');
    
    const registry = window.ProviderRegistry;

    // Enabled-first tie-break + parse requirement both live in getProviderForUrl now.
    const matchedProvider = registry?.getProviderForUrl(url, { accept: (p) => !!p.parseUrl?.(url) }) || null;
    const parsedPath = matchedProvider?.parseUrl?.(url) || null;

    if (!matchedProvider || !parsedPath) {
        showToast('URL not recognized by any provider', 'error');
        return;
    }
    
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';
    }
    
    try {
        let resultId = null;
        let pageName = null;
        
        // Fetch metadata to get the project/numeric ID
        if (matchedProvider.fetchMetadata) {
            const metadata = await matchedProvider.fetchMetadata(parsedPath);
            if (metadata) {
                resultId = metadata.id;
                pageName = matchedProvider.getListingName(metadata);
            }
        }
        
        await saveProviderLink(activeChar, matchedProvider, { id: resultId, fullPath: parsedPath, pageName });
        
        showToast(`Linked to ${parsedPath} (${matchedProvider.name})`, 'success');
        
        updateProviderLinkIndicator(activeChar);
        hideModal('providerLinkModal');
        
    } catch (error) {
        console.error('[LinkSearch] URL link error:', error);
        if (!error.told) showToast(`Failed to link: ${error.message}`, 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<i class="fa-solid fa-link"></i>';
        }
    }
}

/**
 * Unlink character from the active provider
 */
async function unlinkFromProvider() {
    if (!activeChar) return;
    
    const btn = document.getElementById('providerLinkUnlinkBtn');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>';
    }
    
    try {
        const match = linkModalActiveProvider || window.ProviderRegistry?.getCharacterProvider(activeChar);
        const provider = match?.provider;
        if (!provider) throw new Error('No provider found for this character');

        // Non-blocking auto-snapshot before unlink (destructive, restore is the only undo).
        if (window.autoSnapshotBeforeChange) {
            await window.autoSnapshotBeforeChange(activeChar, 'unlink');
        }

        // Capture provider display metadata before the unlink drops it, so it survives as CL-owned fallback.
        const provTagline = activeChar.data?.extensions?.[provider.id]?.tagline;
        const provPageName = activeChar.data?.extensions?.[provider.id]?.pageName;

        // Sentinel-delete the provider namespace, moving display metadata into cl only where cl is empty;
        // the answer clears the held row.
        const existingCl = activeChar.data?.extensions?.cl;
        const updates = { [`extensions.${provider.id}`]: FIELD_DELETE_MARKER };
        if (provTagline && !(existingCl && 'tagline' in existingCl)) {
            updates['extensions.cl.tagline'] = provTagline;
        }
        if (provPageName && !(existingCl && 'pageName' in existingCl)) {
            updates['extensions.cl.pageName'] = provPageName;
        }

        const written = await writeCardFields(activeChar, updates);
        if (!written.ok) throw cardWriteError(written, 'Failed to save unlink');

        showToast(`Unlinked from ${provider.name}`, 'info');

        updateProviderLinkIndicator(activeChar);
        openProviderLinkModal();
        
    } catch (error) {
        console.error('[Link] Unlink error:', error);
        if (!error.told) showToast('Failed to unlink', 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<i class="fa-solid fa-unlink"></i> Unlink';
        }
    }
}

// Unlink a namespace whose provider isnt registered: unlinkFromProvider minus the provider
// (snapshot, sentinel-delete, display metadata into cl).
async function unlinkOrphanedNamespace(char, ns) {
    const keep = await showConfirm({
        title: 'Unlink from unavailable provider?',
        message: `This character is linked to "${orphanLinkLabel(ns)}", a provider that is not currently installed or enabled. The link is intact and reconnects by itself if the provider returns. Remove the link instead?`,
        icon: 'fa-solid fa-plug-circle-xmark',
        confirmLabel: 'Unlink',
        cancelLabel: 'Keep Link',
    });
    if (!keep) return;
    try {
        if (window.autoSnapshotBeforeChange) {
            await window.autoSnapshotBeforeChange(char, 'unlink');
        }
        const provTagline = char.data?.extensions?.[ns]?.tagline;
        const provPageName = char.data?.extensions?.[ns]?.pageName;
        const existingCl = char.data?.extensions?.cl;
        const updates = { [`extensions.${ns}`]: FIELD_DELETE_MARKER };
        if (provTagline && !(existingCl && 'tagline' in existingCl)) {
            updates['extensions.cl.tagline'] = provTagline;
        }
        if (provPageName && !(existingCl && 'pageName' in existingCl)) {
            updates['extensions.cl.pageName'] = provPageName;
        }
        const written = await writeCardFields(char, updates);
        if (!written.ok) throw cardWriteError(written, 'Failed to save unlink');
        showToast(`Unlinked from ${orphanLinkLabel(ns)}`, 'info');
        updateProviderLinkIndicator(char);
    } catch (error) {
        console.error('[Link] Orphan unlink error:', error);
        if (!error.told) showToast('Failed to unlink', 'error');
    }
}

/**
 * View character on linked provider: uses the provider's capability flags
 * to open an in-app preview or fall back to an external URL
 */
async function viewOnLinkedProvider() {
    if (!activeChar) {
        debugLog('[Link] viewOnLinkedProvider: no activeChar');
        return;
    }
    
    const match = linkModalActiveProvider || window.ProviderRegistry?.getCharacterProvider(activeChar);
    const provider = match?.provider;
    const linkInfo = match?.linkInfo;
    
    if (!provider || !linkInfo?.fullPath) {
        showToast('Not linked to any provider', 'error');
        return;
    }
    
    if (!provider.supportsInAppPreview) {
        const url = provider.getCharacterUrl?.(linkInfo);
        if (url) window.open(url, '_blank');
        else showToast(`No URL available for ${provider.name}`, 'error');
        return;
    }
    
    hideModal('providerLinkModal');
    hideModal('charModal');
    showToast(`Loading character from ${provider.name}...`, 'info');
    
    try {
        const previewObj = await provider.buildPreviewObject(activeChar, linkInfo);
        if (!previewObj) {
            showToast(`Character not found on ${provider.name}`, 'error');
            return;
        }

        // the provider's modals are in the page before the view switch opens one
        provider.browseView?.injectModals();

        // Set this provider as the target so switchView activates it, in the characters kind
        onlineKind = 'characters';
        lastOnlineProviderId = provider.id;
        switchView('online');

        // Allow DOM to settle after view switch, then open the preview
        requestAnimationFrame(() => {
            provider.openPreview(previewObj);
        });
    } catch (error) {
        console.error(`[${provider.id}] Failed to open preview:`, error);
        showToast(`Failed to load ${provider.name} character preview`, 'error');
    }
}

/**
 * Download gallery for linked character (uses provider abstraction)
 */
async function downloadLinkedGallery() {
    if (!activeChar) return;
    
    let galleryProvider = null;
    let linkInfo = null;
    const providers = window.ProviderRegistry?.getAllProviders() || [];
    for (const provider of providers) {
        if (!provider.supportsGallery) continue;
        const li = provider.getLinkInfo(activeChar);
        if (li?.id) {
            galleryProvider = provider;
            linkInfo = li;
            break;
        }
    }
    
    if (!galleryProvider || !linkInfo) {
        showToast('Not linked to any provider with gallery support', 'error');
        return;
    }
    
    const btn = document.getElementById('providerLinkGalleryBtn');
    if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Downloading...';
    }
    
    try {
        const result = await galleryProvider.downloadGallery(linkInfo, { charId: activeChar.id });
        
        if (result.success > 0) {
            showToast(`Downloaded ${result.success} gallery image${result.success > 1 ? 's' : ''}`, 'success');
            fetchCharacterImages(activeChar);
        } else if (result.skipped > 0) {
            showToast('All gallery images already exist', 'info');
        } else {
            showToast('No gallery images found', 'info');
        }
        
    } catch (error) {
        console.error('[ChubLink] Gallery download error:', error);
        showToast('Failed to download gallery', 'error');
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.innerHTML = '<i class="fa-solid fa-images"></i> Download Gallery';
        }
    }
}

// Provider Link Indicator: opens the appropriate provider's link UI
on('providerLinkIndicator', 'click', () => {
    if (!activeChar) return;
    const indicator = document.getElementById('providerLinkIndicator');
    const linkedProviderId = indicator?.dataset?.providerId;
    const registry = window.ProviderRegistry;

    if (linkedProviderId && registry) {
        const provider = registry.getProvider(linkedProviderId);
        if (provider?.openLinkUI) {
            provider.openLinkUI(activeChar);
            return;
        }
    }

    // Linked to a provider that is not registered right now (extension removed or
    // disabled): offer to remove the dormant link instead of the link picker
    const orphanNs = indicator?.dataset?.orphanNs;
    if (orphanNs) {
        unlinkOrphanedNamespace(activeChar, orphanNs);
        return;
    }

    openProviderLinkModal();
});

