// ========================================
// CORE API BRIDGE - DO NOT USE DIRECTLY FROM MODULES
// The window.* bridge between library.js and core-api.js; modules import CoreAPI, never this.
// ========================================

// Global Escape closes the overlay painted on top: a descendant over its ancestor, then higher
// z-index, then later DOM order; tiers are back's.
function _overlayZIndex(el) {
    const z = parseInt(getComputedStyle(el).zIndex, 10);
    return Number.isNaN(z) ? 0 : z;
}

function _overlayIsAbove(a, b) {
    const pos = a.compareDocumentPosition(b);
    if (pos & Node.DOCUMENT_POSITION_CONTAINED_BY) return false; // b nested in a, so b paints above
    if (pos & Node.DOCUMENT_POSITION_CONTAINS) return true;      // a nested in b, so a paints above
    const za = _overlayZIndex(a), zb = _overlayZIndex(b);
    if (za !== zb) return za > zb;
    return !!(pos & Node.DOCUMENT_POSITION_PRECEDING);           // b precedes a in DOM, so a is later/on top
}

function _isOverlayVisible(reg, el) {
    return reg.visible
        ? reg.visible(el)
        : el.classList.contains('cl-modal')
            ? el.classList.contains('visible')
            : !el.classList.contains('hidden');
}

function getTopmostOverlay() {
    let top = null;
    for (const reg of (window._overlayRegistry || [])) {
        if (reg.escape === false) continue;
        const el = document.getElementById(reg.id);
        if (!el || !_isOverlayVisible(reg, el)) continue;
        if (!top || _overlayIsAbove(el, top.el)) top = { reg, el };
    }
    return top;
}

// Whether any registered overlay is open, the ids in except aside (a bar that is itself registered).
function hasOpenOverlay(except = []) {
    for (const reg of (window._overlayRegistry || [])) {
        if (except.includes(reg.id)) continue;
        const el = document.getElementById(reg.id);
        if (el && _isOverlayVisible(reg, el)) return true;
    }
    return false;
}

document.addEventListener('keydown', (e) => {
    // Shift+Escape is the conversation's stop, never a close
    if (e.key !== 'Escape' || e.shiftKey) return;
    const top = getTopmostOverlay();
    if (top) {
        e.stopPropagation();
        // a view is no dialog: Escape in one of its fields leaves the field, the next one closes the view
        if (top.reg.viewLevel && top.el.contains(e.target) && e.target.matches?.('input, textarea, select, [contenteditable], [contenteditable="true"]')) {
            e.target.blur();
            return;
        }
        top.reg.close(top.el);
    }
}, true);
window.hasOpenOverlay = hasOpenOverlay;
window.overlayIsAbove = _overlayIsAbove;
window.isOverlayVisible = _isOverlayVisible;

