// ========================================
// WORLD INFO API
// ========================================

/**
 * The primary linked world (the head of char_worlds), from the server; null when none or unread,
 * never guessed by the embedded book's name.
 * @param {string} charId - character uuid
 * @returns {Promise<string|null>}
 */
async function getCharacterWorldName(charId) {
    const books = await getCharLinkedLorebooks(charId);
    return books?.[0] ?? null;
}

/**
 * Fetch a lorebook from GET /api/worlds/{name}
 * @param {string} worldName - The world name to fetch
 * @param {{ throwUnread?: boolean }} [opts] - throwUnread: a failure other than a missing book throws, since unread is not absent
 * @returns {Promise<Object|null>} World info data { entries: {uid: entry, ...}, ...meta } or null
 */
async function getWorldInfoData(worldName, { throwUnread = false } = {}) {
    if (!worldName) return null;
    try {
        const response = await apiRequest(`/worlds/${encodeURIComponent(worldName)}`, 'GET');
        if (response.ok) {
            const world = await response.json();
            return world?.data ?? null;
        }
        if (response.status === 404) return null;
        throw new Error(`the lorebook could not be read (${response.status})`);
    } catch (error) {
        console.error('[getWorldInfoData] Error:', error);
        if (throwUnread) throw error;
        return null;
    }
}

/**
 * Save a lorebook via PUT /api/worlds/{name}
 * @param {string} worldName - The world name to save
 * @param {Object} data - World info data object
 * @returns {Promise<boolean>} Success
 */
async function saveWorldInfoData(worldName, data, source = '') {
    if (!worldName || !data) return false;
    try {
        const response = await apiRequest(`/worlds/${encodeURIComponent(worldName)}`, 'PUT', data);
        if (response.ok) notifyWorldsChanged(worldName, source);
        return response.ok;
    } catch (error) {
        console.error('[saveWorldInfoData] Error:', error);
        return false;
    }
}

// The ONE shelf reader every picker uses; placeholders follow loreShowPlaceholders unless asked for
// 'all' (the manager, name-collision checks).
/**
 * Lists the world files on the server, the shelf walked a page at a time; file_id is the key, name
 * the in-file title.
 * @returns {Promise<Array<{file_id: string, name: string, extensions: Object}>|null>} null when the shelf could not be read (unknown is not empty)
 */
async function listWorldInfoFiles({ placeholders = 'setting' } = {}) {
    const showPlaceholders = placeholders === 'all' || getSetting('loreShowPlaceholders') === true;
    try {
        const rows = await fetchAllPages('/worlds', showPlaceholders ? { count: 'false' } : { placeholders: 'false', count: 'false' });
        // worlds are name-keyed rows now; file_id === name keeps consumers happy
        return rows.map(w => ({ file_id: w.name, name: w.name, entryCount: w.entryCount, placeholder: !!w.placeholder, createdAt: w.createdAt, updatedAt: w.updatedAt, extensions: {} }))
            .filter(e => e.file_id);
    } catch (error) {
        console.error('[listWorldInfoFiles] Error:', error);
    }
    return null;
}

/**
 * Creates a lorebook, never writes over one: the server refuses a taken name (expect 'absent') or a
 * fill of a non-placeholder (expect 'placeholder').
 * @returns {Promise<'created'|'exists'|null>} null when the write failed
 */
async function createWorldInfoData(worldName, worldData, { expect = 'absent', source = '' } = {}) {
    if (!worldName || !worldData || typeof worldData !== 'object') return null;
    try {
        const response = await apiRequest(`/worlds/${encodeURIComponent(worldName)}?expect=${encodeURIComponent(expect)}`, 'PUT', worldData);
        if (response.status === 409) return 'exists';
        if (!response.ok) return null;
        notifyWorldsChanged(worldName, source);
        return 'created';
    } catch (error) {
        console.error('[createWorldInfoData] Error:', error);
        return null;
    }
}

/**
 * Create a new (empty) lorebook; false when the name is taken or the write failed.
 * @param {string} worldName
 * @returns {Promise<boolean>} Success
 */
async function createWorldInfo(worldName) {
    if (!worldName) return false;
    return (await createWorldInfoData(worldName, { entries: {} })) === 'created';
}

// The live advanced rules naming a book follow its rename (null: its delete), as the server carried the saved presets
function renameActiveBookRules(oldName, newName) {
    if (remapAdvFilterRules(ADV_LOREBOOK_RULE_FIELDS, renamedName(oldName, newName))) triggerAdvFilterSearch();
}

/**
 * Deletes a lorebook; the server cascades entries and bindings and answers how many bindings went.
 * @param {string} worldName
 * @returns {Promise<{ok: true, unbound: number}|false>}
 */
async function deleteWorldInfo(worldName) {
    if (!worldName) return false;
    try {
        const response = await apiRequest(`/worlds/${encodeURIComponent(worldName)}`, 'DELETE');
        if (!response.ok) return false;
        const out = await response.json().catch(() => ({}));
        notifyWorldsChanged(worldName);
        renameActiveBookRules(worldName, null);
        return { ok: true, unbound: Number(out?.unbound) || 0 };
    } catch (error) {
        console.error('[deleteWorldInfo] Error:', error);
        return false;
    }
}

/**
 * Renames a world in one transaction (row, entries, bindings), refusing a taken name (409); answers
 * the re-pointed binding count.
 * @param {string} oldName
 * @param {string} newName
 * @returns {Promise<{touched: number}|false>}
 */
async function renameWorldInfo(oldName, newName, source = '') {
    const to = typeof newName === 'string' ? newName.trim() : '';
    if (!oldName || !to || oldName === to) return false;
    try {
        const resp = await apiRequest(`/worlds/${encodeURIComponent(oldName)}/rename`, 'POST', { to });
        if (!resp.ok) {
            console.warn('[WorldInfo] rename refused:', resp.status, await resp.text().catch(() => ''));
            return false;
        }
        const out = await resp.json();
        notifyWorldsChanged(null, source);
        renameActiveBookRules(oldName, to);
        return { touched: Number(out?.touched) || 0 };
    } catch (e) {
        console.error('[WorldInfo] rename failed:', e);
        return false;
    }
}

// ========================================
// Linked character lorebooks (char_worlds)
// ========================================

// A character has N linked lorebooks: one ordered server-side list (char_worlds).
// The HEAD of the list is what exported cards carry as extensions.world.

// The link-list key is the character uuid.
async function fetchCharWorlds(key) {
    const resp = await apiRequest(`/characters/${encodeURIComponent(key)}/worlds`, 'GET');
    if (!resp.ok) return null;
    const list = await resp.json();
    return Array.isArray(list) ? list : null;
}


/**
 * The character's linked lorebooks, the whole ordered list (the head is extensions.world on
 * export); null when unread.
 * @param {string} charId - character uuid
 * @returns {Promise<string[]|null>}
 */
async function getCharLinkedLorebooks(charId) {
    if (!charId) return [];
    try {
        const list = await fetchCharWorlds(charId);
        return list ? [...new Set(list)] : null;
    } catch { return null; }
}

// ========================================
// World-binding mutations (char / global / persona)
// ========================================

// Every link/unlink is an atomic server-side apply, no list read first: a failed read would invent
// an empty list over real bindings.

/**
 * Add/remove lorebook links on one character or a set, a transaction a chunk of IDS_CHUNK (appends land after the tail), announced once.
 * @param {string|string[]} charIds
 * @param {{add?: string[], remove?: string[], source?: string}} delta
 * @param {{detail?: boolean}} [opts] detail answers { ok, deltas, error } instead of the boolean
 * @returns {Promise<boolean|{ok: boolean, deltas: Array, error: string|null}>} deltas: the chunks that landed, a refused one's included in none
 */
async function applyCharWorlds(charIds, { add = [], remove = [], source = '' } = {}, { detail = false } = {}) {
    const ids = Array.isArray(charIds) ? charIds : [charIds];
    const answer = (ok, deltas = [], error = null) => (detail ? { ok, deltas, error } : ok);
    if (!ids.length || !ids.every(Boolean) || (!add.length && !remove.length)) return answer(false, [], 'nothing to apply');
    const deltas = [];
    let error = null;
    let answered = false;
    for (let at = 0; at < ids.length && !error; at += IDS_CHUNK) {
        try {
            const out = await readAnswer(await apiRequest('/char-worlds/apply', 'POST', { charIds: ids.slice(at, at + IDS_CHUNK), add, remove }));
            if (out?.ok !== true) { error = 'the server did not apply it'; break; }
            answered = true;
            for (const d of Array.isArray(out.deltas) ? out.deltas : []) deltas.push(d);
        } catch (err) {
            error = err?.message || 'the server did not answer';
        }
    }
    // what the chunks before a refused one wrote stands, so it is announced and answered beside the refusal
    if (answered) notifyWorldsChanged(null, source);
    return answer(!error, deltas, error);
}

/**
 * Add/remove books on the global list.
 * @param {{add?: string[], remove?: string[]}} delta
 * @returns {Promise<boolean>} Success
 */
async function applyGlobalWorlds({ add = [], remove = [] } = {}) {
    if (!add.length && !remove.length) return false;
    try {
        const resp = await apiRequest('/global-worlds/apply', 'POST', { add, remove });
        if (resp.ok) notifyWorldsChanged(null);
        return resp.ok && (await resp.json()).ok === true;
    } catch { return false; }
}

/**
 * Add/remove books on one persona's bound list.
 * @param {string} personaId
 * @param {{add?: string[], remove?: string[]}} delta
 * @returns {Promise<boolean>} Success
 */
async function applyPersonaWorlds(personaId, { add = [], remove = [] } = {}) {
    if (!personaId || (!add.length && !remove.length)) return false;
    try {
        const resp = await apiRequest(`/personas/${encodeURIComponent(personaId)}/worlds/apply`, 'POST', { add, remove });
        if (resp.ok) notifyWorldsChanged(null);
        return resp.ok && (await resp.json()).ok === true;
    } catch { return false; }
}

/**
 * Imports a world from a parsed native { entries } object through the normal PUT, so the caller
 * names the destination.
 * @param {string} worldName - destination name (no .json)
 * @param {Object} worldData - must contain an `entries` object
 * @returns {Promise<boolean>} Success
 */
async function importWorldInfoData(worldName, worldData) {
    if (!worldName || !worldData || typeof worldData !== 'object') return false;
    if (!worldData.entries || typeof worldData.entries !== 'object') return false;
    return (await createWorldInfoData(worldName, worldData)) === 'created';
}

/**
 * Announces one character changed, notifyWorldsChanged's sibling: the prompt rebuilds server-side,
 * but a conversation's cached name and avatar go stale.
 * @param {string} charId the character that changed
 * @param {string} [source] who wrote it, so that surface can ignore its own echo
 */
function notifyCharacterChanged(charId, source = '') {
    if (!charId) return;
    document.dispatchEvent(new CustomEvent('cl-character-changed', {
        detail: { charId, source: source || '' },
    }));
}

/**
 * THE single card-write primitive: a char (live ref) or an id; one surgical PATCH of the changed
 * fields, then memory synced.
 * @param {Object|string} charOrId - character object (live ref, mutated in place) or an id string
 * @param {Object<string, *>} fieldUpdates - dot-path keys to values; null or FIELD_DELETE_MARKER deletes.
 * @returns {Promise<{ok: boolean, error?: string, told?: boolean}>} error: the server's words; told: the reader saw them, so add no toast
 */
async function writeCardFields(charOrId, fieldUpdates, opts = {}) {
    const char = charOrId && typeof charOrId === 'object' ? charOrId : null;
    const args = { id: char ? char.id : charOrId, fields: fieldUpdates, rootFields: opts.rootFields, source: opts.source, char };
    return runShellCommand('character.update', args, writeCardFieldsFrom);
}

// character.update's args to the one card write; char is used only while it is still the character
// the args name
function writeCardFieldsFrom({ id, fields, rootFields, source, char } = {}) {
    return writeCardFieldsNow(char && char.id === id ? char : id, fields || {}, { rootFields, source });
}

// The one card write, behind the character.update command (writeCardFields above is its door)
async function writeCardFieldsNow(charOrId, fieldUpdates, opts = {}) {
    let char = charOrId;
    if (typeof charOrId === 'string') {
        char = await ensureCharacterById(charOrId);
        if (!char) {
            console.error('[writeCardFields] Character not found:', charOrId);
            return { ok: false };
        }
    }
    if (!char) {
        console.error('[writeCardFields] No char provided');
        return { ok: false };
    }

    try {
        // Every write is surgical: the PATCH carries only updated fields (null deletes), rootFields the op
        // flags (fav, mediaLocalized, loreDismissed).
        const updates = Object.fromEntries(Object.entries(fieldUpdates).map(([k, v]) => [k, v === FIELD_DELETE_MARKER ? null : v]));
        const fields = {};
        let favUpdate;
        for (const [field, value] of Object.entries(updates)) {
            const mapped = field.startsWith('depth_prompt.') ? 'extensions.' + field : field;
            if (mapped === 'extensions.fav') {
                // fav is a DB column (library metadata, not card content)
                favUpdate = value === true || value === 'true';
                continue;
            }
            fields[mapped] = value;
        }
        if (opts.rootFields && 'fav' in opts.rootFields) {
            favUpdate = opts.rootFields.fav === true || opts.rootFields.fav === 'true';
        }
        // the other two op-state columns: same coercion, same root-level wire slot
        const flagUpdates = {};
        for (const flag of ['mediaLocalized', 'loreDismissed']) {
            if (opts.rootFields && flag in opts.rootFields) flagUpdates[flag] = opts.rootFields[flag] === true || opts.rootFields[flag] === 'true';
        }

        const body = {};
        if (Object.keys(fields).length) body.fields = fields;
        if (favUpdate !== undefined) body.fav = favUpdate;
        Object.assign(body, flagUpdates);
        if (!Object.keys(body).length) return { ok: true };

        const response = await apiRequest(`/characters/${encodeURIComponent(char.id)}`, 'PATCH', body);
        // spelled here, not readAnswer: a refusal is a verdict ({ ok: false }) the batch callers fold, never a throw
        if (!response.ok) {
            const error = (await response.json?.().catch(() => null))?.error || `HTTP ${response.status}`;
            console.error('[writeCardFields] API error:', response.status, error, Object.keys(fields));
            // a refusal names what it refused: the reader sees the server's words once (a batch folded into one
            // toast), memory left as is
            const told = response.status === 400;
            if (told) showToast(`Not saved: ${error}`, 'error', 8000, { group: 'card-write-refused', item: error, many: summarizeCardRefusals });
            return { ok: false, error, told };
        }

        const setNestedValue = (obj, path, value) => {
            const keys = path.split('.');
            const lastKey = keys.pop();
            const target = keys.reduce((o, k) => {
                if (o[k] == null) o[k] = {};
                return o[k];
            }, obj);
            if (value === null || value === undefined) delete target[lastKey];
            else target[lastKey] = value;
        };
        const getNested = (obj, path) => path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);

        // The server answers the COMPOSED row, and that lands in memory, never what was sent; the caller's
        // value only when no answer came.
        const updated = typeof response.json === 'function' ? await response.json().catch(() => null) : null;
        const truth = updated?.card?.data || null;
        const favNow = updated && 'fav' in updated ? !!updated.fav : favUpdate;

        // In-memory sync of the passed char and its cache entry (maybe the same ref), per field, so _slim
        // never moves.
        const canonical = _charIndex.get(char.id);
        const crossRef = (canonical && canonical !== char) ? canonical : null;
        const applyFieldsTo = (target) => {
            if (!target.data) target.data = {};
            for (const [field, value] of Object.entries(fields)) {
                setNestedValue(target.data, field, truth ? getNested(truth, field) : value);
            }
            if (truth && Array.isArray(truth.tags)) { target.tags = truth.tags.slice(); target.data.tags = truth.tags.slice(); }
            if (truth && typeof truth.name === 'string') { target.name = truth.name; target.data.name = truth.name; }
            if (favNow !== undefined) {
                // keep the extensions mirror alive for readers still on extensions.fav
                if (!target.data.extensions) target.data.extensions = {};
                target.data.extensions.fav = favNow;
                target.fav = favNow;
            }
            for (const [flag, v] of Object.entries(flagUpdates)) target[flag] = updated && flag in updated ? !!updated[flag] : v;
        };
        applyFieldsTo(char);
        if (crossRef) applyFieldsTo(crossRef);
        const syncRootFields = (target) => {
            for (const [field, value] of Object.entries(updates)) {
                if (field.includes('.')) continue;
                target[field] = truth && field in truth ? truth[field] : value;
            }
        };
        syncRootFields(char);
        if (crossRef) syncRootFields(crossRef);
        // the post-save refetch restores the cached estimate, so refresh it here; never on a slim char,
        // which would underestimate
        if (TOKEN_ESTIMATE_FIELDS.some(f => f in fieldUpdates) && !char._slim) {
            const tok = computeTokenEstimate(char);
            char._tokenEstimate = tok;
            if (canonical) canonical._tokenEstimate = tok;
            _tokenEstimateCache.set(char.id, tok);
        }

        // The Online In-Library lookup base is keyed on name+creator; a surgical write that
        // changes either must invalidate it (other edit paths refresh via fetchCharacters).
        const touchedNameOrCreator = Object.keys(fieldUpdates).some(
            f => f === 'name' || f === 'creator' || f.endsWith('.name') || f.endsWith('.creator')
        );
        if (touchedNameOrCreator) window.ProviderRegistry?.invalidateBrowseLookupBase?.();

        // THE card write, so the one honest place to say a character changed; anything holding an earlier
        // copy re-reads.
        notifyCharacterChanged(char.id, opts.source);

        return { ok: true };
    } catch (error) {
        console.error('[writeCardFields] Error:', error);
        return { ok: false };
    }
}

// The server takes at most this many updates a batch card write; a longer list goes in chunks, in order
const FIELDS_APPLY_CHUNK = 5000;

/**
 * The batch card write behind character.update-many: a request a chunk of FIELDS_APPLY_CHUNK, in
 * order, refusals by name, changed rows re-read as stored.
 * @param {{id: string, fields: Object<string, *>}[]} updates
 * @returns {Promise<{affected: string[], failed: {id: string, error: string}[]}>}
 * @throws the server's words when it refuses a chunk (saying how many updates were written before it, their answer as `landed`), or the request's own error
 */
async function applyCardFieldsNow(updates) {
    const list = (Array.isArray(updates) ? updates : []).filter(u => u && u.id).map(u => ({ id: String(u.id), fields: u.fields || {} }));
    if (!list.length) return { affected: [], failed: [] };
    const affected = [], failed = [];
    let refused = null, sent = 0;
    for (let at = 0; at < list.length; at += FIELDS_APPLY_CHUNK) {
        try {
            const resp = await apiRequest('/characters/fields-apply', 'POST', { updates: list.slice(at, at + FIELDS_APPLY_CHUNK) });
            const result = await readAnswer(resp);
            if (!result) throw new Error(`server returned ${resp.status} with no answer`);
            for (const id of result.affected || []) affected.push(id);
            for (const f of result.failed || []) failed.push(f);
            sent = Math.min(at + FIELDS_APPLY_CHUNK, list.length);
        } catch (e) {
            refused = e;
            break;
        }
    }
    if (refused && !sent) throw refused;
    // what the chunks before a refused one wrote stands, so it is re-read and announced before the refusal is thrown
    if (affected.length) {
        await fetchCharactersByIds(affected);
        for (const id of affected) notifyCharacterChanged(id);
    }
    // the rows the server refused say why, once, the way a single card write does
    if (failed.length) showToast(summarizeCardRefusals(failed.map(f => f.error || 'not saved')), 'error', 8000);
    if (refused) {
        refused.message = `${refused.message} (${sent} of ${list.length} were written before it)`;
        // a caller counts per id from what the chunks before it answered
        refused.landed = { affected, failed };
        throw refused;
    }
    return { affected, failed };
}

// A card write that didnt land, as an Error; told rides along so a catch that toasts stays quiet
function cardWriteError(result, message) {
    return Object.assign(new Error(message), { told: !!result?.told });
}

// A batch of refused card writes (a tag run, a bulk edit) says them in one toast: how many,
// and the distinct reasons
function summarizeCardRefusals(reasons) {
    const distinct = [...new Set(reasons)];
    const more = distinct.length > 2 ? ` (and ${distinct.length - 2} other reasons)` : '';
    return `${reasons.length} writes not saved: ${distinct.slice(0, 2).join('; ')}${more}`;
}

window.writeCardFields = writeCardFields;

// Expose allCharacters as a getter so CoreAPI always gets current value
Object.defineProperty(window, 'allCharacters', {
    get: () => allCharacters,
    configurable: true
});

// Expose currentCharacters as a getter for filtered/displayed characters
Object.defineProperty(window, 'currentCharacters', {
    get: () => currentCharacters,
    configurable: true
});

// Expose activeChar with getter/setter for CoreAPI (used by openProviderLinkModal)
Object.defineProperty(window, 'activeChar', {
    get: () => activeChar,
    set: (char) => { activeChar = char; },
    configurable: true
});

